/* 平成16年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h16.committeeSessions.push(...[{"id":"h16-20041013-4","meetingId":"h16-c-settlement","date":"2004年10月13日","dateIso":"2004-10-13","committee":"決算特別委員会","time":"午前１０時０４分～午後６時０２分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を146件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"○午前１０時０４分開会 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成１５年度品川区一般会計歳入歳出決算","agenda":"○午前１０時０４分開会 おはようございます。ただいまより決算特別委員会を開会いたします。 それでは、平成１５年度品川区一般会計歳入歳出決算","exchanges":[{"speaker":"大沢委員","kind":"質問","question":"おはようあります。私は、今日は４５ページの学校改築の推進、１６１ページの生涯学習についてお伺いをしたいと思います。最初に、１６１ページの生涯学習のほうからお伺いをしたいと思います。大きな流れの中で、学校、家庭、社会という区分による社会教育の概念があります。","respondent":"上川内生涯学習課長","answer":"生涯学習の基本的な考え方ですが、全般的に言いますと、学校教育も含めた概念ですが、品川区の生涯学習としましては、私どもの事業のところでは学校教育を除いた生涯学習ということですが、区民が自発的意思に基づいて日々の生活の中で日常的に豊かにしていくための。","voiceIndex":4,"id":"exchange-001"},{"speaker":"大沢委員","kind":"質問","question":"そうしますと，学校教育、いわゆる補助教育に代わる継続的な教育というふうな捉え方をしてよろしいわけでしょうか。","respondent":"上川内生涯学習課長","answer":"委員おっしゃるとおりです。","voiceIndex":6,"id":"exchange-002"},{"speaker":"大沢委員","kind":"意見","question":"生涯学習教育の中で、いろいろな自治体においてさまざまな取り組みにおける外側からの支援があると思いますけれども、まず品川区の支援ならびに教育委員会の支援についてどのようなものがあるか、その中には支援の対象とすれば、この中に書いてあります社会教育委員、そしてまた青少年委員、ジュニア・リーダー、体育指導員などがありますが、そのほかに顕著なもの、このような後方援護といいますか。","respondent":"上川内生涯学習課長","answer":"支援体制という中で、人的な支援という観点のご質問だと思いますが、さまざまな附属機関に委嘱したり、お願いしている青少年委員、それから、体育指導員があります。そのほかにも歴史館の専門委員、それから、地域の方のスポレク推進委員等があります。","voiceIndex":8,"id":"exchange-003"},{"speaker":"大沢委員","kind":"意見","question":"私は、もうちょっとあるかと思ったんですけれども、人的な資源、社会資源として、スポーツ施設なり、支援体制の一環として人的なもの、物的なものがあると思うんですが、またちょっと思いつきましたら、補足でお願いしたいと思います。","respondent":"上川内生涯学習課長","answer":"機会の提供としましては、さまざまな事業をすることによる支援を行っております。その周りにボランティア等、周辺にさまざまな方たちが支援をしてくださる方たちのネットワークがつくられております。","voiceIndex":10,"id":"exchange-004"},{"speaker":"大沢委員","kind":"質問","question":"今おっしゃったように、逆に、受け止め側の学習効果の成果を活用するような場が大いに必要だと私は思うんですけれども、場について、成果を発揮するような場所、例えばどのようなところにあるとお考えになりますでしょうか。","respondent":"上川内生涯学習課長","answer":"成果につきましては、さまざまな地域の中のことがあると思いますが、私どもとしまして、現在すまいるスクールが全校展開してまいります。地域の方たちの協力というものが大きな力になっていくと考えています。","voiceIndex":14,"id":"exchange-005"},{"speaker":"大沢委員","kind":"質問・要望","question":"シルバー人材センターを通して歴史館のもろもろの事業、いろいろなところで活用しているということですけれども、差し当たりまして、成人する時期と、成人期においては自己表現としての生涯学習の成果が大事なことで、また高齢期においては、今まさにおっしゃったように、生きがいとして、また自分が自分たらんとする認識を得ることができる手段としての生涯学習の成果を求めるものだと私は思いますので。","respondent":"市川庶務課長","answer":"去る７月ですけれども、地元町会、ＰＴＡ、小山小学校の同窓会、小山小学校の関係者、それと教育委員会の関係者によりまして、改築検討会を組織いたしました。その後、７月から現在に至るまで４回ほど検討会を重ねてきてあります。","voiceIndex":16,"id":"exchange-006"},{"speaker":"大沢委員","kind":"意見","question":"思い起こせば、私が小山小学校に行っていた頃ちょうど改築がありました。そのようなことも私の思いの中でありますので、改築は学校にとって一大事、何十年に１回の大きな行事であります。子どもたちにもなお一層よりよい学習環境、そしてよりよい居場所になるように、そして地域の方に十分なコンセンサス、理解が得られるように説明を十分していただくことをお願いいたしまして、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":18,"id":"exchange-007"},{"speaker":"若林委員","kind":"意見","question":"成果報告書の１６６ページの歴史館、１５５ページの学校図書、１５４ページの学校管理、３点行いたいと思います。歴史館のほうです。端的に、品川区のほうでさまざまな歴史的なといいますか、地域的な、郷土的な資料の購入、または寄贈を受けているかと思います。そこら辺の現状の収蔵の資料の現状にはどのようなものがあるか、また、その資料の活用方法も併せて簡潔にお知らせ願いたいと思います。","respondent":"上川内生涯学習課長","answer":"歴史館にはさまざまな収蔵物がありますが、資料の点数については、浮世絵が約６００点、地図が１,０００点、民族資料が２万点あります。活用ですが、巡回展というのを年に１回、文化センターをめぐりながら、歴史館のほうに来られない方たちに対して展示をする。","voiceIndex":20,"id":"exchange-008"},{"speaker":"若林委員","kind":"意見","question":"巡回展が年１回、また、常設ではないコーナー展をやられているということで、基本的には、ここでは資料の管理等についてお尋ねをしたいんですが、平成１４年に新宿区の歴史博物館のほうの、いわゆる区の職員が絡んだ盗難事件がございました。３点挙げますので、それぞれ区の管理、現状はどうなっているか、それだけお知らせ願えればと思います。これが１点目です。これが２点目の指摘です。","respondent":"上川内生涯学習課長","answer":"その鍵については、副館長が鍵を持っていてチェックをする。それから、鍵の管理をきちんとしまして、収蔵物の台帳の管理は１カ月に１回チェックをしていく。そこに入った、入らないというものも、副館長がチェックをしていくということを現場と確認をさせていただきました。","voiceIndex":22,"id":"exchange-009"},{"speaker":"若林委員","kind":"意見","question":"新宿区側には物はあったけれども、明確な一覧がなかったというと、ちょっと違う言い方になりますけれども、その照らし合わせがうまくできなかった。カードタイプなどのデータ化が現状行われているのかどうか。要するに、ちゃんとチェックができる、１カ月ごとにチェックをしているというお答えが今ございましたけれども、その上での資料としての確固たる基盤があるかどうか、それだけお願いいたします。","respondent":"上川内生涯学習課長","answer":"その認識は多く持っておりまして、今、紙で管理しておりますが、これからデータ管理にするように今検討を進めているところです。","voiceIndex":24,"id":"exchange-010"},{"speaker":"若林委員","kind":"提案","question":"ぜひともよろしくお願いいたします。続きまして、１５５ページの学校図書に関連をいたしまして、朝の読書運動です。それとともに、昨年文化審議会のほうで、小・中・高のカリキュラムの中に読書の時間を組み込もうではないかというようなご提案があったというふうに聞いておりますけれども、この国の動きの、いわゆるカリキュラムに組み込む動向が分かりましたらお知らせ願いたいと思います。","respondent":"中島指導課長","answer":"平成１５年度の状況では、朝の読書時間を設定している小学校が２８校、中学校は１１校、これは時間設定ですけれども、そういった形で導入をしております。その他読書週間とか、読書月間、さまざまな形で読書時間の確保を何らかの形で実施をしているというのが現状です。","voiceIndex":26,"id":"exchange-011"},{"speaker":"若林委員","kind":"質問","question":"そこで、今回の決算ですが、もともと朝の読書運動の流れは、平成１３年１２月に子ども読書活動推進法というのが施行されて、平成１４年から５年間という限りの中で、毎年１３０億円、国の交付税として、一般財源としておりているというふうに伺っております。全国的に見ても、この法律ができてから、また、施行を受けてから、図書の予算の増をした自治体が２割から３割程度にとどまっている。","respondent":"谷田部学務課長","answer":"平成１５年度は、そういうことがありましたので、この決算では約２,５００万円程度ですが、これからも読書活動を推進する上で、図書整備費につきましては重点を置いていきたいというふうに考えてあります。","voiceIndex":28,"id":"exchange-012"},{"speaker":"若林委員","kind":"質問・要望","question":"これは朝の読書がどうとか、つながりは別にございませんが、学級の中で落ち着きのないとかというような子どもたちがどうしても介助員を必要とする。この介助員の考え方、一般質問の中でもちらっとあったような気がしますが、基本的な介助員の付け方といいますか、そこら辺をもう一回基本的なところを確認させていただきたいと思います。","respondent":"谷田部学務課長","answer":"介助員の付け方も、１日べたで付ける全部介助、それから、部分的な介助というふうな分け方で、緻密にその子の状態に応じて配置しているというものです。","voiceIndex":32,"id":"exchange-013"},{"speaker":"若林委員","kind":"意見","question":"発達障害児等の問題ですが、一つは、学校の中で付けて、親御さんには基本的にはあえて知らせないというような基本的な考え方があったと思いますが、これは一つ、親御さんと一定のレベルの認識、学校ではこうやっていますよ、家庭ではこうやっていますよというような、意思疎通とか、話し合いというのが、私はどうしても必要ではないのかなというふうに単純に思いましたので。","respondent":"谷田部学務課長","answer":"介助員を付けるか、付けないかの、お知らせするのはこれはあくまでも学級経営上、あの子に大人の方が付いているのかというのは、ほかのお子さんからいろいろ家庭のほうに情報として伝わりますので、その辺はきめ細かく学級担任のほうから各児童には。","voiceIndex":34,"id":"exchange-014"},{"speaker":"若林委員","kind":"質問","question":"最後の１点だけ、昨年の第３回定例会の一般質問でも問いかけをいたしましたが、特別支援教育の検討委員会が設置をされておりますが、これからの見通し、中間のまとめなどいつ出されるか等簡単にお願いできればと思います。","respondent":"谷田部学務課長","answer":"その関係で私どもも勉強会を通じまして、いろいろこれからの方向性について勉強を重ね、今年の９月ですけれども、中央教育審議会のほうの動きもありましたので、９月に私どもは検討委員会を立ち上げいたしまして、品川区立小中学校における特別支援教育のあり方について。","voiceIndex":36,"id":"exchange-015"},{"speaker":"大西委員","kind":"質問・要望","question":"すまいるスクールについてでありますが、本年夏休みにおいての、おやつの問題が文教委員会等で随分議論されたところでありましたが、この間教育委員会として、おやつは特定の子ども、要するに、親が希望する子どもについてはおやつを持たせるという判断をされたようですが、それに至った経緯、また、すまいるスクールが拡大しているわけですけれども、保護者の皆さんから、すまいるスクールを実施していて。","respondent":"富田教育改革担当課長、上川内生涯学習課長、中島指導課長、谷田部学務課長","answer":"続きまして、保護者からのご要望ですが、開設前には昨今の子どもたちをめぐる動きから、安全、安心へのご心配、受け付けですとか。歴史館につきましては、展示場というのはかなり高額なところでもありますし。極力不利益にならないような形で私どもも対応をしてまいりたいと考えています。冬場、いわゆる全校で移動教室みたいなものをスキーでやったらどうかというようなご提案ですが、また、そのようなことは、小学校の校長会、それから。","voiceIndex":39,"id":"exchange-016"},{"speaker":"大西委員","kind":"提案","question":"この点に関して、私は以前、広報広聴課のほうでお子さんたちが不用になったものを引き取って、それを日光のほうに寄贈してもらうという形でその後の利用者の負担を軽減されるような形に持っていったらどうかということを１点提案したこともありますので、今後の教育委員会の活動の中で組み込んでいただければ組み込んでいただきたいと思います。歴史館の問題だけについて答弁をお願いします。","respondent":"上川内生涯学習課長","answer":"歴史館につきましては、条例規則に則ってやってありますが、受益者負担という部分は、お子さんについても同じです。そういう意味で子ども料金ということを設定して、大人の４分の１から２分の１程度の金額を設定しています。","voiceIndex":44,"id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"私は、１５３ページ、教育総務費の中の、教育指導費からプラン２１の関連です。それから、学校教育費の中から、幼稚園費、この２点でお聞きしたいと思います。幼稚園費のほうからお聞かせいただきたいと思います。非常にすばらしい幼保一元の施設だなと思っていたんですが、これから品川区立幼稚園の方向性というのはどういうふうに考えていくのかなということでお聞きをしたいと思います。","respondent":"谷田部学務課長","answer":"一方、国におきましては、就学前の総合施設の検討というのが、中央教育審議会の幼児教育部会と、厚生労働省所管の社会保障審議会児童部会との合同の検討が始まっているということで、１１月には最終的な報告が出されるというふうに伺ってあります。","voiceIndex":47,"id":"exchange-018"},{"speaker":"鈴木（真）委員","kind":"意見","question":"逆に、品川区の中の保育園行政、保育園業務との問題も絡んでくると思いますが、私立の動きと、区立幼稚園の動きというのはどう考えていったらいいのか。一つは、総務部から今度は児童保健事業部に私立幼稚園の担当も変わっていったというところも踏まえて、どのようなお考えか、その辺もお願いしたいと思います。","respondent":"濱野助役","answer":"一方で、幼保の融合化ということ、子どもたちにとっても大変に重要な問題であるという認識から、それでは区立の施設の中でこのことを実現していこうということで今取り組んでいるわけであります。","voiceIndex":49,"id":"exchange-019"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"区立幼稚園で言うと、二葉幼稚園の場合には施設的に余裕があった状況と、園児の数も少なかったという点もあるんですけれども、例えばこれから先ほかの残り８園の施設改築という方向性が出てくるのかなという、その辺だけお答えいただきたいと思います。","respondent":"谷田部学務課長","answer":"二葉幼稚園以外８園の関係ですけれども、先ほども申し上げましたけれども、これから幼保の融合に向けての検討ということが見えてまいりますので、具体的にどうのこうのというのはまだ詰まっていないという段階です。","voiceIndex":51,"id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"意見","question":"プラン２１のほうに入らせてもらいます。今年の夏にサマースクールがかなりの学校で実施されていたと思います。これはどのぐらいの学校が実施されていたのか、多分全校かなと思うんですが、その効果と、サマースクールに関しては、教育委員会からの指導があったのかどうか、そこら辺をお願いしたいと思います。","respondent":"中島指導課長","answer":"本年度の夏の状況ですけれども、これは全校で実施されてあります。平成１５年度の段階では小学校において３７校、中学校において１８校という状況でございました。","voiceIndex":53,"id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"意見","question":"もちろん別の意味で、児童センターの中にも生徒がいろいろなボランティアスタッフで出ていたということも聞いておりますけれども、学校の中のアシスタントティーチャーの取り組みというのは、これは学校独自の対応なのか、教育委員会としてある程度そういう形を進めていったのか、その点をお答えをお願いしたいと思います。","respondent":"中島指導課長","answer":"これは基本的には学校独自の取り組みという形になります。もちろん教員が指導に当たるわけですけれども、保護者の方にご協力をいただくとか、大学生、高校生、これは主に卒業生が多いみたいですけれども、そういった学生がボランティアで入ってくるというケースがあるようです。","voiceIndex":55,"id":"exchange-022"},{"speaker":"鈴木（真）委員","kind":"質問","question":"ただ、その中で、中学校からすると、少し費用が欲しかったみたいな感じをちょっと聞いたんです。行かせるための準備段階の時間とか、ある程度資料とかかかってしまう、こういうのに対しては教育委員会としてはある程度援助をすることができるかどうかという点をお聞きしたいと思います。","respondent":"中島指導課長","answer":"今後学校のほうでそういう取り組みの拡大の状況があれば、相談に応じていきたいなとは考えてあります。","voiceIndex":57,"id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"逆に、こういう形を教育委員会としても全校までは難しいかもしれませんけれども、こういういい結果が出ているのがあるよということも広めていただきたいと思うし、小学生と中学生が一緒になることによって、前に教育長が言っていた、小学校から中学校に行くのに階段をなだらな坂にする、そのステップの一歩になると思うんですが、その辺で考え方としてはどうでしょうか。","respondent":"中島指導課長","answer":"委員のご指摘のとおりだと考えております。日常から小学生と中学生がさまざまな縦の交流の関係をつくっていくということは非常に重要な部分でありますし、小中一貫教育の中でもそういった交流活動は大変重視していきたいと考えているところです。","voiceIndex":59,"id":"exchange-024"},{"speaker":"鈴木（真）委員","kind":"意見","question":"最後に、小中一貫教育、プラン２１すべてを含めて、品川区の進んでいる状況を踏まえてということだと思うんです。先日、第三日野小学校の校長先生が佐賀市の教育長に就任なさったという報道がありました。ただ、今度の教育長にとってはすばらしい場を与えられたと思うんですが、その辺のところを踏まえると、教育長として、品川区のプラン２１を認められているかということについて、お考えをお願いします。","respondent":"若月教育長","answer":"ただいまの委員のご指摘ですけれども、本区で活躍をした校長が認めてもらえたということは、私どもにとっても大変誇りでありますし、品川区の誇りであると、私はそう考えております。そういう優秀な方が今までプラン２１を一生懸命進めてきました。","voiceIndex":61,"id":"exchange-025"},{"speaker":"南委員","kind":"質問・要望","question":"というのは、すまいるスクールに学童保育クラブ機能を移行させるという点については、親たちからの強い要望の一つでもあったというふうに私は思っていますので、改めておやつを持ち込んで来ることを可能にした、その辺の品川区側の見解を伺いたいと思います。したがって、子どもの意見を取り入れていくという点について、教育委員会としてどういうふうに認識をしていらっしゃるか、改めて伺いたいと思います。","respondent":"富田教育改革担当課長、高橋区長","answer":"学校施設としておやつの持ち込みを認める考えはないというところにも何ら変更はございません。したがいまして、タウンミーティングの場合もありますし、また今出ました、子ども議会を開くことも一つの方法だと考えています。この問題につきましては、これからも検討をしてまいりますので、よろしくお願い申し上げます。","voiceIndex":64,"id":"exchange-026"},{"speaker":"南委員","kind":"提案","question":"国連子どもの権利委員会が日本の政府に対して、とりわけ１２条の意見表明権について、子ども国会の開催を提案したりとかしておりまして、またそれだけでなく、日本の過度な競争教育がもたらす発達のゆがみ、それから、よく遊びなどの欠如、不登校として高度にストレスにさらされていると、その結果、余暇とか身体的な活動および休息を欠くに至っているために。","respondent":"富田教育改革担当課長、中島指導課長","answer":"そういったところを踏まえまして来年の夏休みにどうするかということについては、来年間に合う時期までに検討をしてまいりたいと考えています。教育委員会といたしましても、先ほど区長から答弁がございましたように、今後また子どもたちの意見を聞く機会等を検討していければなと考えています。","voiceIndex":67,"id":"exchange-027"},{"speaker":"南委員","kind":"質問・要望","question":"すまいるスクールのほうのおやつの件ですけれども、施設によって持って来る子、持って来ない子がいたということと、持って来ない子のほうが多かった。習熟度別というのはもっと配慮されていいんじゃないかというふうに思うんですけれども、そういう点で品川区のプラン２１の中はなかなかそういう配慮というのは見えないというふうに私は思いますので、その点についての見解を改めて伺いたいと思います。","respondent":"古川教育次長、若月教育長","answer":"教育委員会はかたくなに、おやつをということではございませんで、今年の夏については柔軟に対応をさせていただいた、このように考えてあります。品川区が今考えているプラン２１は、あるいは習熟度別学習というものも、全く競争のない、のどかな世界において子どもたちを学習させようとするものではありません。まさに今の子どもたちに合った、適度な競争の中で学習をさせていこう。","voiceIndex":70,"id":"exchange-028"},{"speaker":"南委員","kind":"質問・要望","question":"子どもというのは、私以上に教育長は専門家ですからあれですけれども、きちんと締めるところと、解き放すところと、こういうのが生活の中にないとだめだと思うんです。そういう点を見ない答弁だということで、私は子どもをパートナーとして見るのであれば、子どもの発達、子どもの姿というものをもっと見て、そして事業を展開していただきたいということを強く要望して、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-029"},{"speaker":"西本委員","kind":"質問・要望","question":"私のほうからは、１６６ページの歴史館、先ほども何人かの委員からご質問がありましたが、ちょっと確認だけをさせていただきたいと思います。歴史館ですが、先ほど幾つかご質問がありまして、品川区内の小中学校、児童・生徒の利用料というところでは、学校の勉強に関連しているところであれば無料というふうな形でお聞きしたんですが、そういう認識でよろしいのでしょうか。","respondent":"古川教育次長","answer":"学校の先生の引率もあれば、学校の先生からの連絡もあろうかと思いますが、基本的には子どもが歴史館を教育のために利用する場合には、さまざまな手続については簡素化しながら、少なくとも免除できるように今後とも配慮していきたい、このように考えてあります。","voiceIndex":75,"id":"exchange-030"},{"speaker":"西本委員","kind":"質問・要望","question":"それが自分から、自ら行ってみよう、品川区の歴史をもっと知ってみたいというような意識の動機付けには、もうちょっと学校側の声かけ、それから、例えば歴史館のいろいろな催し物があれば、ポスター等をつくられると思いますので、それを区内の小学校のほうに貼り出すとか、先生のほうから、今こういうのをやっているよというような声かけのほうをぜひお願いして、子どもたちに品川区の歴史を知ることで。","respondent":"古川教育次長","answer":"実はこれは私どものほうの学校に対する一定のＰＲが不足していたのかなというふうにも反省してございまして、先日の歳入の際の質疑を捉えまして、６日の日に校長、園長連絡会がございましたので、私のほうから改めて歴史館の活用について各学校がもっと活用できるような手だて。","voiceIndex":77,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問・要望","question":"早速行動に移していただきまして、ありがとうございました。次に、１５５ページのほうの心身障害学級に関して、特別支援教育についてですが、中央教育審議会で今特別支援教育について検討されていると思いますが、国、都の考え方、それから、それに対して品川区はどういうふうに捉えているのか、その辺を教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"国や、各都道府県の取り組みといいますのは、従来の障害種別に応じた学校から障害の重度化、それから、障害の重複化、それに対応する新しい特別支援学校、これはまだ、法律はこれからですので、仮称の特別支援学校というものをつくろうというのが１点目です。","voiceIndex":79,"id":"exchange-032"},{"speaker":"西本委員","kind":"質問","question":"その辺の今まで品川区で行われてきた考え方、心身障害学級も含めて、通常学級の方たちもたくさんおられると思いますので、その方たちの今までの教育に対して、これを始めることによって何か変わるということが起きるのか、そこら辺の品川区に置き替えてみたときの今後の課題というところはいかがでしょうか。","respondent":"谷田部学務課長","answer":"教室の場合についての教員の配置はどうするのかとか、そのような今後検討をしなければならないというような話と、それから、いきなり実施するというのではなくて、ある程度特別支援学校をモデル的に実施をして。","voiceIndex":81,"id":"exchange-033"},{"speaker":"西本委員","kind":"質問","question":"大きな流れとして危惧するところとしては、財源ももちろんありますけれども、専門性というところにおいて、これは財源と非常に密着するところとは思うんですが、通常学級の教師の方たちにさらに特別支援教育に関する専門性をもたせていくという方向性にあるのか、それとも専門的な方たちを別途配置をして対処していくのか、その辺はまだ決まらないとは言っても。","respondent":"谷田部学務課長","answer":"今回特別支援教育という考え方が出てまいりましたのは、障害者基本計画の中で、いわゆる学校教育だけではなくて、医療、福祉、さまざまな専門の方たちの連携によって障害のあるお子さんに対して、就学前で、就学に向けてのつなぎの期間、それから、就学義務教育期間。","voiceIndex":83,"id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"今の状況、これから教育だけではなく、特別支援教育というのは、広い意味で考えていかなければならないだろうというお考えかとは思いますが、東京都のほうからも確たる財源なく、いろいろなことが言われてきてしまっているという状況は、いい政策も現実的ではないというふうに思いますので、今後それも併せて、今まで品川区で培ってきた心身障害学級のメリット、それから。","respondent":"中島指導課長","answer":"それぞれの学校での危機管理体制ですけれども、基本的には平成１４年度に文部科学省が作成いたしました、学校への不審者侵入時の危機管理マニュアルをベースにいたしまして、学校に不審者が侵入した場合のケーススタディですとか、それから。","voiceIndex":85,"id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"関係所管のほうにも連絡体制ができているという状況を確認をさせていただきましたが、もう一つ警察等の関係ですね、それから、内容によっては地域限定もあるでしょうし、それから全域という形もあるかと思うんですけれども、その判断基準はどういう判断基準がされているのかなというところで確認をさせていただきたいと思います。","respondent":"中島指導課長","answer":"学校は警察と連携をとりながら、もう大丈夫だ、または、大丈夫でないというような情報をとって、子どもたちが下校時であるならば、下校を一たん待つですとか、それから、方面別に集団で教師が付き添って下校させるですとか、そういったような体制をとる形になってあります。","voiceIndex":87,"id":"exchange-036"},{"speaker":"西本委員","kind":"質問・要望","question":"連絡体制の中で、一つ、これは小Ｐ連の方たちの要望なんですが、例えば携帯等を持っている親が今は多いものですから、そこに情報が発信できないだろうかというようなご意見もいただきました。","respondent":"市川庶務課長","answer":"今ご提案のあった点につきましては、ただいま品川区全体で近隣セキュリティシステムというものの開発途上でございまして、その中でも、今ご提案のあったようなことも含めて対応ができるかどうか、今後の一つの研究課題にしています。","voiceIndex":89,"id":"exchange-037"},{"speaker":"築舘委員","kind":"質問・要望","question":"それと、幼稚園費のほうですが、先ほど鈴木（真）委員からも質問がありましたけれども、幼保一元化の方向で検討をしていくというような方向性だとは思うんですが、区立幼稚園の意義といいますか、良さというものもあるのではないかというふうに思うんです。その良さというのは、現在どういうふうに考えているかということをお答えいただきたいと思います。","respondent":"市川庶務課長、中島指導課長","answer":"芝生に関連したご質問です。芝生については、これまで主に日常的な管理の問題、あるいは年間を通しての管理の面から、校庭への導入は非常に困難であるということを説明させていただいてまいりました。このような背景をもとに、今後とも幼・小の連携活動につきましては教育委員会としても推進をしていきたい、このように考えているところです。","voiceIndex":93,"id":"exchange-038"},{"speaker":"築舘委員","kind":"質問・要望","question":"それと同時に、区立幼稚園の良さというのは、公立ですので、営利を追求しない幼児教育を提供できるということであり、そしてまた、研究、研修の充実で教員の質が高いと、こういうこととか、地域と協力体制がとりやすいというような、３点ぐらい挙げているんですけれども、実際にそういった幼児教育の充実、大切さというんですかね、そういうのを幼保一元化においても。","respondent":"中島指導課長","answer":"しかしながら、就学前の教育と、小学校、特に低学年との連携の部分は、１年生に入った子どもたちへの対応という部分で、学校としても重点的に取り組んでいる部分でもありますので、先ほどもちょっとご答弁申し上げましたが、公立幼稚園につきましては。","voiceIndex":96,"id":"exchange-039"},{"speaker":"嶋委員","kind":"質問・要望","question":"私のほうから、３点お伺いいたします。初めに、１５３ページの小中一貫教育に関連いたしまして、二つ目には、学校現場での公衆電話について、三つ目には、１５３ページ、プラン２１の外部評価者制度について、時間のある限りお尋ねをいたします。初めに、小中一貫教育に関連してですが、品川区としてもこのたび小中一貫で、市民科を創設されました。その中で、熊本県富合町が小中一貫の特区をとりました。","respondent":"中島指導課長","answer":"熊本の特区の状況は私どもでも資料等で拝見しています。４・３・２のカリキュラムの中で、生き方創造科ですか、こういったような教科を設定していくということで、私どもが想定しております市民科と基本的な考え方は同じにするものではないかなと、このように考えております。","voiceIndex":99,"id":"exchange-040"},{"speaker":"嶋委員","kind":"質問","question":"同じように、将来的に、最後は人づくりといいますか、人によって決まっていくということは同じだと思います。私自身がそうなんですが、そういう意味で、子どもたち、児童・生徒にこれから市民科を訴えていく場合に、低学年に市民科という形のときには、どのような言葉といいますか、ご指導をされていらっしゃるのか、一番最初の４年制についてお伺いいたします。","respondent":"中島指導課長","answer":"行動としましては、例えば自分の係を責任を持ってやっていこうという、１年生の発達段階に合わせた形での行動目標をつくりまして、具体的な活動を通して指導をしていきたい、このように考えてあります。","voiceIndex":101,"id":"exchange-041"},{"speaker":"嶋委員","kind":"質問・要望","question":"品川区は市民科をつくる、決定するまでにいろいろな、何科、何科とあったと思いますが、市民科に続くものが何かあったのか、幾つかもしありましたらお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"小中一貫教育につきましては、その検討当初の段階で道徳、特別活動のほか、市民科の考え方を入れていこうということで、市民科というような検討が具体的に始まったという形です。","voiceIndex":103,"id":"exchange-042"},{"speaker":"嶋委員","kind":"質問・要望","question":"小中一貫に関して、一つの流れ的にいろいろなことになっていくと思いますが、計算特区をとったところがあります。これも一つの大きな、いわゆる算数が苦手、数字をすぐそろばんの目として頭の中に入れる分にはそろばんが大変すばらしいということも認識をされていますが、これから小中一貫の中でそろばんといいますか、数に対する、計算に対するお考えをお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"現在小中一貫教育のカリキュラムの中で、算数、数学を検討しています。その中で具体的にそろばんを使ったような単元を小学校の３年生で位置づけていきたいなと考えています。","voiceIndex":105,"id":"exchange-043"},{"speaker":"嶋委員","kind":"質問・要望","question":"先日私は、食育の視察に行った江戸川区の小岩小学校ではセカンドスクールというものが６泊７日で実施をされて、同じように見せていただいて、６泊７日ですから、７日間先生もその間教育現場から離れて行くということでございましたが、全部ビデオで撮られておりまして、それをインターネットで見せていただいたんですが、子どもたちが行くときの顔と、帰ってきたときの顔が全然表情が違う。","respondent":"中島指導課長","answer":"小中一貫校におきましても、基本的にはそのほかの小中学校と同じように移動教室、林間学校等を実施することを考えてありますが、一貫教育という視点から、その学校の特色として今後また一貫校の中でこういった行事を工夫していくことを検討してまいりたいと思います。","voiceIndex":107,"id":"exchange-044"},{"speaker":"嶋委員","kind":"質問・要望","question":"これからの品川区の小中一貫の中でセカンドスクール的なもの、農業体験とか、自然学習、体験学習もあるかと思いますが、ぜひそれを入れていただきたいということを要望します。それから、次に、学校現場での公衆電話のことです。品川区内の小中学校、学校だけに限らせていただきますが、公衆電話が今何台あるのか、お聞かせいただきたいと思います。","respondent":"市川庶務課長","answer":"それと、通常学校の玄関のところに公衆電話が置いてありますが、これはすべて当該校のＰＴＡが設置をしているところが１４校、５８校中計１８校に公衆電話が設置されてあります。","voiceIndex":109,"id":"exchange-045"},{"speaker":"嶋委員","kind":"質問・要望","question":"これは品川区として学校現場的に公衆電話の設置に対してのお考えをお聞かせいただきたいと思います。","respondent":"市川庶務課長","answer":"その対応策として、先ほど申し上げましたが、それならばＰＴＡが設置者ということで置きましょうということで、ある時点ではおそらく５８校がそのまま幾つかはＮＴＴ、幾つかはＰＴＡという振り分けで、存続したものと思います。","voiceIndex":111,"id":"exchange-046"},{"speaker":"嶋委員","kind":"質問","question":"最後の付けるか、付けないかの判断はＰＴＡがしているということでよろしいでしょうか。小学校、中学校携帯電話を持たせておりませんので、そういう意味では、学校現場に公衆電話、外部と何らかの連絡がとりたいという部分もあるかと思いますが、それは品川区の教育委員会としてはどのようにお考えでしょうか。","respondent":"市川庶務課長","answer":"ＰＴＡの判断で撤去と、言葉で私は申し上げましたけれども、学校がＰＴＡにお願いする経過の中で、ＰＴＡご自身が学校と相談して、こういう状況のもとで継続して設置すべきかどうかと、そういうお考えのもとになされた結果だというふうに考えてあります。","voiceIndex":113,"id":"exchange-047"},{"speaker":"嶋委員","kind":"質問・要望","question":"私はＰＴＡ会長からご相談があったものですから、ちょっとこのことを質問をさせていただきました。ＰＴＡ会長のほうにその旨を伝えて、よく現場的にご相談をしていただきたいということで判断をしていきたいと考えています。そういう意味で、品川区がすでにできています外部評価委員会との流れといいますか、文部科学省が展開をしていく学校運営協議会とのつながりをちょっと教えていただきたいと思います。","respondent":"中島指導課長","answer":"今後この外部評価者制度が学校運営協議会の役割の部分とどのように担っていけるところがあるのか、また、足りないところをどう補完していくのか、検討をしていきたいなと考えております。","voiceIndex":115,"id":"exchange-048"},{"speaker":"嶋委員","kind":"質問・要望","question":"品川区としては各学校８名以内、全学校で３４２名、内訳的に地域、団体、関係者、ＰＴＡ関係が２８４名、学識経験者が５８名です。そういう学校でも外部評価をやっていると思いますが、そういう方たちで重なっていっている方たちも大変いると思いますが、そこら辺で、また、その方たちのご意見とかを聞く場があるのかどうか、お聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"今ご意見をいただいた部分を踏まえまして、現在進めております外部評価者の検討委員会の中でも話題として取り上げていければなと考えています。","voiceIndex":117,"id":"exchange-049"},{"speaker":"中塚委員","kind":"質問","question":"私からは、１５３ページの小中一貫教育について質問を行いたいと思います。９月２８日の文教委員会でカリキュラムの説明がありまして、その中で、国語科のカリキュラムについて伺いたいんですけれども、初めに、改めて今の子どもたちの国語の課題について説明をしていただければと思います。","respondent":"中島指導課長","answer":"今の子どもたちの国語の課題というのは、なかなか大きな部分ですけれども、具体的な話に落としてまいりますと、例えば読書離れが進んでいる、活字離れが進んでいる、そして、長文とか、そういったものに根気よく取り組んで読解することがなかなか難しい。","voiceIndex":120,"id":"exchange-050"},{"speaker":"中塚委員","kind":"質問","question":"私は漢字の学習について本会議でも取り上げたんですけれども、一貫教育での漢字の配当が前倒しされることに漢字嫌いが増えるんじゃないかという不安の声を保護者の方や、教師の方からも伺っております。しかし、６年生に上がると途端に漢字が好きではなくなってくる。子どもたちにとってどういう授業が漢字が嫌いだというのをつくっているのかというのを、お考えを聞かせていただければと思います。","respondent":"中島指導課長","answer":"６年生でもパズル的な要素を使いながら部首を使った漢字の学びをするケースがありますし、いろいろな授業の取り組みの仕方で子どもたちの興味、関心を高めることができるものと考えています。","voiceIndex":122,"id":"exchange-051"},{"speaker":"中塚委員","kind":"質問","question":"パズルを使ったり、いろいろ教材を使ったり、クラスごとで工夫をしながら行って克服しているというお話がありましたけれども、一貫教育では学年ごとに漢字の数が変化していきますけれども、漢字が増える、前倒しされるのが、それぞれ学年ごとにどれだけ変わってくるのか、増える理由と、その根拠と言いますか、なぜ変化するのか教えていただければと思います。","respondent":"中島指導課長","answer":"それらの豊富な語彙を使って、ほかの教科の学びも波及的に広がっていくことができる。これが二つ目のポイントだと、このように考えてあります。","voiceIndex":124,"id":"exchange-052"},{"speaker":"中塚委員","kind":"質問・要望","question":"一方で、漢字が苦手といいますか、嫌いといいますか、子どもたちがいるのは、その理由について、先生方に伺ったんですけれども、子どもが漢字学習の中で一番嫌いなことに対して、漢字を機械的に何度も書いたり、機械的に意味もわからず何度も読んでみたり、こういうのが一番嫌いだと子どもたちが話していると言っていました。","respondent":"中島指導課長","answer":"国語科のカリキュラムの検討委員会につきましては、昨年度当初に立ち上げてあります。","voiceIndex":126,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問","question":"千葉県の先生が２年生の担任のクラスに上がったときに、漢字嫌いの子どもをなくしたいと思って、２年生の１６０字の中で６７字を選定して、１セット５課程という方法で、子どもたちに漢字っておもしろいな、便利だな、この言葉はどんなふうに使うのかな、文章の中ではこんなふうに使われるのかな、一文字、一文字教えていったと。","respondent":"中島指導課長","answer":"漢字の指導につきましては、すべての指導を機械的に丸暗記という形で実施するということは想定してございません。","voiceIndex":128,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"学校の勉強で、なぜ漢字のことを取り上げるかというと、漢字でつまずくことが勉強嫌いをつくり出す引き金になっているという話も教師からよく伺います。ですから、僕は心配に思っております。これでどうして品川区の子どもたちが楽しいことを感じる時間となるのか、教えていただきたいと思います。","respondent":"中島指導課長","answer":"みんなが苦手な教科を持っていれば、全員が学校嫌いになってしまいます。そのようにさせないのがプロとしての教師の力量であり、品川区の先生方は一生懸命取り組んでくださっていると考えております。","voiceIndex":130,"id":"exchange-055"},{"speaker":"中塚委員","kind":"質問・要望","question":"しかし、一貫校教育の漢字のカリキュラムで増える時間というのは読書指導なんですね。今は現場の先生たちが漢字指導で困っているのは、漢字の量が多過ぎて、時間が少ない。だから、不安を感じているわけです。品川区の国語のカリキュラムですけれども、どんな実践が今までされてきたのか、品川区以外のところでありましたら、教えていただきたいと思います。","respondent":"中島指導課長","answer":"週１時間平均で、１年生から４年生までは読書活動を展開していきたいと考えていますけれども、年間にしますと、およそこれが３０時間前後になるのではないかなと思います。","voiceIndex":132,"id":"exchange-056"},{"speaker":"中塚委員","kind":"質問","question":"率直にまだ不十分な点、多くの意見も集める点があるのではないのかなと思うんです。この先生の著書に「楽しく学ぼう漢字」という本があるそうですけれども、インターネットのイーエスブックスという中でたびたび１位になって、教員の方からも多く愛読されているというお話も伺いました。積極的に意見を集めて、慎重に見直すべきではないかと思いますけれども、いかがでしょうか。","respondent":"中島指導課長","answer":"そういった流れの中で、漢字の指導というものは今後小学校、中学校でどのように考えていくべきかという視点でもって私どもの品川区の、先ほど申し上げましたスペシャリストの小中の国語の先生、それから、国語科教育の学識経験者の方、また。","voiceIndex":134,"id":"exchange-057"},{"speaker":"中塚委員","kind":"質問・要望","question":"まとめたいと思うんですけれども、政府の文化審議会でやっていると言いますけれども、実際子どもたちにそのカリキュラムがどうなのかというところはまだ研究されていないのが現状だと思うんです。ですから、真の子どもの実態に即して、教師や、専門家の意見をたくさん聞いて、見直しを進めていただきたいと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":136,"id":"exchange-058"},{"speaker":"伊藤委員","kind":"質問","question":"成果報告書の１５４ページ、学力定着度調査に関連をして、それから、教員の人事に関連をして質問をします。人事のほうから先に進みますが、簡単で難しい話かもしれませんが、品川区の小学校で１年生が入学しました。だから、こういう事例に関しては、学校長の権限でお別れ会を開いていくとか、さまざま対応をすべきかと思いますが、いかがでしょうか。ご見解をお聞かせください。","respondent":"中島指導課長","answer":"人事というのは事前に、この学校へかわりますということをオープンにできないというような状況がございまして、その辺での子どもたちとの交流がどうなのかというような趣旨のご質問かなというふうに考えてあります。","voiceIndex":138,"id":"exchange-059"},{"speaker":"伊藤委員","kind":"質問","question":"このケースは結果として、歓送迎会に来られないですから、子どもも、保護者の皆さんも、ありがとうの言葉も言えなかった現状なんですね。今、学校任せという部分がありましたけれども、私はそれではなくて、むしろこのような問題については教育委員会が中心になって対応措置をしていくべきと考えますが、いかがでしょうか、ご見解をお聞かせください。","respondent":"中島指導課長","answer":"基本的には学校運営に係わる問題であるとは考えてありますが、こういったようなお声につきまして、それぞれの学校長のほうとまた話せる機会に議題に切り出していければなと考えています。","voiceIndex":140,"id":"exchange-060"},{"speaker":"伊藤委員","kind":"質問","question":"ぜひよろしくお願いいたします。次に、学力定着度調査に関連して質問をいたします。海外調査の報告書にも示されておりますけれども、今後品川区、あるいは品川区の教育委員会の責任として、定着度調査結果から示された、各学校の改善案を年次を区切って実行し、具体的な学力向上を測定し、それを評価するシステムを検討すべきと考えますが、いかがでしょうか、ご見解をお聞かせください。","respondent":"中島指導課長","answer":"特に小学校は２回目のホームページでの公表ということもありまして、昨年度の公表した内容、そこから出てきた課題、成果、それと今年度の実施の結果等を踏まえた形で、そこに新たな課題として何が残るかということを明らかにしよう。","voiceIndex":142,"id":"exchange-061"},{"speaker":"伊藤委員","kind":"質問","question":"今ご説明いただきました。海外調査のことであれですけれども、イギリス、スコットランドの人は数値化する、しかも氏名を公表していく非常にドラスティックなことをやっているわけです。品川区は学力定着度調査を行った、その結果をこれからどうつなげていくかという新しい段階に入っているわけですから、もう少し具体的な答弁をいただかないと安心しませんので答弁をお願いいたします。","respondent":"中島指導課長","answer":"これが大きな要素になっていこうかと考えております。教育委員会のほうでも、それに伴う指導、助言をつくる体制で考えてまいりたいと考えています。","voiceIndex":144,"id":"exchange-062"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、そのことをぜひ最後はご理解していただきたいと考えています。それから、もう１点、学校評価について質問をしますが、海外調査で学校評価については、学校の自己評価、それから外部評価の同時進行を行って、より客観的な学校の評価を進めていく必要があると、どこでもありました。","respondent":"中島指導課長","answer":"今後より開かれた学校づくりを目指す中で、こういった自主的に取り組んでいる学校の状況も含めて、評価のあり方につきましては、外部評価者制度の見直しの中でも検討をしてまいりたいと考えております。","voiceIndex":146,"id":"exchange-063"},{"speaker":"伊藤委員","kind":"質問","question":"今お話を聞いていて、評価についてはおそらく途上にあるかなという感じがしました。いろいろな見方があるわけですから。まして今はプラン２１をはじめとして、品川区は堂々と教育改革を進めているわけですから、そういうことについても３分の１の意見ということではなくて、そこに通学していらっしゃる保護者の意見を聞かないのかな。ですから、確かに外部評価者制度の中に入っているのは分かっています。","respondent":"中島指導課長","answer":"しかし、保護者に関しましては、これまで学校がそれぞれの形でアンケート等で意見を収集している状況も踏まえて、この検討委員会の中で課題として取り上げてまいりたいと思います。","voiceIndex":148,"id":"exchange-064"},{"speaker":"伊藤委員","kind":"質問・要望","question":"外部評価の結果についての責任はどこにあるかということ、学校長なのか、外部評価者委員会にあるかということを、答弁をもう一ついただきたいのと、それから、この質問の趣旨は、昨年の海外調査も含めて、さまざまな形の学校評価のスキルを私たちは勉強をしてきました。","respondent":"中島指導課長","answer":"外部評価の制度によって、いただいた評価を学校の運営、教育の充実に生かしていくということが本来の目的ですので、これの責任は学校長にあると考えております。","voiceIndex":150,"id":"exchange-065"},{"speaker":"山村委員","kind":"質問","question":"そこら辺のことは前にも個人的にお聞きさせていただいたんですが、その後コナミスポーツにどのようなことを言っていただいて、今どのように改善されているのか、教えていただければと思います。","respondent":"梶教育委員会事務局副参事","answer":"現在要員を送ることにつきましては、契約書の仕様書の内容の中で、例えば高等学校以上の学力を有する１８歳以上の方ですとか、あるいは健康な方、窓口の業務が主ですから、履行場所の風紀、業務規律を乱さない者、また、来館者に対して不快感を与えないこと。","voiceIndex":153,"id":"exchange-066"},{"speaker":"山村委員","kind":"質問","question":"素早い対応をありがとうあります。スポーツ協会の方がもし辞められた場合に、そのソフト自体が何かあったときに、作成した本人がいないと不都合が生じるかなとも思うんですが、今はそういうコマ数の計算などは当然総合体育館もＩＴ化されていると思うんですが、そこら辺どのようにされているのか教えていただければと思います。","respondent":"梶教育委員会事務局副参事","answer":"ただ、こちらの内容はそんなに難しいというものではございませんので、特にエクセル関係は今はほとんどの方が使えるような状態になってありますので、そちらのほうは、例えば異動ですとか、退職等があっても、その中で十分対応できる、そのような形でやっていきたいと思います。","voiceIndex":155,"id":"exchange-067"},{"speaker":"山村委員","kind":"質問・要望","question":"それを踏まえまして、今後はスポーツ協会の方がそういうこともやられていくのか、それともコナミからいらっしゃった方がそういうふうなこともされていくのか、教えていただきたいと思います。","respondent":"梶教育委員会事務局副参事","answer":"現在スポーツ協会の職員のほうで資料統計を行ってありますけれども、実際の計算とか、取ること自体については窓口のほうで行いますので、これから窓口業務等が、コナミには限りませんけれども、委託業者のほうがだんだん入ってくるようになれば、そちらのほうで数字を拾い。","voiceIndex":157,"id":"exchange-068"},{"speaker":"山村委員","kind":"質問","question":"コナミスポーツのほうとのやりとりが大変だということは聞いておりますので、これからも鋭意頑張っていただければと考えています。次の質問に移らせていただきます。多子家庭給食費補助のことについて質問をしますが、何人目から無料なのかということと、どの程度補助をされているのか教えていただければと思います。","respondent":"谷田部学務課長","answer":"補助金の対象ですけれども、小中学校に在学する児童・生徒が３人以上いて、３人目以降のお子さんから補助になるです。","voiceIndex":159,"id":"exchange-069"},{"speaker":"山村委員","kind":"質問","question":"ただいまのご説明ですと、３人兄弟の一番上が抜けただけで補助がなくなるということだと思うんですが、例えば予想としてそういう状況にいる家庭が品川区内にどのぐらいいるとお考えなんでしょうか。","respondent":"谷田部学務課長","answer":"所得制限の対象ですけれども、特別区民税の所得割課税金額が１４万円以下の世帯が対象になりますので、私ども全体で何世帯ぐらいあるのかというのはちょっとわかりませんが、先ほどの補助を受けている人数が９４名前後です。","voiceIndex":161,"id":"exchange-070"},{"speaker":"山村委員","kind":"質問・要望","question":"補助のほうは、対象となるであろう家庭というのがもし分かっているのであれば、個別に通知をしたほうがいいかと私は思うんですが、個別ではなく、やはり区報とかのみの告知で行われているのか、それとも家庭ごとに告知でそのような案内を送られているのか、教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"これは学校を通じていろいろＰＲといいますか、周知をしているということでございまして、あくまでも申請するのはその世帯が申請をしたいということで、申請主義をとってありますので。","voiceIndex":163,"id":"exchange-071"},{"speaker":"山村委員","kind":"質問・要望","question":"私が言いたいのは、告知のことでございまして、そういう情報が、対象でも、自分がそうだと思っていらっしゃらない方もいるかなと思ったので、例えば学校でしたら、まず分かるわけですから、学校ごとにそういう方がいらっしゃったら、教えているというか、ＰＲしているというか、そこら辺のＰＲのことをどういうふうにやられているのかを教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"なるべく漏れがないようにはしたいと思ってあります。ただ、私ども所得の関係が、税情報をつかめませんので、この人が対象だということについては、ピンポイントでお知らせはできない部分がありますので、あくまでも学校を通じて周知に努めているです。","voiceIndex":165,"id":"exchange-072"},{"speaker":"山村委員","kind":"質問・要望","question":"医療費の助成のほうも所得制限をなくされたわけですので、これについても所得制限をなくされたほうがいいと私は思っているんですが、そういう意味で、お話を聞いていると、これは若干不完全な部分があるようて気がしてなりませんので、所得制限の撤廃を強く求めるというわけではないんですが、そこら辺で何か改善策等考えられていたとしたら、教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"この制度ができて大分経過しています。現在の要綱が制定されたのが昭和５５年ですから、当時とは社会経済状況は随分変わっているということで、現在のこの事業のあり方についても今後検討をするのが私ども事業の改善のポイントの一つになろうかというふうに思ってあります。","voiceIndex":167,"id":"exchange-073"},{"speaker":"山村委員","kind":"質問・要望","question":"教育関係全般のことになってしまうんですけれども、新聞等で読ませていただいたんですが、総合規制改革会議のほうで公設民営方式を公立学校に入れるというような議題が出ているということと、学校に代えて、個々の子どもを対象に公的補助支給する、バウチャー制度というのは、学校の公的補助だけでなくて、今後いろいろなところで活用される機会が増えてくるんじゃないかと思うんですが。","respondent":"中島指導課長","answer":"いずれにいたしましても、現在方針を固めて今後答申に盛り込めるよう折衝を国のほうでも図っていくというような段階ですので、私どもといたしましては、国の動向を今後とも見守っていきたいなと考えています。","voiceIndex":169,"id":"exchange-074"},{"speaker":"井上委員","kind":"質問・要望","question":"私からは、１５２ページの教育費全般ということで伺います。次回、３学期の終わり頃に行われると思いますけれども、すまいるスクールの保護者会で必ず当事者の意見として周知方法がどうだったのかとか、子どもたちの様子がどうだったのかということを、保護者会で意見を聞いていただきながら、次回の検討に反映させていただきたいということを一つ要望しておきます。","respondent":"中島指導課長","answer":"男女混合名簿も誤った認識のもとでの実施はしないというようなところを出したということですが、表現が明確になっていないようなところもありまして、いろいろと論議をかもしているようです。","voiceIndex":174,"id":"exchange-075"},{"speaker":"井上委員","kind":"質問","question":"私たち生活者ネットワークが２年前に調査をしたときには、小学校４０校で、中学校が１校というところでは、間違いないでしょうか。","respondent":"中島指導課長","answer":"現在男女混合名簿を導入している小学校ですけれども、これは私どもの調査で小学校が３８校です。中学校につきましては１１校です。","voiceIndex":176,"id":"exchange-076"},{"speaker":"井上委員","kind":"質問・要望","question":"２年前には中学校が１校だったところが、１１校に増えているということは、今後さらにこういった正しい認識の上で進めていきたいと思っていますけれども、品川区が小中一貫で教育展開をしていくところで、７年生になって名簿が男女に振り分けられるようなことはないかと思いますけれども、そこら辺はどうなのかということと、さらに、先ほども要望としては申しましたけれども。","respondent":"中島指導課長","answer":"例えば諸活動の中の仕事の分担ですとか、男女平等の認識に立った進路指導ですとか、学校教育の中で行われるさまざまな男女平等教育、それの一つの面として男女混合名簿といったものが存在していると認識しています。","voiceIndex":178,"id":"exchange-077"},{"speaker":"井上委員","kind":"質問","question":"学校での職員構成について伺います。２３区どこの学校でも一番人数の多いところというのは４０歳代でしたけれども、品川区の小学校の教職員は年齢バランスが平均しているということ、逆に言えば、ベテランの先生が少ないということも言えますけれども、この状況を教育委員会ではどのように考えていらっしゃるのでしょうか。","respondent":"中島指導課長","answer":"全都的には５１歳から５５歳が一番ピークにきておりますので、この辺品川区も全都も５０歳前後の方々が学校の中枢になって動いているという認識です。","voiceIndex":180,"id":"exchange-078"},{"speaker":"井上委員","kind":"質問","question":"２００３年度の職員数の新任、新卒の職員が全体の６.６％で、６０人ということで伺っています。先日の一般質問では、新任、新卒の先生がクラス担任になることはあまりないというようなことを伺ったんですけれども、実際に新規採用６０人の方で、担任になった方の人数をお知らせください。","respondent":"中島指導課長","answer":"私どもの平成１５年度の資料の中では、小学校５５名のうち学級担任をやっているのが４６名、８３％です。中学校は平成１５年度は５名のうち１名が学級担任をやっておりまして、２０％、こういう状況です。","voiceIndex":182,"id":"exchange-079"},{"speaker":"井上委員","kind":"質問","question":"この５５人の先生方で、単数の学年の担任になった先生というのはお分かりでしょうか。そういうふうになった場合には、大変な負担がその先生にあり、また問題も抱えられるんじゃないかと思うんですけれども、その辺の判断を教育委員会としてはどのように考えているのでしょうか。","respondent":"中島指導課長","answer":"単学級の場合には、基本的には小学校の場合には、低学年、中学年、高学年という形で二学年の中でそれを一緒に見ながら、体制をつくっていくというのが基本的な運営のあり方でありますけれども、そういうような形での人的な支援も現実的にはしている状況です。","voiceIndex":184,"id":"exchange-080"},{"speaker":"井上委員","kind":"質問","question":"８３％というのが、私にしてみたら、その割合は非常に高いという印象があるんですけれども、どうしてそういう新任教師が担任を持たなければならなくなってしまったのかということは、何らかのお考えがありますでしょうか。","respondent":"中島指導課長","answer":"今定数加配のプラスアルファの部分で、ＴＴですとか、少人数の加配の教員が小学校に大体１名ぐらいはいるんですが、そういったところに初任者を配置するというのはなかなか難しい。","voiceIndex":186,"id":"exchange-081"},{"speaker":"井上委員","kind":"質問","question":"それからまた、子ども自身が子ども同士とのけんかも含めて、経験的に体験することで子ども同士のつき合いというものを見つけるところなんですけれども、その一方で、先生が忙し過ぎたり、また、経験が少々不足している中で、子どもの心のサインも見えないとか、気がついてあげられないということでは。","respondent":"中島指導課長","answer":"幾つかいただいております。子どもたちとゆとりを持ってふれあう場ですけれども、単純に時間さえ与えればそれでいいのかという、そういう問題ではなくて、なかなか難しい要件が入ってくるんじゃないかなと思います。","voiceIndex":188,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問","question":"ジェンダーフリー教育についてお伺いいたします。先ほどの質疑の中で、都教育委員会の指導が一部あるようなんですが、区教育委員会としてジェンダーフリー教育に対して、具体的にジェンダーフリーという用語を今後今までと変わりなく使っていくのか、また、教育の中身に従来のものと変わりがないのか、その辺を具体的にお聞かせください。","respondent":"中島指導課長","answer":"男女混合名簿の実施につきましては、先ほど申し上げましたが、男女共同参画宣言の視点に立って、学校の男女平等教育を進める中での一つの視点ということで、今後ともこれまでと同じような体制で取り組んでいきたいと考えています。","voiceIndex":191,"id":"exchange-083"},{"speaker":"飯沼委員","kind":"意見","question":"もう１点としては、こういったことを分かりやすく魅力的に編集された手引書の決定版や、リーフレットを作成すること」、この三つの提言がされているんですが、最後のところに、「ジェンダーフリーな区職員、区教育委員会関係職員、保護者など、一丸になったジェンダーフリー教育が推進されることを」と書かれているんですが、その後ジェンダーフリー教育が品川区内において、学校だけじゃなくて。","respondent":"若月教育長","answer":"教育論として必要な男女平等の意識とか、男女平等に関する教育はやりますよ。しかし、それと運動論でさまざまなことが言われています。運動論と教育論は分けますよと。これを教育委員会の基本的なスタンスとしているということであります。","voiceIndex":193,"id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問","question":"今、教育委員会と区の職員のところもあるし、生涯教育においてどうなのかという具体的な部分でどう進んでいるのかというのをお伺いしたんです。運動論がとにかくではなくて、どう進んでいるのかをお聞きしたので、お答えください。","respondent":"本間総務部長","answer":"男性も女性も一人の人間として尊重されるそういう社会、男女共同参画社会を目指しての施策、これを私どもは人権啓発課を中心に教育委員会としても連携して進めているということでございまして、運動論的には、先ほど教育長から答弁したとおりです。","voiceIndex":195,"id":"exchange-085"},{"speaker":"塚本委員","kind":"質問・要望","question":"私のほうからは、教育費の不用額と、それから減額補正がされまして、前に報告を受けたと思いますが、その件と、文化行政保護委員会、歴史館等の大きな柱を立てておりますけれども、文化行政について伺いたいと思います。不用額関係ですけれども、当初予算より１２億円ほどの減額補正、これはたしか第二延山小学校に関連してのことだと思いますけれども、改めて概要を報告していただきたい。","respondent":"市川庶務課長","answer":"この内容といたしましては、第二延山小学校の国有地の取得費ですけれども、当初２７億円見込んで予算計上したものが、１３億円で買い上げたということで、１４億円のマイナス、それに対しまして、同じ最終補正におきまして。","voiceIndex":198,"id":"exchange-086"},{"speaker":"塚本委員","kind":"質問","question":"第二延山小学校で国有地の買収が半額ということ、これはちょっと目論見としても、結構なことですけれども、考え方がどこかでずれていたのではないかと思いますけれども、その辺のところ、こういうわけで交渉術がうまかったから安くなったという額ではないと思いますが、そのいきさつをもう一歩踏み込んで教えていただければありがたいと思います。","respondent":"市岡企画財政課長","answer":"したがいまして、私どもは時価の２分の１を予算計上したものですが、そのときも若干は頭においておったんですが、実はこの校地は昭和２２年から５７年間借地料を一度も滞納することなく営々として品川区が国に払ってまいりました。","voiceIndex":200,"id":"exchange-087"},{"speaker":"塚本委員","kind":"質問","question":"大変すばらしい交渉能力だと思います。民間だと特別ボーナスが出るのではないかと思いますけれども、それでは、もう１点のほうの文化財、歴史館に関連しましてお伺いします。全般的に言って、博物館行政という言い方が適当じゃないかと思います。ある文化の拠点をつくりまして、それからいろいろな発信をするです。基本的な考え方をお知らせ願えればと思います。","respondent":"上川内生涯学習課長","answer":"こじんまりしていると言われましたが、品川区を中心とした歴史等で事業を展開しているところでございまして、近代の工学の歴史としまして、平成１４年度には「鎌倉武士西に走り、トランジスター海を渡る」と題しまして、品川区から世界に巣立った人、者。","voiceIndex":202,"id":"exchange-088"},{"speaker":"塚本委員","kind":"質問","question":"江戸博の館長でもありました。碩学でおられます。そういうことをどうやって残していくか、側面支援、歴史館があそこに一つだけあればいいというものではありませんから、ある種の資料館を旧東海道に配置するとか、そういうことが可能だと。全体的な行政財産をどう使うかということを考えていかないと、文化行政展開できないというふうな視点で物を申し上げておるわけですから、お答え願えればと思います。","respondent":"古川教育次長","answer":"今の委員のご指摘を踏まえまして、これからの歴史館が品川区という土地の古いもの、そしてこれから新しく伸びていくもの、こういったものをつなぎ合わせて、さらには旧東海道という大きな品川区の資源がありますので、こことも連携を図りながら。","voiceIndex":204,"id":"exchange-089"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１５４ページの学校教育費の中の特別支援教育についてお伺いをしたいと思います。現在の障害児教育の現状についてお聞きしたいんですが、現在障害児学級が何クラスあって、在籍生徒数が何人いるのか。そして、通級による指導を受けている生徒数が何人いるのかを教えていただきたいと思います。そして、現在その子どもたちにどのような支援がされているのかについてお聞かせください。","respondent":"谷田部学務課長、中島指導課長","answer":"１年から３年までの生徒が３５名です。それから、荏原第二中学校に情緒障害の通級学級が設置されておりまして、２学級編成で、１６名の生徒が通われているという状況です。文部科学省が行いました、通常学級に在籍する児童・生徒の学習障害等に対応した教育支援に関する研究のための調査ですけれども、これは東京都のほうで小中学校の学級には知的な遅れはないが。","voiceIndex":210,"id":"exchange-090"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"さっきＬＤ児などの子どもたちに対してどのような支援がされているかということもお聞きしたんですけれども、それは次の質問と合わせてお答えいただければと思います。この問題では、一般質問でも南議員が取り上げておりまして、このところで今年度からすべての教職員を対象にした特別支援教育の研修を開始したと。","respondent":"中島指導課長","answer":"本区が主催している研修の中で、特別支援教育研修会と銘打ちまして、特別支援教育とは何か、また、現在東京都、そして品川区で検討している特別支援教育の内容等、これに絡めた話を、講師を招いて実施をした状況があります。","voiceIndex":213,"id":"exchange-091"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"全体で何人いるのかというのがちょっとわからないので、１５３名というのが何％ぐらいなのかというのを後で教えていただきたいんですが、この問題で、アスペルガーの子どもを持ったお母さんからお話をお伺いしたんですけれども、１年生と２年生のときはクラスが３５名だったそうですけれども、先生が新任の先生だったそうです。なぜ三国志を教えたんだというふうに言われたということです。","respondent":"中島指導課長","answer":"先ほどの１５３名がどれぐらいの割合になるかという部分ですが、これは計算いたしますと１７％です。教員の研修をすべての教員でというお話ですけれども、今私どもで申し上げたのは、品川区で実施している研修会と、それから東京都で実施している研修会です。","voiceIndex":215,"id":"exchange-092"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"さまざまなところで気軽に相談できるというふうな場もたくさん必要だと思いますし、みんながこの認識をしっかりとしていくということが凄く大事なんじゃないかなというふうに思うんです。親や、教員、一般区民にもどれだけ大変な中で生活をしているのかという理解のためにも、こういうところも多くの人が参加できるような形で取り組んでいただきたいというふうに思うんですが、いかがでしょうか。","respondent":"中島指導課長","answer":"今の相談体制をまた充実していきたいなと考えています。家庭あんしんセンター、そういったような情報ですけれども、特別支援教育のあり方を私どもは今検討を進めてありますけれども、そういった中での協議の中で俎上に上がってくるものと考えています。","voiceIndex":217,"id":"exchange-093"},{"speaker":"堺委員","kind":"確認","question":"私のほうから３点お尋ねをしたいと思います。成果報告書では１５４ページの学校教育費に関連してです。その点が１点目です。２点目が、校内暴力といじめの件です。中学校も、いずれもそのような増加傾向にあるわけですが、本区についての状況はどうなのか、その辺を確認をしておきたいなと思います。もしお読みになっておられれば、お読みになった上でのご感想も含めて、ご意見をお伺いしたいと思います。","respondent":"中島指導課長","answer":"そういったところが大きく報道されて、その部分での対応等が、消えゆく反抗期というような状況になってきているのではないかということで、通常であれば親子関係が円満に見えるので、望ましい傾向ではあるけれども、それは子どもたち。","voiceIndex":220,"id":"exchange-094"},{"speaker":"堺委員","kind":"質問・要望","question":"確かに効果があったという評価のようですので、これもぜひそういう方向で取り組んでいただければと思っておるんですが、その辺についてのご意見をお伺いしておきたいと思います。それから、いじめの件です。したがって、もう一度確認の意味で、品川区としてスクールカウンセラー等の、不登校、いじめ、暴力、そういうものに対する取り組み状況、その辺のところを参考にお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"この相談の中で、平成１５年度の実績の中では、一番多い相談が不登校に係わる相談です。２番目に話し相手になってもらいたいというような形での相談、３番目、４番目ときまして、５番目にいじめに係わる相談という形で対応をしている状況があります。","voiceIndex":222,"id":"exchange-095"},{"speaker":"堺委員","kind":"質問・要望","question":"いじめと校内暴力の関係です。それから、先ほどの中学生の親子円満の関係です。この辺については、ある精神科の先生がこのようなことをおっしゃっておられました。こんなふうなことが言われておりますけれども、もしこの記事をお読みになっておられましたら、読んだことも踏まえての感想、ご意見を伺いたいと思います。","respondent":"中島指導課長、上川内生涯学習課長","answer":"ご承知のように、小中一貫教育の市民科の内容の中でもそういった、今子どもたちに大人として教えていかなくてはならないことをはっきりと位置づけて取り組んでまいりたいと考えているところです。小学校の高学年から思春期を迎えますと親離れ、自分の親となかなか話ができないということがあります。そういう中で、何か一つの作業を通じて、このようなことをしていくというのは大変重要なことだと考えています。","voiceIndex":224,"id":"exchange-096"},{"speaker":"堺委員","kind":"質問・要望","question":"家庭学級の件、まだお話を聞いたことがないですが、ぜひ来年の夏休み等を含めまして、品川区でも実施されるように要望をしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":227,"id":"exchange-097"},{"speaker":"石田委員","kind":"質問","question":"私は、１５４ページ、学校教育費、学校評価等をお聞きしたいと思います。登校時の朝のあいさつ、伺ったところによると、小学校では今全校に広がってきたということで、非常にいいことだなと考えています。これはどういう形で教育委員会も携わって広がっていったのか、そこら辺のところ、また、これは非常にいいことだと教育委員会も判断していたのかどうか、そこら辺の点を併せてお伺いしたいと思います。","respondent":"中島指導課長","answer":"現在、やり方はそれぞれに違いますが、中学校におきましても生徒会等がある程度定点的に実施をするなどして、このあいさつ運動は広めている状況があります。","voiceIndex":229,"id":"exchange-098"},{"speaker":"石田委員","kind":"質問","question":"基本的に先ほど来いろいろお話を伺う中で、例えば卒業遠足においては学校の独自の事業ですよ、今のも自主的ですよ、朝の読書なども自主的にやっていますよ、答弁などでも積極的に取り組んでいるところは非常に高い評価をしています、こういう報告を聞いていますというところで、朝の読書については、小中一貫教育の中で、これはカリキュラムに入れてやっていくんだ。","respondent":"中島指導課長","answer":"これは教育委員会と学校が現在進めておりますプラン２１の小中一貫教育の推進にも係わる部分かなと捉えてあります。私どもは決して小中一貫教育におきましても教育委員会がトップダウン的に全面的に引っ張り上げているというふうには考えてございません。","voiceIndex":231,"id":"exchange-099"},{"speaker":"石田委員","kind":"質問","question":"もう一つお聞きをしたいのは、例えばあいさつなども今は小学校では全校に広まってきた。朝の読書などもいいと思っているけれども、先ほど２８の１１だということだけれども、全体的に制度的に行うんだよ。だけれども、今学校が独自に行っているものでも、これは教育委員会でもいいなと思うことはあるのか、ないのかだけちょっとお聞きしたいと思います。","respondent":"中島指導課長","answer":"たくさんあります。","voiceIndex":233,"id":"exchange-100"},{"speaker":"石田委員","kind":"意見","question":"私もそう思っておりまして、ここら辺の非常にいいことだなと思う、最低限のレベルでいいんですけれども、例えばこういうのは本当にいいことだというのであれば、やっぱり校長の権限というのではなくて、品川区民の子どもたちにとって良いことだと思うのであれは、教育委員会が制度とは言わないけれども、強い指導力を発揮して、こういうことは、内容のやり方は別だけれども。","respondent":"中島指導課長","answer":"委員の今おっしゃられたように、さまざまなたくさんのいい取り組みがありますが、すべてを教育委員会で一律にやれということはもちろんできませんし、その中でこれが重要な部分というところを押さえる形で具体的な内容として示していくという考え方です。","voiceIndex":235,"id":"exchange-101"},{"speaker":"石田委員","kind":"意見","question":"いいことだけを言わないで、悪いことを言います。例えばこの前公開授業がありました。校長先生もそれは分かって、ちゃんとこういうことを、迷惑のかからないように、お願いということがあります。非常にひどい話だけれども、最低限の部分だけでも、教育委員会も今出ていかざるを得ない状況にあるんじゃないのかなと思っているんですが、そこら辺の点の考え方をお願いいたします。","respondent":"中島指導課長","answer":"今の保護者のマナーの徹底といった部分は、緊急対応的に対応できるという形ではなかなか難しい部分があるのかもしれませんけれども、学校が実際に困っている状況についても、私どもとしてはなるべく情報を引き上げながら対応できるところを考えていきたいなとは考えております。","voiceIndex":237,"id":"exchange-102"},{"speaker":"石田委員","kind":"質問","question":"もう１点、学校評価のことで、先ほど伊藤委員が質問をして、学校評価の責任の問題をお伺いしたら、これについての責任は学校長ですということでお話があった。その内容を見ると、指定の報告書を作成して、校長を経由して教育委員会に提出ですよね。","respondent":"中島指導課長","answer":"一番大切なのは、こういう評価がある、だから学校としてはこういう形で改善を図っていきたいんだ、それをどう測定していくんだ、そこのところの責任は校長のほうにあると、このように考えているところです。","voiceIndex":239,"id":"exchange-103"},{"speaker":"石田委員","kind":"質問","question":"これは私の感覚でもいいですけれども、教育界で大人がいると、大人が責任をとりたがらない、子どもたちも思っているのかもしれないし、父兄も、先生が責任をとりたがらないと思っているのかどうかはわかりませんが、責任の所在がどこにあるのか。ですから、責任と権限というのもあるけれども、そこら辺の点の考え方を最後にお聞きしたいと思います。","respondent":"中島指導課長","answer":"私ども教育委員会、地方自治を進めていく中で、さまざまな場面で責任と権限を持って判断し、実施している状況があります。","voiceIndex":241,"id":"exchange-104"},{"speaker":"須貝委員","kind":"質問","question":"私は、１５２ページ、教育指導費、学校管理費、もし時間があれば、生涯学習費についてお聞きしたいと思います。先ほどからお話が出ておりますけれども、小中学校の外部評価者制度についてお聞きしたいと思います。それから、現役の先生の意見も取り入れて、いろいろな意見を取り入れて学校改革というのはすべきだと思うんですけれども、その辺についてご見解をお聞かせください。","respondent":"中島指導課長","answer":"その中で外部評価者にどういった方々に係わっていただいたらいいか、これはまだ現在の実施している状況がありますけれども、これからまだこれについては私どもも課題がある部分もあると考えておりますので、検討をしていかなくてはならないところだと考えています。","voiceIndex":244,"id":"exchange-105"},{"speaker":"須貝委員","kind":"質問","question":"お話はよく分かりました。もう１点、学校改革委員という制度があります。来ていないところに対して、ご意見をお伺いして、学校改築というのが進んでいくように感じるんですけれども、本来、その辺の人選も、地域の方とか、ふだん学校によく来られている、いろいろなサークルのメンバーもいらっしゃると思います。地域のボランティア団体もいると思います。","respondent":"市川庶務課長","answer":"学校の改築検討会のメンバーの人選ということでのご質問をいただきました。これまで数校で改築検討会の組織づくりをしてまいりました。今委員のご指摘になったような地域団体の方、学校関係者、そういったことで構成をしてまいりました。","voiceIndex":246,"id":"exchange-106"},{"speaker":"須貝委員","kind":"質問","question":"実際の小学校６年生のレベルを見たいということならば、本来子どもが、自分のお子さんでもそうですけれども、学力的にどこの位置にいるんだと。千差万別なく皆さんを調べるわけですから、きちんと報告して、あなたは品川区の中でどの辺の成績の位置にあるよというのを、個々に教えてあげても何もおかしいことではないと思うんですけれども、何でそういうふうにしないのか、その辺ご見解をお聞かせください。","respondent":"中島指導課長","answer":"学力定着度調査は、何度かご答弁しておりますけれども、この調査を実施することで、なかなか外部評価者の方にも見えにくい、子どもたちの学力の数値でもって測定できる部分的なところを見て、そこで学力定着のためにそれぞれの小学校、中学校が何が足りなかったか。","voiceIndex":250,"id":"exchange-107"},{"speaker":"須貝委員","kind":"質問","question":"しかし、現実の社会では競争にさらされるわけです。私はそう思うんですけれども、だって、今まで小さい頃は競争しなくていいよ、一緒に仲良くいこうよ、社会に出た途端、あんた、競争だよ、ノルマ達成しろ、そうすると、今の品川区の教育がちょっと間違っていないかという考えをするんですけれども、どう思われますか。","respondent":"中島指導課長","answer":"ただ、学力定着度調査に関して、そういった競争的な部分をねらうということは、私どもは目的としているわけではないです。","voiceIndex":252,"id":"exchange-108"},{"speaker":"須貝委員","kind":"質問","question":"ということは、いいですよと。皆さんほとぼとに勉強して、その成果が出ましたよと。ベテランの人で来る人はいないですからね。例えば皆さんが医者に行くのに、１０年、２０年やっているベテランの医者と、今日、きのうインターンを卒業して、そこに出ていった医者と、どちらがいいかとなったら、やはり申し訳ないんですけれども、教員というのはそんな簡単に１年、２年ですぐ担任を持ててやれるんでしょうか。","respondent":"若月教育長","answer":"そんなことはありません。それは事前調査とか、予備調査といったような、一部の中でそういう傾向があるというだけのことであって、現実に来ないんだったら、品川区は教員がいなくなっちゃうんですから、そうじゃない。","voiceIndex":254,"id":"exchange-109"},{"speaker":"須貝委員","kind":"意見","question":"たくましい教育長のやる気十分見ました。私の最後に言いたいのは、経営者で言うならば、教育長にそういう風評は出てはいけないわけですね。品川区にも。でも、現実は違うんだとおっしゃるならば、もっと教員ならびに校長と仲良く、どうぞ品川区に来てくださいと、そういうふうなやり方を教育委員会のほうでしていただければありがたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":256,"id":"exchange-110"},{"speaker":"沢田委員","kind":"意見","question":"１点だけお尋ねしたいんですが、去年と今年の入って来る先生と、他区に出ていった先生の割合、前に文教委員会で聞いたんですが、答弁をいただけなかったんです。今の問題と関連しますので、それから２３区の平均と比較してどうだったかを説明願います。","respondent":"中島指導課長","answer":"今年の教員の転出と転入ですけれども、区外転出は１１２名、区外からの転入は１０３名という状況です。昨年度につきましては、区外に１１９名転出、区外から９１名転入という形になってあります。２３区の比較はちょっとデータがないのでわかりません。","voiceIndex":258,"id":"exchange-111"},{"speaker":"沢田委員","kind":"質問","question":"教員の実数は変わりませんから、この相差は、結局新任教員で穴を埋めるしかないと考えてよろしいですか。","respondent":"中島指導課長","answer":"これにつきましては、学級数の増減等も入ってまいりますので、すべてが新任教員で補充されるという形ではございません。","voiceIndex":260,"id":"exchange-112"},{"speaker":"沢田委員","kind":"意見","question":"今年で１２名がプラスマイナスで外に出ていった。去年は２８名が出ている。この数字は何を物語るのかと私は思いますと、先ほど論議があった、よく「しなながし」と呼ばれることが、先日世田谷区のある教頭から聞きました。「品川区は今望む人が少ないんですよね」と、教頭先生がこう言ったんです。","respondent":"若月教育長","answer":"ゆめゆめただ単に一面的に、今のプラン２１に反対でしょうけれども、しかし、すべてをそこに持ってこられるというのは、一生懸命頑張っている先生たちにあまりにも気の毒じゃないでしょうか。ぜひその辺も温かい目を注いでいただきたいと思います。","voiceIndex":262,"id":"exchange-113"},{"speaker":"沢田委員","kind":"意見","question":"分かりました。関連で入ったので、これで終わりますけれども、「しなながし」と言ったのは、私ではなくて、世田谷区の教頭先生が言ったんです、「有名なんですね」と。それだけ言って、終わります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":264,"id":"exchange-114"},{"speaker":"宮崎委員","kind":"質問","question":"私は、１５３ページの習熟度別学習と、３０人学級など少人数学級の考え方を関連してお伺いしたいと思います。今年度から神奈川県なども少人数学級に踏み出しました。今こうした全国で広がっている少人数学級の動きについて教育委員会はどういうふうにお考えになっているか、伺いたいと思います。","respondent":"中島指導課長","answer":"この全国の動きをどう見るかという１点目のご質問です。これはすでに平成１６年度から指導方法の工夫、改善を弾力的に国のほうでは運用しているという状況がございまして、全国的にもさまざまな道府県におきましてこういった取り組みが増えてきている状況は認識しています。","voiceIndex":266,"id":"exchange-115"},{"speaker":"宮崎委員","kind":"意見","question":"少人数授業、習熟度などをやっているので、そっちのほうでいいと、そういうお考えだというふうに思います。その前に一つ聞きたいんですけれども、現在小中学校で３０人以下になっているクラスの数がどのぐらいあるのかということと、３０人学級にした場合に、どのぐらいそれぞれ増えるのか、必要な教員は何人増えるのかというのが分かったらお聞かせいただければと思います。","respondent":"谷田部学務課長","answer":"中学校につきましては、１３５学級から１７７学級になりまして、４２学級増えるということで、これも教科別の指導をしていますので、その辺の係数が小学校と若干違いまして、１.５の係数を掛けますと、４２学級に対して６３人ぐらい、これはあくまでも推計ですけれども。","voiceIndex":268,"id":"exchange-116"},{"speaker":"宮崎委員","kind":"質問・要望","question":"おおよそ小中学校で１５０人、雇用の面からでも非常に効果が出てくるんじゃないかというふうに思います。３０人になると、１５人、１６人と、こっちのほうがおかしいと、全く矛盾しているような気もするんですけれども、先ほどの要望等の関係も併せて、３０人学級といいますか、少人数学級の考え方を、本当に効果はないと考えているのかどうなのか、改めてお伺いしたいと思います。","respondent":"谷田部学務課長","answer":"３０人学級で、前に教育長からも答弁がありました。３１人になれば、１５人、１６人のクラス編成もあると。そうしますと、１５人のクラスでは男女それぞれ半数ずつという中で、これで生活集団として維持していくのは非常に難しい問題もあるだろう。","voiceIndex":270,"id":"exchange-117"},{"speaker":"宮崎委員","kind":"質問","question":"学習集団と生活集団、先ほどの東京都の考え方を踏襲しているようだと思うんですけれども、この考え方というのは私はよくわからないんですけれども、もう一つ伺いたいんですが、品川区のほうは習熟度別をやっているからいいというふうなお考えのようですけれども、基本的なところて伺いたいのは、習熟度別学習のクラスの分け方をどういうふうに分けるのか。","respondent":"中島指導課長","answer":"そのグループ分けですが、例えば一つの学校では３つのコースに分ける中で、一つ目のコースは単元の内容を予定時間より早めに進めて、残りの時間を単元内容に係わる難易度が高い問題に取り組んでいくようなコースというような説明の仕方をしています。","voiceIndex":272,"id":"exchange-118"},{"speaker":"宮崎委員","kind":"質問","question":"先ほどお伺いしたんですが、子どもたちに選ばせるというふうに、その基準をこういうふうに示しているというお話だったんですけれども、どういう材料で３つに分けるということなんですか。全くの子どもたちの主観で決めるんですか、あるいは何か材料というのはあるんでしょうか。","respondent":"中島指導課長","answer":"これもこの学校の例ですけれども、ここでは子どもたちの選択という形で選ばせております。全くの選択という形です。","voiceIndex":274,"id":"exchange-119"},{"speaker":"宮崎委員","kind":"質問","question":"その学校はそうかもしれませんけれども、ある学校では事前にテストをやっているということもお伺いしています。習熟度でいいというふうな説明は、私は今の子どもたちと親御さんたちの希望とは全く逆の方向にいっていると思います。時間がないので、あとはしゃべるだけですけれども、子どもたちの状況と、親御さんの状況、世界を大きく見れば、少人数学級だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-120"},{"speaker":"田中委員","kind":"質問","question":"私は、１５９ページの学校施設建設費関連で、特に施設面からの質問をします。冒頭お伺いしたいのは、現在単体で学校施設がありますが、複合施設として戸越台中学校がありますが、複合施設であることのメリット、教育上の良さというのはどういうところに現れているのか、お伺いをしたいと思います。","respondent":"中島指導課長","answer":"戸越台中学校は、特に高齢者福祉施設との共同という形になってあります。子どもたちが学習を展開する中で、ノータイムでこちらの施設の交流ができるという最大のメリットを生かしまして、さまざまな形での交流活動を進めている状況があります。","voiceIndex":278,"id":"exchange-121"},{"speaker":"田中委員","kind":"質問・要望","question":"新校舎を建設するにあたりましての、一つの考え方として、いろいろお伺いをしていきたいと思うんですが、まず、校舎を改築するにあたりましての規模の考え方ですね、例えば既存の教室から割り出す考え方もありますし、また、その中で全体の中の適正配置を考えながら学校のあり方を考えていくという考え方もありますし、また、学校施設をつくるにあたっての法律上の制限があるのかどうか。","respondent":"市川庶務課長","answer":"この学級数の推計ができますと、片や、文部科学省の学校の設置基準がありますので、一定の目安となる面積が出てまいります。そういったようなことで、実際改築の計画を進めている経過があります。","voiceIndex":280,"id":"exchange-122"},{"speaker":"田中委員","kind":"質問・要望","question":"既存のスペースで余っているから空き教室として有効活用しようとして今行っておりますが、新しく建て替える際には、空き教室を先につくって、空き教室ありきではなくて、何か学校教育上の、あるいは学校に限らずですが、教育上の要素をそこに加味して、プラス既存の学校の生徒が授業として使えるし、また付随的に教育上の、あるいは防災等々も含まれるのかもしれませんが、そういった観点から。","respondent":"市川庶務課長","answer":"一方、教育委員会で平成１４年５月に学校改築計画指針というものを明らかにしています。この指針の中で学校の改築に際しては、何よりも教育方法等の多様化に柔軟に対応できる、これを第１点に挙げてあります。","voiceIndex":282,"id":"exchange-123"},{"speaker":"田中委員","kind":"質問・要望","question":"この部分の活用というのは第一義的には跡地も小中一貫校教育の充実という視点で生かされていけば一番いいのかなと思いますし、また、２番目に、それが地域的にかなわないとするならば、文教施設、教育施設として現在あるわけですので、今後の跡地の活用も、まずは教育施設というような視点から考えていくことも考え方としてあるのかなという思いがありますが、改めまして。","respondent":"榎本行財政改革担当課長","answer":"特に日野中学校ですと、中学校だけではなく、隣接している文化センターのほうの老朽化の部分もありますので、そういうところも含めて多角的な検討をしていかないといけないという形で認識しています。","voiceIndex":284,"id":"exchange-124"},{"speaker":"田中委員","kind":"質問・要望","question":"この問題も品川区にとっても財源の措置の必要性ということでの大きな問題となっておりますが、区長の先見性ある対応から、基金等もしっかりと積まれているので、その辺は安心だろうというふうに思っておりますが、もしこの主要５課題が解決されなかった場合、特に小中学校改築の部分に関してですが、品川区にとってどのような影響があると推測されるのかをお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"しかし、この課題が２３区にとっても、区民にとっても重要な課題であることは間違いありませんので、ほかの課題を含めた財調協議については全力を尽くしてまいりたいと考えています。","voiceIndex":286,"id":"exchange-125"},{"speaker":"田中委員","kind":"意見","question":"平成２０年までは対応可能ということで安心をいたしましたが、さらに残された改築もスムーズになされるように、議会とともに主要５課題解決に取り組み、また、新校舎改築に向けて取り組んでいきたいと考えていますので、ご尽力をよろしくお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":288,"id":"exchange-126"},{"speaker":"高星委員","kind":"質問","question":"そういうことで、私は本当にこれは大切な課題だというふうに思うんですが、学校現場ではその辺のところをどういうふうに教えているのか、時間の関係があるので、簡潔にお答えをお願いしたいと思います。","respondent":"中島指導課長","answer":"命を守るということは絶対にこの尊厳は守らなければならないんだ。人を殺してはいけないんだ、人を傷つけてはいけないんだ、これはもう理屈をつけて教える部分ではないというところをかなり強調して学校のほうには指導にあたっているところです。","voiceIndex":290,"id":"exchange-127"},{"speaker":"高星委員","kind":"質問・要望","question":"私がさっきわざわざ言った、「人を殺すな、殺されるな、自ら死ぬな」というところの、最後の部分も、できたらその中に織り込んでいただきたいと思います。ともあれ学校教育ですから、義務教育です。ですから、プラン２１でいろいろなことで各方面から、私も言いますけれども、私はもともとプラン２１は不退転の決意でやれと言った。話がありましたら、後でお聞かせいただきたいと思います。","respondent":"中島指導課長","answer":"２学期以降この体制、いろいろな状況が出てきておりますので、情報収集もこれまでのような形では追いつかない部分もあります。全体として体制をつくっていきたいなと考えております。","voiceIndex":292,"id":"exchange-128"},{"speaker":"高星委員","kind":"質問","question":"そういう中で問題なのは、担任も含めた教員を具体的にどう研修をさせていくかということがポイントだというふうに思いますので、その辺のところで、よもや品川区の４０校、あるいは１８校の児童・生徒たちがこういったことで被害者とならないように、逆の意味では、加害者ともならないように、ひとつご指導を徹底してもらいたい。後ほど意見があれば、お聞きしたいというふうに思います。","respondent":"中島指導課長","answer":"しかしながら、それぞれの学校では学校長の人事構想、来年度の経営構想に基づいて教員の異動を考えるということがベースに置かれておりますので、例えば７年目の教員なんだけれども、この教員は今年５年生を持っているので、来年はぜひ６年生を持ち上がらせたい。","voiceIndex":294,"id":"exchange-129"},{"speaker":"高星委員","kind":"質問・要望","question":"例えば４・３・２というスタイルの中で、１年から４年までは、ここで繰り返す人も中には出てきちゃう可能性も出てくる。ただ、前の人事の関係のときもそうですけれども、品川区は一貫して長いこともう少し自区内で教員として続けられないかという要望を東京都にずっと出していたわけです。そのことが今でも続いているかどうか、そのことをもう一度聞いてみたいと思います。","respondent":"中島指導課長","answer":"プラン２１の中で、さまざまな施策に取り組んできた校長、教頭をはじめとする教員に１年でも長く品川区で頑張っていただきたいと思う心は同じです。","voiceIndex":296,"id":"exchange-130"},{"speaker":"高星委員","kind":"質問","question":"教育改革プラン２１の中の具体的な学校選択の部分についてお聞きしたいと思います。そのために普通学級を確保担保するために、特別学級のほうにいろいろなしわ寄せがいっている。小さな子どもたちですから、親が選ぶということになっているわけです。どうしてもその辺のところが心配でなりませんので、そのところの実態がどうなっているのか、先にお聞きしたいと思います。","respondent":"谷田部学務課長","answer":"これは大井第一小学校の校長、教頭と、これ以上学習環境が悪くならないようにということで、普通教室として転用できる教室数の最大数を確保するのが全部で２４学級が限界だというようなお話がありまして、それとまた、今後すまいるスクールの展開ですとか。","voiceIndex":298,"id":"exchange-131"},{"speaker":"高星委員","kind":"質問・要望","question":"その意味で言えば、親御さんからも、保護者の皆さんからもいろいろな要望が出ている。学級の適正規模から言ったって２４クラスと言ったら、大変多いですね。問題なのは、学校選択自由をめぐって、周辺学校との教育の平準化をどう図っていくかということをどういうふうに考えて、どういうふうにやっていくべきなのかというようなことを、しっかりとした答弁をお願いしたいと思います。","respondent":"谷田部学務課長","answer":"平成１２年度から小学校については来年度入学で丸６年、６回目になります。この間学校も相当変わってきたのは、委員の皆様方もその辺はご理解いただいていると思います。保護者も学校とともにいろいろ子どもの教育について一生懸命考えるようになった。","voiceIndex":300,"id":"exchange-132"},{"speaker":"高星委員","kind":"質問","question":"そういうふうに答弁せざるを得ないんですよね。そうでなければおかしいことになっちゃうんです。基本は、ブロック内の周辺の学校の教育の中身の特色あるのはいいの。問題なのは、どうしてそこにまた集中するのというようなことが気になってしようがないんです。最後に、ゼームス坂にありますろう学校がやがて廃止されるという話ですけれども、この点について経過を短くお願いします。","respondent":"谷田部学務課長","answer":"東京都のほうで特別支援教育の検討をする中で、盲・ろう・養護学校の再編整備という考え方が出てまいりました。","voiceIndex":302,"id":"exchange-133"},{"speaker":"高星委員","kind":"質問・要望","question":"当面というのがひっかかってくるわけです。だから、現在そこに通学している子どもたとにいろいろな問題が生じないのかどうなのか、その辺のところ具体的な対応策をどういうふうにしていくのか。当面というのはどのくらいなのか、分かったら教えていただきたいと思います。","respondent":"谷田部学務課長","answer":"私どもも新聞報道ですとか、東京都の計画でしかこの情報は知り得てございませんので、当面が何年なのかというのは今の段階では申し上げるときではないというふうに思ってあります。","voiceIndex":304,"id":"exchange-134"},{"speaker":"三上委員","kind":"質問","question":"１５２ページの教育指導費、１５４ページ、まちの人々から学ぶ授業、同じく１５４ページの教育総務費という感じになるんでしょうか、それから１５７ページ、卒業記念アルバム、時間がちょっとないかもわかりませんが、もしあれば、学校の改築に関する件でちょっとお聞きしたいと思います。順番が違いますが、最初に、まちの人々から学ぶ授業ということでちょっとお伺いしたいと思います。","respondent":"中島指導課長、谷田部学務課長","answer":"プラン２１のまちの人々に学ぶ授業の実施の状況です。小学校、中学校すべての学校で実施をしています。小学校ですけれども、一番高いところで２万６,０００円、一番安いところで１万２,２００円、平均で小学校は１万６,０００円、中学校ですけれども、安いところでは９,０００円で、一番高いところでは１万７,５００円。","voiceIndex":307,"id":"exchange-135"},{"speaker":"三上委員","kind":"質問","question":"その中で実際に来てくれて、そして話をしてくれる、こういった方については、ボランティア的なんでしょうか。それから、物によっては、いろいろなものを持ち込まなければならないものもあると思いますけれども、そういった部分についての費用についてはどういうふうになっているんでしょうか。ですから、そういったことも含めて、ぜひ検討をされたらどうかと思いますが、いかがでしょうか。","respondent":"中島指導課長、谷田部学務課長","answer":"各学校の取り組みは非常に多くありますので、この限度はかなり早い時点でクリアされてしまう状況はあるかなと思ってありますけれども、中にはボランティアでということでご辞退される方もいらっしゃるということで。その辺の調整をどうやってとっていくかというのがなかなか難しい問題があります。一方で、ある中学校ですけれども、私どものほうにデジタルカメラを何台か欲しいというような予算の要望がございました。","voiceIndex":310,"id":"exchange-136"},{"speaker":"三上委員","kind":"質問・要望","question":"その人はボランティアとして私は要りませんと言っても、その人がさらにお借りした人についての謝礼をしなければならないということもあるわけですから、ケース・バイ・ケースで、そういうような人についてはしっかりと相談に乗った、きめ細かな対応をしてあげていただきたいなと。これはぜひやっていただきたいと思います。受ける立場はこうなんだということを、簡単でいいですから、お願いします。","respondent":"南監査委員事務局長、市川庶務課長","answer":"そういう意味で、どういう組織でも事務処理の基準があって、組織的に内部統制といいますか、一人だけで事務処理をするわけではなくて、それぞれの機関の審議を経て決定して、事務処理を行っているわけですから。指摘事項のほとんどがルールに則った事務処理ができていない、あるいは計画的な事務事業の執行ができていない、いわば事務の基本にわたる部分が原因にわたっていることが多い、このような実情を受けて。","voiceIndex":313,"id":"exchange-137"},{"speaker":"三上委員","kind":"質問","question":"しっかりと指摘をしていただいているようでありまして、その中で支払いが遅れているということがありますよね。民間ではとてもじゃないけれども考えられない。手形を発行しているんじゃないかぐらいの納期、支払いまで５カ月以上かかっているとかというのがあるわけですよね。品川区でそういうような納品制度というのはあるんでしょうか。","respondent":"市川庶務課長","answer":"そのようなことはございません。","voiceIndex":316,"id":"exchange-138"},{"speaker":"三上委員","kind":"質問","question":"今回の指摘を受けているのも１校だけじゃないですね。それこそ支払いが３カ月以上も経っているなんて、とてもじゃないけれども、公金を支払っている立場としては、これは認めるわけにいかないんじゃないでしょうか。しっかりとそういった約束が守られていくということが、これは管理、監督という部分について、この責任というのはどういうふうに受け止めていったらよろしいんでしょうか。","respondent":"市川庶務課長","answer":"そういう意味では、担当の事務職員はもちろんのこと、現場の管理監督者の職務意識の希薄な面というのがあろうかと思います。今後教育委員会といたしましては、そういった職務意識の覚醒と申しましょうか、そういうことも含めて対応をしてまいります。","voiceIndex":318,"id":"exchange-139"},{"speaker":"三上委員","kind":"質問・要望","question":"そういう部分をきちっと受け止めた上で、どう取り組んでいっていただけるか、これは本当に来年の３月までの課題として、学校長、教頭の責任はどうするのか。それから、学校事務の職員はどのような仕事をやったらいいのか、非常勤はどのようにして補助として仕事を手伝っていくのか、こういったことについて明確にしていっていただきたいと、お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":320,"id":"exchange-140"},{"speaker":"原委員","kind":"質問・要望","question":"最後で、１０分ですので、１点だけお伺いをさせていただきたいと思います。学校によって大小いろいろ種類も多岐にわたっていると思うし、あるいは多い、少ないもあると思うんですが、学校の樹木に対する考え方はどういうふうにお持ちになっていらっしゃるか、伺います。","respondent":"市川庶務課長","answer":"そういう意味で地域環境の保全という面からも、あるいは子どもたちへの教育活動という面からも、緑を大切にしていく、こういうことが基本になろうかというふうに考えてあります。","voiceIndex":322,"id":"exchange-141"},{"speaker":"原委員","kind":"質問","question":"まさに樹木、緑もそうですし、地域の環境をよくし、そして学校の環境もそこに加味されてくるわけですけれども、今般各学校の改築に入っていますね。それから、小中一貫校もそこの中に入ってきているわけですが、私が今お伺いしたいのは、伊藤中学校が今度小中一貫で改築が始まるわけですけれども、ここにおける樹木は全部で１５９本と調査によって出てきております。","respondent":"市川庶務課長","answer":"先ほど申し上げました樹木の健康診断をいたしますと、ほとんどの樹木について移植ができない。したがって、伐採せざるを得ないという、今のところそのような結論を得ているわけです。","voiceIndex":324,"id":"exchange-142"},{"speaker":"原委員","kind":"質問","question":"確かに木の状況から言って伐採しなければならないような状況なんでしょうけれども、１６０本ある木のうち半分以上を伐採するということは異常じゃないかと思うんです。移すのが４本だけですから。ただ、歩道上空地による伐採は残せる部分があるんじゃないかと思うんですが、いかがでしょうか。","respondent":"市川庶務課長","answer":"これについては、むしろ移植をして植え替えるよりは、新しい植栽計画のもとで新しい学校づくり、新しい環境づくりということで対応したほうがベターではないかということで、伐採ということを考えているものです。","voiceIndex":326,"id":"exchange-143"},{"speaker":"原委員","kind":"質問","question":"そうすると、木の性格上そういうところも出てくるわけですけれども、新たに計画的に植えるのがどのぐらい出ているんでしょうか。","respondent":"市川庶務課長","answer":"植栽については、これからの計画づくりということになってあります。","voiceIndex":328,"id":"exchange-144"},{"speaker":"原委員","kind":"質問・要望","question":"伐採するだけがすべてではないと思うし、これから中でしっかり植栽の部分も考えていただきたいと思います。それから、伊藤中学校はしいの木が象徴的な木ですが、これがなくなっちゃうわけなんですよ。しいの木会という会もあるんですけれども、それもなくなっちゃう。そういったものも、ある一方のところでは残しておけるような形をぜひつくっていただきたいと思うんですが、いかがでしょうか。","respondent":"市川庶務課長","answer":"ただ、今回この木のこれまでの歴史と申しましょうか、それを最大限考慮いたしまして、一たん根の直近の上のところで切りまして、いわば根を残して、俗に言う、やごが新たに生えるか生えないか、その様子を見て本格的な対処と申しましょうか。","voiceIndex":330,"id":"exchange-145"},{"speaker":"原委員","kind":"質問・要望","question":"いずれにしましても、伊藤中学校とよく相談をされて、しいの木、例えば新しく植えるということも考えられるわけですから、残すだけではなく、そういったところも新生小中一貫校としての生まれ変わりということもあるわけなんで、十分その辺も考慮をされて、それから、これから改築されるような学校も、それにあたるような象徴的なものも出てくると思うので、その辺も考慮しながら進めていただきたい。","respondent":"林（和）委員長","answer":"以上をもちまして、本日予定の審査はすべて終了いたしました。次の会議は１０月１９日、午前１０時から開きます。本日は、これをもって閉会をいたします。","voiceIndex":332,"id":"exchange-146"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1238#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":120594,"voices":333}},{"id":"h16-20041019-4","meetingId":"h16-c-settlement","date":"2004年10月19日","dateIso":"2004-10-19","committee":"決算特別委員会","time":"午前１０時１５分～午後６時４６分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を144件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"田中委員","kind":"質問・要望","question":"おはようあります。私は、地方分権の推進、都区制度改革の際に残された課題、いわゆる主要５課題の解決につきまして質疑を行ってまいりますが、この解決に当たりましては、区民のご理解とご協力が不可欠であるとの考えから、５課題の内容や論点の再確認も行いながら質疑を行ってまいりたいと考えていますので、よろしくお願い申し上げます。","respondent":"市岡企画財政課長","answer":"ご質問のとおり、地方分権一括法あるいは平成１２年の都区制度改革によって、事務事業の面では区の権限、あるいは事務の内容が拡充したわけですが、これからは財政自主権の確立、三位一体改革あるいは財調の残された課題。","voiceIndex":2,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"そのことによって、逆の意味で地方分権が逆の方向に行ったことによるデメリットもこういった部分に起きているのではないかというふうに思われますが、その状況についてお聞かせをいただきたいと思います。","respondent":"山田区民生活事業部長","answer":"今後も保険料の催告のために市区町村と連携を図り、税情報、住基情報の突合を務めていきたいということと、また区民の皆様にも年金納付の情報を定期的に通知を差し上げるなど、きめ細かなサービスの提供を実施すると伺ってありますので。","voiceIndex":4,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"平成１２年にご案内のとおり都区制度改革、大きな成果がなされました。品川区初め、特別区としてはこれまでの東京都の内部団体から基礎的な自治体として移り変わりましたが、このことによって、改めて確認ですが、品川区としてどのような変化があったのか、また区民生活上、区民にとってどのようなメリットがあったのか、お聞かせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"これらを使いまして、先ほど挙げた例もありますが、例えば都市計画公園の計画決定をした後、事業が実施されるまでの間、この土地を有効に使うことができないだろうか、こういう権限はこれまで都知事の許可でございました。","voiceIndex":6,"id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"五つありますが、いわゆるこれが主要５課題というふうにされておりますけれども、その平成１２年の都区制度改革の際に主要５課題が残されてしまった、その経過、経緯あるいはそのまず５課題の内容について基本的なところですが、ご説明をいただきたいと思います。","respondent":"市岡企画財政課長","answer":"そのためには都と区の役割を明確にする、これが１点です。それから、平成１７年という時限を切りましたが、それまでの間でも大きな税制改正等があれば、役割分担等に応じた財源配分を変更する。","voiceIndex":8,"id":"exchange-004"},{"speaker":"田中委員","kind":"質問・要望","question":"今ご説明いただきました５課題の解決が品川区にとって、また品川区民にとってどのようなメリットがあるかという、そういった視点から個々にお伺いをしてまいりたいと思います。改めまして、その理由、ある種これが解決すれば、ほかも大きく転換するんではないかという思いもありますが、その辺のことについて、受けとめ方をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"２３区の側の仕事、経費の内容というのは、それまでも非常に明らかになっておりましたが、先ほどの都区共通の税の配分であります財調制度の配分率でいうと、東京都に残された４８％の内容、これはなかなか区民、区のほうからは見えない内容です。","voiceIndex":10,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"まさに今ご説明いただいたように、大都市事務の範囲、内容について、まず都区で確認をすること、またその大都市事務をいかに都と区の間で役割分担を明確にしていくか、それに基づいて財源配分がなされるのだろうと考えていますが、今までもさまざま大都市事務の内容について都区間での協議がなされたと考えていますが、それぞれのいわゆる論点、都側。","respondent":"市岡企画財政課長","answer":"したがって、どうしても使わなければならないかどうかの説明責任は東京都にある、東京都が区それから区民に対してこういう説明を行うべきだ、こういう主張をしています。","voiceIndex":12,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"まさにこれは大都市事務の議論はこのままいくと東京都にもちょっと分が悪いという思いからだろうというふうな推測はされますが、最近になって大都市行政論を東京都が展開してきておりますが、改めまして、この持ち出してきた背景をどのように受けとめていらっしゃるのか、また内容についてお聞かせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"これは東京都の意見ですので、私どものほうでご答弁することが適切かどうかはありますが、いずれにしても東京都は都が行う大都市事務の範囲を大きく広げておけば、それだけ財源が確保できるという観点に立っていることはこれは否定できないだろうというふうに考えてあります。","voiceIndex":14,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"続きまして二つ目の課題ですが、先ほどありましたように、平成１７年度までに大きな制度改革がなされた際の配分割合の変更ということが課題だというふうにご説明いただきましたが、ここでいう、まず制度改革、具体的には何が想定されるのかをお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"しかし、今のところ、まだ区側が５２％という財源配分の変更は行われておりませんので、これから三位一体改革が具体化していく段階に従って、この都区双方に生じた税財政制度の変更というのは、大きな財源配分変更の理由になるもの、このように考えているところです。","voiceIndex":16,"id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"現在まさに三位一体改革は国会を中心に議論がなされ、方向性がまだはっきりとしていない段階でありますが、おおよそ言われている国庫補助金あるいは交付税交付金の削減またはそれに対する税源移譲ということで三位一体改革ですが、三位一体改革が行われて今の課題となっております、それの変更に伴う配分割合の変更がなされないときに、品川区にはどのような影響が想定されるのか。","respondent":"市岡企画財政課長","answer":"このように、都と区に双方に影響するものについては、先ほど申し上げた大きな税財政制度の変更という形できちんと財源配分に影響額を精査をいたしまして反映させる必要がある。","voiceIndex":18,"id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"特別区が清掃事業を行うに当たり、７４５億円がまだ都のほうに残ってしまったですが、平成１２年に移管された際に、これが逆に都に残ってしまったことの影響はどのようなものがあるのか、また今回の主要５課題が解決されたことによって、いわゆる７４５億円分が特別区側に移管された際に、現在行われている清掃事業等がどのように変化し、また区民にとってメリットがあるとお考えなのか。","respondent":"市岡企画財政課長","answer":"ご質問の清掃事業の関連経費７４５億円、これは本来は都区財政調整の中の配分率に反映されるべき金額です。当時東京都もこれは配分率にして５％に相当するというふうに説明をしておりました。これが当時財源配分に反映されなかったのは、要は技術的な理由だけです。","voiceIndex":20,"id":"exchange-010"},{"speaker":"田中委員","kind":"質問・要望","question":"移管された事業が区民にとってよりよい形になるためにも、この財源も区に移管することが必要だろうと改めて確認をさせていただきました。四つ目の課題であります小中学校の改築需要急増への対応についてであります。これまでの財調制度のもとでの小中学校の改築需要に対する算定の、まずは考え方をお聞かせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"しかし、実際には今後２３区全体ですけれども、この２０年間で建て替える必要が出てくる、築後５０年以上経過した学校というのは全体で９００校ございまして、今のこの平均的な算定の仕方では、ピークのときに対応できない、こういう事情があるものです。","voiceIndex":22,"id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、我が品川区におきましては、この５０分の１ずつ毎年財調手当をなされておりますが、その対応といいますか、聞くところによると、他区においては本来これを改築の際に使用するために基金として積み上げていかなくてはいけないところを、品川区はきっちりと対応されていたというようなことも伺っておりますが、改めてこの点についてお聞かせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"この学校改築、小中一貫校に備えるために実施計画の中で具体的な整備計画を立てまして、それにあわせてこれまで算定されていた財調の原資も含めて、現在義務教育施設整備基金、これを品川区は１３５億円、平成１５年度末で保有をしています。","voiceIndex":24,"id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"当面の考え方ですが、もしこの５課題の一つでありますこの点が解決しなかった場合、区の影響はどのようなものがあるのか、現在義務教育施設整備基金があるですが、そうすると、これだけに頼らざるを得ないかと思いますが、その辺の状況についてお聞かせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"この義務教育施設の改築に関しては、実はこの５課題の中では、東京都もやや区側の説明といいますか、考え方に理解をしているところでございまして、問題は、金額が都区で大分見解が違いますけれども、したがいまして。","voiceIndex":26,"id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"学校の耐用年数５０年と伺っております。５番目の都市計画交付金のあり方についてでありますが、現在行われている都市計画事業、東京都あるいは区でそれぞれで行っておりますが、この事業の事業量とまたその財源の割合について、お聞かせをいただきたいと思います。","respondent":"市岡企画財政課長","answer":"ところが、実際の都市計画税を配分しております都市計画交付金と申しますが、これは税の総額が直近のところでは平成１６年度の予算額で１,８８２億円、２,０００億円弱ですが、そのうち都市計画交付金として区に交付されるのは１５０億、率にいたしますと８％ですので。","voiceIndex":28,"id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"この８％の根拠も、そういう意味では何ら明確にはなっていないと考えていますが、品川区として、これまで都市計画事業を実施する上で今のように８％しか来なかった、その中でも２３区の配分がありますけれども、本来もっと入るべきものが８％分しか来なかったことのデメリット、あるいはその都市計画事業を行う際の不都合な点があったのかどうか、またこれについて、もしこの課題が解決することによって。","respondent":"市岡企画財政課長","answer":"２３区の中では、品川区は実は都市計画事業を積極的にやっている区でございまして、例えば目黒線の立体交差、その他都市計画道路を推進しています。","voiceIndex":30,"id":"exchange-015"},{"speaker":"田中委員","kind":"質問・要望","question":"大変品川区は東京都の中心的位置に占めておりまして、いわゆるまさに都市計画事業を推進することがこのまちづくりの発展、地域のためにつながるものと確信をしておりまして、今お話にあった４分の３が逆に自前の都市計画税が入ることによって、ほかの行政サービスの提供にもつながるですので、この課題についてもぜひ取り組んでいただきたいと考えていますが。","respondent":"市岡企画財政課長","answer":"そういう場ではたびたび区側からの申し入れをしていたわけですが、共通の場でなかなかこれだけ大きい問題を協議することは難しいだろうということで、もっぱらこの５課題だけを検討する組織を立ち上げる、こういうやりとりがありまして、結果的に３年間を経過したわけですが。","voiceIndex":32,"id":"exchange-016"},{"speaker":"田中委員","kind":"質問・要望","question":"現在、都知事は、地方分権の推進に向けて積極的に国と闘っております。ある意味、これと同じ構図が我々と東京都の間にもあるのではないかと考えていますが、積極的な都知事のもとで、ある意味では一番地方分権に消極的なのが東京都ではないのかなというふうに思っておりますが、この部分についてのご見解をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"私どもは、これをそっくり東京都に申し上げたい、こういうふうに主張しているところでございまして、いわば都区のこの主要５課題をめぐる改革というのは、都と区の間での分権改革そのものですので、真の分権改革につながるような改革に誠意を持って取り組んでいただきたい。","voiceIndex":34,"id":"exchange-017"},{"speaker":"田中委員","kind":"質問・要望","question":"我々としては、もう既に都知事あるいは都議会に対してもいつでもアクションを起こせるような機運が高まっておりますが、さきに行われました１０月１４日に区長会の役員の方々あるいは議長会の役員の方々との話し合いの結果をもって次のアクションを起こすべきかどうするかを考えようというような状況であろうかと思いますが、まずは１０月１４日の役員会の内容についてお聞かせをいただきたいと思います。","respondent":"高橋区長","answer":"１４日の議長会役員と区長会役員との合同の懇談会ですが、今、企画財政課長からるる説明がありました。内容につきまして議長会のほうにご説明をいたしました。","voiceIndex":36,"id":"exchange-018"},{"speaker":"田中委員","kind":"質問・要望","question":"それで、その先ほど区長のお話がありましたように、国に対する平成１２年の改革のときに、あれだけの動きがあった中で、相手としては国ではなく東京都なので対応しやすいというお話ではありましたが、まだ全体的な機運が前回と比較すると、それほどでもないのかなと、お聞きするところによると、また１２月あるいは１月に東京都から出てくる検討結果を受けて。","respondent":"高橋区長","answer":"この問題に対しまして東京都とどのような対応をしていくかという具体的な問題につきまして、これからいろいろと各区で協議を進めるところですが、私は平成１７年度に向けましての財調問題、平成１６年度都区協議会が行われます。","voiceIndex":38,"id":"exchange-019"},{"speaker":"田中委員","kind":"質問・要望","question":"若干、視点を変えてまいりますが、品川区がさらなる地方分権を進め、独自性を発揮していく上で、この５課題の解決ももちろんでありますが、もう一つ、やはり今までの東京都の垂直調整の関係から今も区長にも少しお話がありましたが、水平調整をいかにスムーズに行っていくか、そういう仕組みづくりをしていくか、東京都に何ら心配なり変な横やりが入らない中で。","respondent":"高橋区長","answer":"したがいまして、水平調整が難しいという問題はそう私はないんじゃないかと考えています。例えば水平調整をやる場合に、区間の問題の中で公平な外部の委員を入れてやる場合もありますし、また東京都も中にいつも入っていただいて、やることも可能だと考えています。","voiceIndex":40,"id":"exchange-020"},{"speaker":"田中委員","kind":"質問・要望","question":"大変力強いお話を伺いました。ぜひ、都民であるよりも区民でいることが本当にいいんだというふうに思っていただけるように、改めて最後に区のご見解、またこの問題の解決に対する意気込み、そして最後、区民に対するメッセージをお聞かせをいただきたいと思いますので、よろしくお願いいたします。","respondent":"高橋区長","answer":"したがいまして、区がより区民の皆様にとってすばらしい区であるように、住んでよかったと思われるような区にするためには、この財源の財政の改正が一番大きな問題だと考えていますし、適切な方法で区民にＰＲしてまいりたいと考えています。","voiceIndex":42,"id":"exchange-021"},{"speaker":"本多委員","kind":"質問","question":"田中委員に引き続きまして、自由民主党品川区議団の総括質疑を続けします。教育について、主に学校教育を伺います。小学校５年生を対象として、昨年平成１５年度から実施されております経済体験学習、スチューデント・シティは、その格好の機会であると思います。そして、中学生の場合は職場体験を通して何種類かの職業を体験することが重要だと考えますが、この点についてお聞かせください。","respondent":"若月教育長","answer":"まさにこの認識は全く私どもも同感です。学校というのは、とかく学校で学ぶことと勉強することと、子どもたちが実際に社会に出て生きるということがどうも分離する傾向があります。","voiceIndex":45,"id":"exchange-022"},{"speaker":"本多委員","kind":"質問・要望","question":"経済や社会の仕組みを実際に体験しながら学び、企業や店舗の経営者になったり消費者になったり、さまざまなかかわりの中で社会が成り立っているということで、この学んだ適性について、児童・生徒自身の認識と学校側から見た認識、その辺についてどのようにとらえているのか、また、中学校の何種類かの職業、複数についての職場体験をしていく中で、実施前の選定と実施後の思いというんでしょうか。","respondent":"若月教育長","answer":"この中学生の職業体験の実施前、実施後のことでありますが、これはかなり明確になっておりまして、かなり具体的な進路指導といいましょうか、職業指導といいましょうか、そういったような目的に直接結びつくような反応を示す子どももいれば、例えばこういう仕事をしたい。","voiceIndex":47,"id":"exchange-023"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ、いろんな可能性を秘めていますので、よろしくお願いしたいと思います。学校における安全管理の現状について、それをお聞かせいただきたいのと、そしてすべての児童・生徒への指導としてロールプレイを行う必要性について伺うのと、これまでのロールプレイの取り組みについて、指導についてお聞かせいただきたいと思います。","respondent":"若月教育長、小沼児童保健事業部長","answer":"多くのこれは特に警察のお力をかりることが多いわけですけれども、そこでさまざまなロールプレイで実際に具体的な場面に対する対応の仕方といったようなことを、すべての学校で実施をしています。そういう状況の中での情報交換あるいは意見交換、さらには保育園あるいは幼稚園等を使っての寸劇等々を活用しまして、暴力対策、それから、最近では虐待の問題がありますけれども、そういうところに啓発活動を行っている。","voiceIndex":49,"id":"exchange-024"},{"speaker":"本多委員","kind":"提案","question":"地域安全マップの作成ですとか防犯訓練のプログラム、ＣＡＰは答弁をいただいたように家庭あんしんセンターによるものなどで実証されたり、また半数が研修ということだったんですが、主にＰＴＡとかが自主的に取り組むものだと私は思っているんですが、そういったことを品川区議会でも数年前、５年ぐらい前からでしょうか、超党派により提案がありまして、教育委員会としての答えは検討をしていくですとか。","respondent":"若月教育長","answer":"ＣＡＰについてでありますけれども、あるいはロールプレイもそうなんですけれども、これは具体的な対応や行動の仕方、これを子どもたちに体験を通して学ばせる、これが大きなねらいであります。","voiceIndex":52,"id":"exchange-025"},{"speaker":"本多委員","kind":"質問・要望","question":"ぜひ前向きな取り組みをお願いしたいと思います。その取り組みに当たりまして、就学前の子どもに対応してやっているところもあるということなんですが、まずは大人への対応も取り組んでいただきたい、大人といっても、まずは身近なＰＴＡからですとか、子どもに携わる教職員ですとか、そういうところから進めていただきたい、大人への対応ということではそういうふうに思うんですが、いかがでしょうか。","respondent":"古川教育次長","answer":"そして次年度に向けまして、これはまた来年度のことでありますけれども、小Ｐ連のほうからもこのＣＡＰについての大きな教育委員会の支援、こういうお話も伺ってありますので、私どもはこのＣＡＰについては。","voiceIndex":54,"id":"exchange-026"},{"speaker":"本多委員","kind":"質問・要望","question":"それで、子どもの安全を考えるときに、学校と保護者、地域が一体となって子どもを取り巻く環境を整備をしていくことが必要ですが、その一つとしまして、款別審査でも出されておりました朝のあいさつ運動、コミュニケーション活動の活性化を、今まで取り組まれているあいさつ運動はＰＴＡの自主的なものでありましたり、地域センターが学校と連携をして行われているもの、それぞれあると思うんですが。","respondent":"若月教育長","answer":"もちろんこうした運動を進めること、広げることについては、教育委員会も大いにその役割を果たしていきたい、こう考えているところですが、地域の方々にそうしたところも深く理解をしていただき、より地域に根差した。","voiceIndex":56,"id":"exchange-027"},{"speaker":"本多委員","kind":"質問・要望","question":"コミュニケーションについて、地域力ということで、ちょっと一例を挙げしますと、学区域の自由化が進み、本当にすばらしいことだと思うんですが、きめ細やかな対応をお願いしたいと思うんですが、一つ挙げますと、地域センターの親子レクリエーション運動会で、小学校で配られるチラシで親子で参加してくださいという周知を各学校でされますが、そのチラシを見て親子で参加をされても。","respondent":"古川教育次長","answer":"私どもは学校を一つの拠点とした活動、そしてもう一つは地域というものを拠点とした活動、両方が成り立っていくように、さまざまな形で連携をとりながら、ただ委員のほうからご指摘がございましたような点につきましても、今後工夫をしてまいりたい、このように考えてあります。","voiceIndex":58,"id":"exchange-028"},{"speaker":"本多委員","kind":"質問","question":"続きまして、学校週５日制について伺います。学校週５日制が平成１４年度から完全実施となって２年半が過ぎました。学校でのカリキュラムや行事の実施状況についてお聞かせください。問題点、課題点についてはどのようにお考えでしょうか。","respondent":"若月教育長","answer":"初めは随分心配しましたけれども、おかげさまで教育課程の実施、それから学校行事の実施につきましては、各学校がそれぞれの保護者、地域、子どもの実態、そうしたものを勘案しながら、そういう意味では今まで以上に充実した内容で、それぞれを展開している。","voiceIndex":60,"id":"exchange-029"},{"speaker":"本多委員","kind":"質問・要望","question":"ゆとりで始まりましたけれども、時間２割短縮、内容３割短縮、各自治体、各教育委員会で対処、工夫をされているものの、現状でよいのか、今後の方向としてお伺いいたしますが、区内外を問わず、私立で例えば中高６年間の一貫をされている場合、あえて週６日制を貫くわけとして、時間をかけた教育こそが必要で、じっくり時間をかけて育ったものは大地にしっかりと根を張ると持論を展開されておりますが。","respondent":"若月教育長","answer":"したがって、必ずしも私立が６日やっているから、じゃあ公立も６日やったらどうだろうかと、そういったような考え方もありますけれども、品川区は品川区で、今申し上げましたような具体的な幾つかの手を使いながら、その学習活動を展開しているところでありますので。","voiceIndex":62,"id":"exchange-030"},{"speaker":"本多委員","kind":"質問・要望","question":"この休日の使い方、今では土曜日は休日ですが、土曜スクールですとか、ぜひいろんな意味で工夫をして進めていただきたいと思います。続きまして環境教育について伺います。学校版環境ＩＳＯを初めとする学校における環境教育の取り組み状況についてお聞かせください。環境から学ぶ、環境について学ぶ、環境のために学ぶ、三つの目標から見て、どのようになっているでしょうか。","respondent":"若月教育長","answer":"私どもが聞いているところでは、その成果といたしましては、子どもたちが学校の生活の中だけではなく、それぞれの家庭に帰ってからもその家庭の中で学校で体験したことをそのまま家庭の中で使って環境といったようなものに対する配慮。","voiceIndex":64,"id":"exchange-031"},{"speaker":"本多委員","kind":"質問","question":"夏休みなどの家庭で考える環境で、節水ですとか節電ですとかごみの減量化ですとか、いろいろと進められていると思うんですが、家庭によっては環境家計簿なんていう、そんなやり方もあるようなんですが、学校のエネルギーとして太陽光、太陽熱、風力、コジェネレーションシステムなどのエネルギーを活用しての環境教育としての太陽電池時計ですとか、照明の電力にソーラーパネルを使用するですとか。","respondent":"古川教育次長","answer":"試みとして、これから新しく改築する学校の中で、そういったものも検討していきたいなという部分はありますが、具体的にそういったものを今学校の中で直接、現実のエネルギーの代替として使っている例はございませんけれども、今後検討してまいりたい、このように考えております。","voiceIndex":66,"id":"exchange-032"},{"speaker":"本多委員","kind":"質問・要望","question":"例えば３階建ての校舎でしたら屋上４階部分に天然芝なんかを使って３階の効果とかがわかるような種類、セダムだったら本当に効果があると思いますので、その辺は検討していただきたいと思います。続きまして、教育改革プラン２１について伺います。こうした方法は学力の向上に有効な手段と考えますが、区の教育委員会としても一部を取り上げられておりますが、改めて見解をお伺いいたします。","respondent":"若月教育長","answer":"品川区が今進めておりますこの教育改革でありますけれども、この基本的なコンセプトの一つに、平たくいうと公立学校の信頼といったようなものをもう１回よみがえらせようじゃないかというのがその根底にあるわけであります。","voiceIndex":68,"id":"exchange-033"},{"speaker":"本多委員","kind":"質問・要望","question":"我が党同僚議員で、神奈川県の桐陰学園の教育改革について学んでまいりました。中高による中高一貫とは別に、さらに進んだ中高による中等教育学校というものを行っておりました。この桐陰学園ではそういったことをされているということで、これは我々は学んで、決して差別なんていう、そういった発想は全く出てこないんですね。学ぶと同時に。そういったことについて、お聞かせいただきたいと思います。","respondent":"若月教育長","answer":"そこで今日は余り説明する時間はありませんけれども、基本的に結論から申し上げますと、私はそれぞれの子どもたちがそれぞれの能力に応じた教育を受けることができるというのが憲法にも教育基本法にも書いてあります。したがいまして、それを差別だとは全く思いません。","voiceIndex":70,"id":"exchange-034"},{"speaker":"本多委員","kind":"質問・要望","question":"ハード面ではまさに人、物、金、情報、ソフト面では９年間４・３・２の連続性、継続性のある教育活動、そしてその内容を全校にということで、また人間らしい生き方についての自覚を深め、自己を生かす能力と社会性を身につける学習としての市民科が期待されておりますが、小学校、中学校の方向性について、改めてこの全区展開ということについてお聞かせをいただきたいと思います。","respondent":"若月教育長","answer":"これは従来の道徳と特別活動といったようなものの時間を一緒に合わせて、そして新たな市民、健全な市民を育てる、その市民としての教養を身につけるという意味で行うものでありますけれども、こうしたものも教員の研修とカリキュラムの作成を、平成１６年度。","voiceIndex":72,"id":"exchange-035"},{"speaker":"本多委員","kind":"質問・要望","question":"小中一貫校、いろいろ学校のこれからの進めていく中で、なかなか大崎、大井からその後のことがなかなか答弁をいただけなかったんですが、これから例えば国有地を取得する方法、この間、４分の１になったというすばらしい話を伺いましたが、国有地をこの使途変更をした自治体があって、本来だったら学校という使途を変更したら手続をしなければいけないのに。","respondent":"古川教育次長","answer":"小中一貫校につきましては、大崎、そして大井地区、次にということは私どもも十分に今検討しています。学校の用地につきましても、区が使用している土地もあれば、今、委員のほうからご指摘がございました国有地、あるいは民有地も一部あります。","voiceIndex":74,"id":"exchange-036"},{"speaker":"本多委員","kind":"質問・要望","question":"いろいろな手法があると思いますので、視野を広げていただきたいと思います。それで、大崎地区の小中一貫と大井地区の小中一貫の学校名を今までなかなか検討中ということだったんですが、その後どのようになったのか、また制服ですとか規律についてどのようにお考えか、それと大崎地区の総合体育館の跡地利用について、現況のお考えをお聞かせください。","respondent":"古川教育次長","answer":"いずれにいたしましても第二日野小学校と日野中学校は学校の名称としては残るわけですが、一貫校としての対応を具現化した名称は考えていきたい、こういうふうに考えております。","voiceIndex":76,"id":"exchange-037"},{"speaker":"本多委員","kind":"質問・要望","question":"大崎地区の小中一貫の完成に合わせまして、周辺の通学路ですとか、歩行者、自転車、バイク、車などの安全管理の充実については区議会でも既に取り上げられております。この点の整備点検をあわせてお願いしたいのと、総合体育館跡地利用につきましては、人の誘致、観光、産業振興、あらゆる角度から検討に入り、ぜひ目玉となるような企画をしていただきたいとまず改めてお伺いいたします。","respondent":"中尾根企画部長","answer":"したがいまして、区といたしましても、そうした動向も見据えながら、よりよいまちづくりのため、よりよい品川区の将来の活用のために検討してまいりたい、このように考えてあります。","voiceIndex":78,"id":"exchange-038"},{"speaker":"本多委員","kind":"質問・要望","question":"わかりました。最後に品川の歴史、伝統を伝えるために何点かお聞きします。品川の由来について、お聞かせいただきたいと思います。","respondent":"古川教育次長","answer":"幾つか事例を出してみますと、例えば隣の村、高輪に対しまして地形がよかったということで、品が輪、輪は高輪の輪ですが、そういう説、あるいは目黒川を古くは品川と称したということから、この川からの起源、あるいは鎧のおどしに用いる革。","voiceIndex":80,"id":"exchange-039"},{"speaker":"本多委員","kind":"質問・要望","question":"説は確かにたくさんあると思うんです。１２世紀、この地域に貴族が住みつき、名字に大井とつけ、大井氏の弟が領土の一部を譲り受け、領土、名字ともに品川と名づけられて、後に品川氏は源氏方として源平合戦に出陣したとありますが、こうした特定はできませんが、有力説について、改めて品川の観光資源といいますか伝えていくということで、お聞かせいただきたいと思います。","respondent":"山田区民生活事業部長","answer":"ただいま品川という名称そのものを一つの由来として観光に生かしたらどうかというご提案ですけれども、今後、しながわ観光協会と十分協議をしながら、いろいろなイベントの中で由来のご紹介という形でもできるかと思いますので、検討します。","voiceIndex":82,"id":"exchange-040"},{"speaker":"山路委員","kind":"質問","question":"質問の内容は、次世代育成支援対策推進法に基づく行動計画策定について、１３カ所の各地域センターで事業を展開しているふれあいサポート活動について、ヒートアイランド対策について、地域再生、都市再生を有効活用したまちづくり構想についてお伺いをいたします。初めに、次世代育成支援対策推進法が制定された背景と法案の趣旨について、お伺いをいたします。","respondent":"中尾根企画部長","answer":"そこで、新しい時代を担う子どもたちを健全に、健やかに生まれ育てる環境をつくろう、そういうことで、国、地方自治体、企業、それに区民といいますか、それぞれがより今まで以上に積極的にそうした少子化対策に取り組んでいこう、こういうことを趣旨しているものです。","voiceIndex":88,"id":"exchange-041"},{"speaker":"山路委員","kind":"質問","question":"この法案は１０年間の時限立法でありますが、同法で定める行動計画策定指針に即して地方公共団体等において平成１７年４月１日から実施できるように行動計画を策定することが義務づけられております。そこで、策定に関する八つの基本的事項の視点と品川区の取り組み状況について、お伺いをいたします。","respondent":"中尾根企画部長","answer":"区の取り組みですけれども、同法の趣旨を生かしつつ、これまで品川区が培ってきた施策、それらの独自性を発揮した体系として計画としてつくりたいと考えておりまして、本年の８月に次世代育成支援対策推進協議会、これを設けまして、この中で原案について検討していく。","voiceIndex":90,"id":"exchange-042"},{"speaker":"山路委員","kind":"質問・要望","question":"ただいまご説明をいただきました八つの視点についてはわかりました。その説明の中で、推進協議会ですが、どのような方に委員を委嘱されているのか、参考までにお知らせいただきたいと思います。そしてまた８月４日から約３カ月間、日にちがたっておりますが、その間の進捗状況について、策定までの今後のスケジュールについてお伺いをいたします。","respondent":"中尾根企画部長","answer":"委員会については８月にスタートさせましたけれども、この間原案を協議会でつくっていただきたいという依頼をしまして、それについてのこれまでの品川区の取り組み等の報告と多少の意見交換を行っておりまして、この委員会の中で、１０月中までには原案をつくって、その後。","voiceIndex":92,"id":"exchange-043"},{"speaker":"山路委員","kind":"質問","question":"公募委員は５名ということでございましたが、この中でどのように選任されたのか、その中に専業主婦の方、あるいはサラリーマンの方が委員になっているかどうか、重ねてお伺いをいたします。","respondent":"中尾根企画部長","answer":"専業主婦、それからサラリーマン、こういう選考基準で選んでおりませんけれども、委員の中には女性が８名おりますので、それぞれの皆さん方は子育ての経験もありますし、専業のときもございました方もいますので、そういう声は代表されると思いますし、サラリーマンについても。","voiceIndex":94,"id":"exchange-044"},{"speaker":"山路委員","kind":"質問","question":"１１月から１２月にかけて予定されているパブリックコメントについてですが、どのような方法で区民の意見を反映させるのか、お伺いをいたします。","respondent":"中尾根企画部長","answer":"周知の方法につきましては、広く行政の窓口にパンフレット等を置きまして周知するとともに、意見そのものにつきましては、広くということでは広報を通じまして中心に意見を公募していきたいというふうに思っておりますが、そのほか、ＣＡＴＶの放映であるとか、それから。","voiceIndex":96,"id":"exchange-045"},{"speaker":"山路委員","kind":"質問","question":"２カ月という短期間で幅広く区民からの意見を徴収する方法として、ホームページでと言われましたけれども、ホームページの掲示板とかメール送信、あるいはファックスとか郵送等により受け付けを広げるなども考えられますが、再度ご見解をお伺いいたします。","respondent":"中尾根企画部長","answer":"ただし、別なあれですけれども子育て支援総合モデル事業、いわゆるカリスマ自治体としての事業がありますが、この事業の中でシンポジウムを開く予定になっておりまして、今のところ１２月中旬ごろ開く予定でおりますけれども。","voiceIndex":98,"id":"exchange-046"},{"speaker":"山路委員","kind":"質問","question":"行動計画策定の内容についてお伺いをいたします。そこで、品川区としての地域特性を考慮されながら、各項目について計画案が策定されていると思いますが、それぞれの項目について簡単にお知らせを願います。","respondent":"中尾根企画部長","answer":"現段階では、まだたたき台の段階ですので、余り詳しい内容は確定しないのでご説明はできませんけれども、大まかに言いますと、一つにはやはり母子保健だとか医療体制、食育等も含めました安心できる出産、それからそういう子どもの健康という体系が一つ。","voiceIndex":100,"id":"exchange-047"},{"speaker":"山路委員","kind":"質問・要望","question":"第３回定例会で食育について我が党で取り上げましたが、２の母性ならびに乳児および幼児等の健康の確保および増進については食育も大事な要素と考えております。そこで、今述べました３点について、まだこれからだとは思いますが、行動計画の中にどのように反映していくのか、あらかじめ想像できる範囲でお答えをいただきたいと思います。","respondent":"中尾根企画部長","answer":"どのように反映させるか、最終的な冊子となったときにどういう表現をするのか、このことはまだ固まっておりませんので現段階では何とも申しませんが、内容といたしましては、先ほど言いましたように、一つには順不同になりますけれども、まず食育の関係としましては。","voiceIndex":102,"id":"exchange-048"},{"speaker":"山路委員","kind":"質問・要望","question":"先ほどちょっと触れられましたが、要保護児童への対応、きめ細かな取り組みの推進に関連してお伺いをいたします。今年の１０月、今月に改正児童福祉法が施行されましたけれども、確認の意味で、改正法の内容について簡単にご説明を願います。","respondent":"小沼児童保健事業部長","answer":"１０月から施行されているものと来年の４月以降に施行というようなものが分かれてありますが、基本的な今回のトーンにつきましては、まず相談事業というようなもの、これを虐待防止関係を含めて。","voiceIndex":104,"id":"exchange-049"},{"speaker":"山路委員","kind":"質問・要望","question":"ただいまご説明をいただきましたように、児童虐待を防止するために従来より地域における通報や警察等の調査権が強化されましたが、あらゆる機関のネットワークを通して児童虐待を防止していく必要からも、ただいまの内容が行動計画の策定に反映されて取り組んでいくのかどうか、また地域でのネットワークの児童虐待防止に関しまして、ほかに細かいことがあるんだったら教えていただきたいと思います。","respondent":"小沼児童保健事業部長","answer":"それと、今、私のほうで所管しております家庭あんしんセンター所管ですが、虐待防止会議という、私は議長なんですが、そのメンバーの中に児童相談所の所長が入っているということと。","voiceIndex":106,"id":"exchange-050"},{"speaker":"山路委員","kind":"質問","question":"職業生活と家庭生活との両立の推進に関連してお伺いをいたします。この中では、固定的な男女の役割分担の解消を基本目標に、多様な働き方の実現および男性を含めた働き方の見直しや仕事と子育ての両立の推進が取り上げられております。そこで、品川区において、子育て支援等の視点から、職員の勤務状況等がどのように変化していくのか、お伺いをいたします。","respondent":"本間総務部長","answer":"具体的には、育児休業の取得率の向上や超過勤務の縮減、それから年次休暇の計画的な取得などによりまして、子育て中の職員の勤務状況は変化も生じてまいりますが、いずれにいたしましても、法の趣旨を生かしまして、職場を挙げて子育て中の職員を支援する。","voiceIndex":108,"id":"exchange-051"},{"speaker":"山路委員","kind":"質問","question":"いろいろ細かく中身についてお伺いをいたしましたが、この行動計画策定は、あくまでも地域の実情や特性に応じて、それぞれの施策についてはできる限り数値を示し、総合的かつ具体的に設定していただくことが大事だと言われておりますけれども、この点について、最後にご答弁をお願いいたします。","respondent":"中尾根企画部長","answer":"先ほどから委員がご質問されている、そうした内容につきまして、私どもも基本的には同じ認識に立ってあります。今後についても、今までの成果をより区民のサービス拡充に向けて体制をつくっていきたい、このように考えてありますので、どうぞよろしくお願いしたいと思います。","voiceIndex":110,"id":"exchange-052"},{"speaker":"山路委員","kind":"質問・要望","question":"１３カ所の各地域センターで事業展開されている、地域福祉計画の推進を担っているふれあいサポート活動についてお伺いをいたします。そこでまずお伺いしたいのは、今日まで取り組んでまいりましたが、改めて、総括的にどのような感想をお持ちなのか、まずお伺いをいたします。さまざまなサービス依頼が多くほかに寄せられているのも含めて、お答えをいただきたいと思います。","respondent":"山田区民生活事業部長","answer":"地域の食事サービスにつきましては、平成元年に小学校４校でモデル実施したのを初めとしまして、平成９年に中学校で夕食の配食サービスを開始し、平成元年３０件であった受給者が平成１５年には２８０件と着実に実績を伸ばしています。","voiceIndex":112,"id":"exchange-053"},{"speaker":"山路委員","kind":"質問","question":"２点目に、６５歳以上の高齢者等を対象にボランティアの協力を得て週２回の学校給食等を配食する地域食事サービスについてただいまお話がありましたが、区内全域でサービスのアンバランスはないのか、もしあるとすれば、どのようなご努力をされているのか、３点目に、相談者が例えば急を要する相談をしたい場合、地域センターへ連絡をしたとき。","respondent":"山田区民生活事業部長","answer":"ふれあいサポート活動推進委員会ですが、平成１５年３月に策定いたしました品川区地域福祉計画に基づきます実施状況の把握と達成状況の評価を行うなど、ともに地域福祉に関する全区的な取り組みについて調整と推進を図っております。","voiceIndex":114,"id":"exchange-054"},{"speaker":"山路委員","kind":"質問・要望","question":"細かい説明をありがとうございました。その辺にも速効性に対応できるようなものができてくる可能性は多分にあると思います。高齢者の方から昨日は元気でも今日はぐあいが悪くて動けないので、給食を３日ばかり連続で配達してほしい、ボランティアを探さないと配達してもらえないんでしょうなどの相談も受けております。その辺を今後柔軟に取り組んでいただきたいと思いますが、どのようにお考えでしょうか。","respondent":"山田区民生活事業部長","answer":"今後も議員ご提案のとおり、地域の各団体の集会等、出席させていただいて、積極的にＰＲ活動に努めてまいりたいと考えています。","voiceIndex":116,"id":"exchange-055"},{"speaker":"山路委員","kind":"質問","question":"ふれあい健康塾は、メニューの一つとして昨年度より地域センターでの事業に加わり、自立支援高齢者の健康維持と介護予防を目的とし、大変期待されております。そこで、対象者は何名で、実施回数は何回ぐらい月にやられたのか、また指導員体制、運動方法についてお伺いをいたします。","respondent":"小沼児童保健事業部長","answer":"対象者と、それから実施回数等ですけれども、実施回数につきましては、現在のところ月１回のペースでしています。","voiceIndex":118,"id":"exchange-056"},{"speaker":"山路委員","kind":"質問・要望","question":"来年４月の介護保険の改正に伴い、高齢者が歩いていける健康拠点を考えた場合、地域センターエリア内での運動の場所の確保や指導員体制についても教育委員会との連携でスポレクやトリム連盟などが所属する財団法人品川区スポーツ協会との協力をも視野に入れ取り組んでいくのも一考かと思いますが、どのようにお考えでしょうか。","respondent":"小沼児童保健事業部長","answer":"生まれながらのこの事業というのは介護予防的な機能を持った事業というような性格づけで出発している点、それから。","voiceIndex":120,"id":"exchange-057"},{"speaker":"山路委員","kind":"質問","question":"いきいき計画２１のあらましによりますと、介護予防とふれあい健康塾との連携とありますが、お金がかかる、かからないとかいろいろなこれから問題も出てくると思いますが、その辺は来年の４月以降、どのように検討されていらっしゃるのかどうかお伺いをいたします。","respondent":"新美福祉高齢事業部長","answer":"そういう意味ではふれあい健康塾を含め、さまざまな介護予防サービスを拡充していく、それが今後の高齢社会を活力あるものにしていく重要な取り組みというふうに位置づけて、今後すべてのサービスの拡充を体系的に進めていきたいと考えております。","voiceIndex":122,"id":"exchange-058"},{"speaker":"山路委員","kind":"質問・要望","question":"ふれあい健康塾とともに、今後さらに高齢化が進んでくると、このふれあいサポート活動はますます重要になっていくと考えますけれども、参加と支え合いから生まれる地域福祉を地道に取り組んでいただきたいと思いますが、これらの方向性を今後どのように考えていらっしゃるのか、お伺いをいたします。","respondent":"山田区民生活事業部長","answer":"したがいまして、今後常にこの制度が地域の皆様に理解をいただき、促進を図り、ボランティアの方々が生き生きと活動を続けられる、そのような区民相互が快適に支えられる仕組みになるよう、きめ細かに今後もコーディネートに努めてまいりたいというふうに考えてあります。","voiceIndex":124,"id":"exchange-059"},{"speaker":"山路委員","kind":"確認","question":"ヒートアイランド対策についてお伺いをいたします。このような現状から、ヒートアイランド対策について、平成１５年３月に規制改革推進３カ年計画を閣議決定し、平成１５年度中にヒートアイランド対策にかかわる大綱を策定することが決定されました。そして、平成１６年３月３０日にヒートアイランド対策大綱が決定され、本格的に対策の実行に向けた取り組みが始まりました。","respondent":"岩崎環境清掃事業部長","answer":"基本方針としまして、総合的、効果的な対策の実施、それから、実行可能なものから進めて長期的な対策を強化していくこと、それから、国と地方、住民との連携が大事であるということと、関連政策分野との連携が重要であるというようなことを定めておりまして。","voiceIndex":126,"id":"exchange-060"},{"speaker":"山路委員","kind":"質問","question":"官民一体による温暖化対策についてお伺いをいたします。そのことによって、例えば冷房温度の設定を１℃上げるだけでも相当な効果があると思います。温暖化対策について、区内の企業や家庭にも意識を持っていただき、エアコンの排熱、省エネ等の働きかけについて、どのように取り組んでいかれるのか、あわせてお考えをお聞かせください。","respondent":"岩崎環境清掃事業部長","answer":"この中で、特に東京電力品川支社、東京ガス南部支社、東京商工会議所品川支部と連携したわけですが、特に東京商工会議所の場合は２００社が参加でありますので、そこのほうにファクシミリを送ったというふうな２次的な広げ方もしています。","voiceIndex":128,"id":"exchange-061"},{"speaker":"山路委員","kind":"質問","question":"続いて緑化対策の拡充と歩道の保水性舗装の推進についてお伺いをいたします。最初に緑化対策の拡充について、お尋ねいたします。そこで、区有施設の屋上緑化の推進の取り組みと、助成制度の拡充についてご見解をお伺いいたします。壁面緑化については学校や区有施設等が考えられますが、今後どのように取り組んでいかれるのか、あわせてお伺いをいたします。","respondent":"中谷まちづくり事業部長","answer":"壁面緑化につきましては、古くはこちらの防災センターの前の道路の擁壁について壁面の緑化を行ったところですが、今お話のように平成１４年度からこの目黒川の護岸緑化を行い、今年度も１,２００ｍ弱について緑化を行うという予定ですし。","voiceIndex":130,"id":"exchange-062"},{"speaker":"山路委員","kind":"確認","question":"次に歩道の保水性舗装の推進についてお尋ねいたします。東京都の実験によれば保水性舗装の道路では、１０℃程度の温度を下げる効果が確認されております。一昨年千代田区では全国初の歩道の保水性舗装を行っており、品川区としても先日のまちづくり展で展示されておりましたが、今後は積極的に推進すべきと思います。歩道の保水性舗装について、どのように取り入れていかれるのか、お伺いをいたします。","respondent":"中谷まちづくり事業部長","answer":"この中で、大崎の地域全体で環境配慮のまちづくりというものを進めていこうということで、今取り組みをやっておりますので、この一環として具体に検討しています。","voiceIndex":132,"id":"exchange-063"},{"speaker":"山路委員","kind":"質問","question":"近隣区周辺にある大規模緑地とのグラウンドデザインについて、お伺いいたします。そこで、東京都が作成した熱環境マップで赤く染められている港、目黒、渋谷、千代田区など隣接する自治体と共同でヒートアイランド対策を考えていくことが必要と思われますが、この辺のご見解をお聞かせください。","respondent":"中谷まちづくり事業部長","answer":"都においても広域的な観点からこのヒートアイランド対策を実施するために、さまざまな取り組みを行っているですが、区としましても大崎駅周辺のこの取り組みをまずモデルとして区全体に普遍的に広げていきまして、そして都とも連携しながら。","voiceIndex":134,"id":"exchange-064"},{"speaker":"山路委員","kind":"質問・要望","question":"この点を強く意識していただき、今後の対策に取り組まれることを要望してこの質問は終わらせていただきます。最後に、地域再生と都市再生を有効活用した品川区のまちづくり構想についてお伺いをいたします。品川区では教育の分野で小中一貫教育特区を認定されたと伺っておりますが、これにはどういうメリットがあるのか、お伺いをいたします。","respondent":"古川教育次長","answer":"具体的には市民科を新たに設ける、あるいは小学１年生から英語学習を取り入れる、こういった教育活動をいわゆる小中９年間を通して継続的に行う、これが最大のメリットです。","voiceIndex":136,"id":"exchange-065"},{"speaker":"山路委員","kind":"質問","question":"小中一貫教育特区のメリットについてはわかりました。このほかの事業で特区を申請したものがあるかどうか、あるとしたら、どういう事業の申請をされたのか、また、その結果はどうだったのか、お伺いをいたします。","respondent":"中尾根企画部長","answer":"内容といたしましては、幼稚園の権限を区長のほうにと、それから入所要件等の緩和であるとか、民間の委託を可能にする、こういう内容でございまして、これについては、現在特区としては採用されておりませんで、政府としましては、骨太の方針２００３で。","voiceIndex":138,"id":"exchange-066"},{"speaker":"山路委員","kind":"質問・要望","question":"わかりやすく説明していただきました。今後の事業展開で、特区申請を考えているものがあるかどうか、ございましたら、そのある内容についてお聞かせをしていただきたいと思います。","respondent":"中尾根企画部長","answer":"そのほかの特区の申請ですけれども、現在例えば水辺を生かしたまちづくり等についての特区申請という検討はしていますけれども、まだまだ検討すべき内容がたくさんございまして、いまだに申請するまでの時期に至っているものはございません。","voiceIndex":140,"id":"exchange-067"},{"speaker":"山路委員","kind":"質問","question":"地域再生と都市再生についてお伺いをいたします。本年７月３０日、国土交通省では重点施策をまとめ、その中に地域再生、都市再生を盛り込み、地域の自立を支援する基盤づくりとしてまち再生丸ごと支援の方針を打ち出しています。これはどういう内容でどれほどの財政支援があるのかお伺いをいたします。","respondent":"中尾根企画部長","answer":"そこで、政府といたしましては、地域再生本部の中で、これまでのように法による規制のほかに、経済的な支援というものにかかわるものが非常に多くあるということで、これらについては、来年度の予算に向けて各省庁でこういう意見をまとめて、そして要望してくれと。","voiceIndex":142,"id":"exchange-068"},{"speaker":"山路委員","kind":"提案","question":"私は、このただいま説明をいただきました地域再生、都市再生の制度は、品川のまちづくり構想にぴったりの制度だと考えております。そこで、国の制度である地域再生、都市再生の認定申請を有効活用し、元気のあるまちづくり構想を推進することを提案するものでありますが、どのようにお考えでありましょうか、お伺いをいたします。","respondent":"中尾根企画部長","answer":"これまで品川区はまちづくりにおきましては、補助金等の有効活用をしてきたところですけれども、今後につきましても、まちづくりにおきまして、こういった制度が有効に活用できるかどうか十分検討していきたいと思います。","voiceIndex":144,"id":"exchange-069"},{"speaker":"山路委員","kind":"質問・要望","question":"高橋区長は区政概要の中で、新幹線品川駅開発に伴い、再び品川区は交通産業の拠点としてポテンシャルを上げていると言われております。どうかこの制度を利用されて、すばらしい元気のある品川のまちづくりを要望いたしまして、私の総括質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":146,"id":"exchange-070"},{"speaker":"木下委員","kind":"質問・要望","question":"一般区民の方々は、区政に対してご要望をお聞きしても、なかなかお出しになってこられません。２点目は、震災対策、密集住宅市街地対策について。平成１６年６月に行われました内閣府の国民生活に対する世論調査によりますと、政府に対する要望で、医療、年金等の社会保険構造改革を挙げた方々の割合が６７.７％と最も高く、以下、景気対策が５８.６％と続いております。その方々の人数は何名でしょうか。","respondent":"新美福祉高齢事業部長","answer":"特に後期高齢者、痴呆性高齢者の増加にどう対応していくかが大きな課題というふうに考え、今後は居住性を重視いたしました個室型の介護施設を整備していく計画です。","voiceIndex":148,"id":"exchange-071"},{"speaker":"木下委員","kind":"提案","question":"そうしますと半年で９５名ですので、本当にお困りの方々の手当てはできていると理解してよろしいわけでしょうか。これからの将来、人口動態的に言って、戦後の団塊世代の方々が介護世代になる２０２５年を控え、さらなる対策とサービスの充実が求められておると思います。家族だから一番心配するわけでありますし、事務的にならず親身になってくれるのではないでしょうか。よろしくお願いします。","respondent":"新美福祉高齢事業部長","answer":"したがって、介護保険制度も導入というような経緯があったわけでございまして、私どもも心身の介護負担の軽減のために適切に外部サービスをご利用いただきながら、家族の方との生活が継続できるようにご支援をしていく。","voiceIndex":150,"id":"exchange-072"},{"speaker":"木下委員","kind":"質問・要望","question":"震災対策密集住宅市街地対策について質問をします。１．都内ワースト１０の中に入っていた旗の台四丁目、中延五丁目は事業計画には出ておりませんけれども、事業として考えておられるのでしょうか、考えておられるものでしたら、何年度に事業開始予定でおられるのか。２．決算特別委員会の資料に新しく豊町四・五・六丁目が計画事業として載っておりましたが、事業開始予定は何年度からでしょうか。","respondent":"中谷まちづくり事業部長","answer":"３点目の都市再生機構との協定の内容ですが、これは今お話のとおり、旧都市基盤整備公団でございまして、今般独立行政法人になったわけですが、ここに対する協定書は、平成１５年６月６日付で協定しておりますが、これは二葉三・四丁目地区の防災性および居住環境の向上。","voiceIndex":152,"id":"exchange-073"},{"speaker":"木下委員","kind":"質問","question":"そういう現場の方々ですとか、地域住民の方々の願いにお答えするためにもお聞きした次第です。すぐやれることはすぐやるべきだと考えています。これは防災対策としても効果がありますし、配布が難しいのなら消火器をあっ旋したりもしているわけですから、そういう被害を最小限にするためにも装備を促進するために、ＰＲや告知を兼ねてあっ旋したらいいかと思いますけれども、いかがでしょうか。","respondent":"山田区民生活事業部長","answer":"しかしながら、用具の効用性については高く認識をしておりますので、区ではこれまでも防災用具でありますガラス飛散防止フィルムや家具転倒防止器具につきましては、区役所２階の売店で１５％の割引という形であっ旋を図っているところです。","voiceIndex":154,"id":"exchange-074"},{"speaker":"木下委員","kind":"質問","question":"個人住民税の使途指定制度について質問します。投票しない、または投票に行かない方々になぜ投票に行かないのですかと尋ねますと、大体の方は投票に行っても何も変わらないよとお答えになられます。サイレントマジョリティーである大多数の投票に行かない方々の声なき声を区政に反映させるべき行動を起こすときではないでしょうか。３番、制度としての問題点が行政側としてあるかどうか。","respondent":"市岡企画財政課長","answer":"主なところでは、埼玉県の志木市、あるいは千葉県の市川市が委員ご指摘のとおり来年度から導入を目指して準備を進めているというふうに報道されてあります。それから、長野県、足立区が検討しているということが報じられているところでもあります。","voiceIndex":156,"id":"exchange-075"},{"speaker":"木下委員","kind":"質問・要望","question":"地方分権とセットで約束した清掃労働組合との約束は各区ごとにいろいろな状況があり、確かに難しい点はあることもわかりますが、ですが、組合の方々のおっしゃるには、大きくは区長会が約束をほごにした責任があるとのことですけれども、いかがでしょうか。年末年始を迎え、そのあたりが心配でなりません、これから先、最悪の状況が生じないように、どのように対応されていくのか、お聞きいたします。","respondent":"高橋区長","answer":"それを近日中に組合に提示をし、交渉を重ねていくことになると思います。少なくとも１０月いっぱいに交渉を求め、１２月第４定例会に改正の条例を出し、４月１日から実施をできるような方向に持っていきたいというような区長会の今の考え方です。","voiceIndex":158,"id":"exchange-076"},{"speaker":"木下委員","kind":"質問","question":"新聞報道によりますと、１０月１１日、都内がごみであふれるというものが載っておりましたので心配した次第です。次に、東京法務局品川出張所移転計画について質問します。品川区役所の１階部分には東京法務局品川出張所があり、本庁舎の１階のほとんどを占めております。現在、品川区役所は昭和４３年に竣工されたわけですが、そもそも国、都、品川区の関係はどのようなものだったのでしょうか。","respondent":"本間総務部長","answer":"ただ、財務省との関係で、調査もの等が法務局に来ているそうでございまして、その調査ものの中で平成１８年度頃、この区分所有している建物が処理できたら、ということを事務的に回答しているというだけでございまして、これは去年もこのような回答をしているそうでございまして。","voiceIndex":160,"id":"exchange-077"},{"speaker":"飯沼委員","kind":"質問・要望","question":"日本共産党を代表いたしまして総括質問を行います。どうぞよろしくお願いいたします。私からは、次世代育成支援地域行動計画について、お伺いをいたします。初めのうちは重複をいたしますが、準備をしていましたので、どうぞよろしくお願いいたします。改めて、次世代育成支援対策推進法の制定に当たり、経過と目的、また地域行動計画の概要をお知らせいただきたいと思います。","respondent":"中尾根企画部長","answer":"品川区といたしましては、これまで第三次長期基本計画等に示されまして、そして、これまで取り組んできた背景をもう一度再整理をして、それから将来に向けての整理をしていく、このような考え方で取り組むところです。","voiceIndex":164,"id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"地域行動計画策定に当たってのプロセスとスケジュールについて、簡単に教えていただきたいと思います。特にニーズ調査、そして定量的目標の設定について、あと、地域協議会の開催について教えていただきたいと思います。","respondent":"中尾根企画部長","answer":"行動計画の取り組みそのものにつきましては、第三者によります協議会を設立しまして、その中で今後どういうふうにしていくべきかという原案をつくりまして、それをもとにしまして、区民への意見等も広く聞いた上で。","voiceIndex":166,"id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問・要望","question":"改めてニーズ調査が大変重要であると思うんですが、東京２３区中２１区までがニーズ調査を行い、詳細な報告書をつくっています。品川区は行わずに、このまま行動計画の策定を進めているわけなんですけれども、この点に関してもう一度基本的な考えをお聞かせいただきたいと思います。そして、この調査なくしてどのようにこの計画の目標値の設定を行われるのかどうか、その辺についてもお伺いしたいと思います。","respondent":"中尾根企画部長","answer":"これの長期基本計画そのものについて、これまでさまざまな区民の方のご意見を伺い、それから、議会でのご意見を伺ってきた民主的な方法でつくってきた基本計画で、それの延長線上にあるということですから、改めてすべてのことについて。","voiceIndex":168,"id":"exchange-080"},{"speaker":"飯沼委員","kind":"意見","question":"今までの流れのままで、この少子化を克服できるのかどうか、その辺も含めてですけれども、実際にこの間、先ほど言われました計画、調査が行われているというご答弁をいただいたんですけれども、具体的に中高生の子どもたちの意見なんかがどこでどう受けとめられているのか、一つだけ具体的にお聞かせください。","respondent":"中尾根企画部長","answer":"したがいまして、先ほど言いましたように、データ、結果について、まだまだこういうところが不足だ、こういうところをもっと補充すべきだ、こういう意見のことについては真摯に受けとめて、そういったところの補充は十分していきたい、このように考えてあります。","voiceIndex":170,"id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今のご答弁からは、この少子化を何とか克服しよう、こういった意気込みを感じられません。この間、区民の実態を知る上での資料、私は何回も求めたんですけれども、資料は何一つ出てきていません。区のやり方は行政主導であって、区民参加を形だけにしていないでしょうか。今後の進め方として、公聴会、そして懇談会、説明会を行い、広く区民の意見を求める姿勢へと改善を求めます。これが１点です。","respondent":"伊藤保健センター所長、小沼児童保健事業部長","answer":"乳幼児期の育ちについてということでご質問ですけれども、私どもは、乳児健診とかそれから１歳半健診、３歳児健診等で子どもの成長、発達のいろいろなデータを得ておりますし、それから。それから児童センターを利用しての問題ですが、日々来所されるお母さん方との話、あるいは中高生の問題からの意見のやりとり、それから、幼児クラブ等を通しても抱える問題点を、話し方あるいは話の様子というようなことで。","voiceIndex":172,"id":"exchange-082"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子どもたちの育ちの問題点を伺ったんですけれども、特に問題はないというご答弁と受けとめてよろしいのでしょうか。もう１点、先ほど公聴会、説明会開催について求めたんで、この広く区民の意見を求める姿勢と改善を求めますという１点について、後でお答えをいただきたいと思います。子どもの睡眠不足と発達障害についてのご見解を伺います。研究はこの点されているのか教えてください。","respondent":"伊藤保健センター所長、中尾根企画部長","answer":"それで、そのほか、寝ている間に免疫力が活発になるというふうなこともあったりいたしますし、睡眠不足が長期間続きますと血圧が上がるとか、いろいろ身体的な側面は出てまいりますけれども、睡眠の不足ということと。公聴会等を開く考えはないかということですけれども、今回の行動計画の広く意見を聞く方法としましては、１１月から１２月にかけまして、パブリックコメントを行うということにしています。作成協議会もこのことで了としています。","voiceIndex":175,"id":"exchange-083"},{"speaker":"飯沼委員","kind":"質問・要望","question":"睡眠の保障は重要な課題であり、実態をつかみ、対策行動は本当に大事なことだと思います。ぜひ盛り込んでいただきたいと思います。特に気になっていることなんですけれども、幼稚園で行われている預かり保育ですが、幼稚園でも長時間保育になれば、保育園と同様に昼寝の機能が求められるのではないでしょうか。二葉の幼稚園とかぷりすくーる西五反田でも昼寝が必要と考えますが、この点はいかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"事は施設運営にかかわる問題ですから、ベテランのあるいはそれぞれのキャリアのある園長が状況に応じて判断して、弾力的に対応している、こういうことでご理解いただければと思います。","voiceIndex":178,"id":"exchange-084"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先に行きます。在宅、子育てのお母さんたちのニーズをどのように把握をされているのでしょうか。ＮＰＯを含め地域の子育てネットワークづくりへの支援を求めます。そして、今後需要にこたえていく意味では、オアシスルームなど、児童センターの中に拠点とする子育て館を位置づけて、スペースも人員配置も確保して行うべきと思いますが、いかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"幼児クラブの関係、おもちゃ云々というようなことがあったかと思いますが、これにつきましては、現在私どものほうではライフステージ、それぞれ児童センターを利用する方々は月齢層が０歳から極端なことを申し上げますと１８歳まですから。","voiceIndex":180,"id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"人も予算もぜひつけて充実をしていただきたいと思います。保育園について２点改善を求めます。１点目は子どもの生活、発達にとってどうなのか、検証が全くされないまま進んでいる、こういった実態です。財政効率を追求した結果が子どもたちの成長発達にどのように影響しているのか、私はぜひ現場の検証をしていただきたいと思いますが、いかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"むしろ、園から上がっていないという状況ですし、それから、配置基準について何回も申し上げますけれども、これは国基準をベースにして加算配置している状況の中での実施ですので。","voiceIndex":182,"id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問・要望","question":"２点目、保護者の要求をつかんでいない、この点です。品川区の待機児解消は、認証保育所、そして幼保一体化施設ぷりすくーる西五反田の形式を求めていくようですが、保護者からは認証保育所は保育料が高くて預け切れない、ぷりすくーる西五反田も預かり保育などを加えると保育園よりも保育料金が高くなり、私立幼稚園並みという声が届いています。中止を求めますが、いかがでしょうか。","respondent":"小沼児童保健事業部長","answer":"ですから、１０月から始まった保育料について、私のほうは特に値上げ中止というようなご意見等は今のところございませんし、当初の方針どおり、撤回する考えはございません。","voiceIndex":184,"id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問・要望","question":"品川区は子育てにかかる保護者の費用負担、子育てにかかわる費用負担がどのくらいかかっているのか調査をされたことがあるのでしょうか。子育て支援、経済的援助、これがなくてはならないのが、今の特に子育ての若い世代への応援ではないでしょうか。そして、最後になりますけれども、男女共同参画の取り組みについても伺います。特に男性の育児休業取得への取り組みについて、お伺いをしたいと思います。","respondent":"本間総務部長","answer":"男女の役割分担意識についてのご質問ですが、この点の調査につきましては、男は仕事、女は家庭という考え方についてどのように思うかという設問を設けまして、過去４回にわたり調査を実施しています。","voiceIndex":186,"id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"男女平等の教育というのは、なかなか進むのに時間がかかるように思っています。そのためにも住民の要求、意見を聞く姿勢を、そして子どもの視点で最善の環境を求める姿勢をつくっていっていただきたいと思います。特に今回の計画、厚生労働省指針に示されていますけれども、公聴会、説明会、懇談会など開催をして、住民参加、情報公開で進めていただけるように改善を求めて、今回の質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":188,"id":"exchange-089"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は小中一貫教育の問題について質問をさせていただきたいと思います。どうぞよろしくお願いいたします。初めに、第二日野の１校目の小中一貫校から大井地区に展開し、そして今年は全小中学校で小中一貫教育を開催をすると一気に進みました。この小中一貫教育をこんなに早くなぜ導入したのか、その目的、問題点はないのか、どんな手順を踏んで決定に至ったのかを説明していただきたいと思います。","respondent":"若月教育長","answer":"そうした諸々の問題を少しでも解決しよう、そういう意味で、子どもたちのための学校をつくろうということで、新たな発想から小中一貫教育といったようなものを実現していこう、こういうような考え方がもとになっているところです。","voiceIndex":190,"id":"exchange-090"},{"speaker":"沢田委員","kind":"質問・要望","question":"どんな手順でこれが導入に至ったのかというのを後ほど答弁をいただきたいというふうに思います。２００２年の３月４日の文教委員会で、教育長はこう言いました。小中一貫校で学んだ実践教訓をその他の学校に広げるんだ、こういうことを繰り返し文教委員会や予算特別委員会や決算特別委員会で説明なさったんですけれども、それがいきなり全区展開になったのは何なのかということを再度お尋ねしたいと思います。","respondent":"若月教育長","answer":"それで、その次に、それを受けまして、すぐに小中一貫校の準備委員会やプラン２１推進委員会等々において、その内容といったようなもの、また進めていく上でのさまざまな課題といったようなものを検討していっていただいた、こういう経緯があります。","voiceIndex":192,"id":"exchange-091"},{"speaker":"沢田委員","kind":"提案","question":"一貫校はという、これはつけ足しですけれども、「今のところ完成型を測定する現状がないわけですから、本来は前例を見きわめた上で、実践を確認した上で展開すべきではないかと思うのです。こういうことをやるなら、一生に一度しかない教育なんですから、一歩一歩確かめながら前に進んでいくのが本来教育のあるべき姿だと、このことを強調して先に進みたいと思います。","respondent":"若月教育長","answer":"そうした具体的なデータのもとから、それを連携からさらにその実を上げるための一貫教育への拡大をしていったわけで、これは変更でも何でもないわけでありまして、計画の発展だと、こういうふうに私どもは考えているところです。","voiceIndex":194,"id":"exchange-092"},{"speaker":"沢田委員","kind":"質問・要望","question":"何字増えるのかというのを具体的に述べてほしいと思います。新学習指導要領では、小学校で２２４時間国語の時間を減らしました。ところが、指導要領でも配当漢字１,６００字はそのままですから、子どもが勉強するのに大変になるわけですね。その上に今度はさらに学年を早めて勉強しよう。どんな変化があったんでしょうか。","respondent":"若月教育長","answer":"１・２年生では年間１０時間であります。算数では３・４年生ではやはり５０時間程度、２年と５年では５時間程度、７年生から９年生では１３時間程度の増ということを計画をしています。","voiceIndex":196,"id":"exchange-093"},{"speaker":"沢田委員","kind":"質問","question":"私のほうから漢字の問題がどれだけ増えるのか、早まるのかというのを述べたいと思います。小学校６年で書く問題、字を書けるようになるのが８２５字だったものを４年までに８２５字を覚える、中学１年で１,００６字だったものを２年早める、小学校１年で書く字は０だったものが新たに８０字加わる、こうした問題について、現場から意見は出ていないでしょうか。","respondent":"若月教育長","answer":"この漢字を学習する場合、ぜひ心にとめておいていただきたいことは、例えば２年生でこの漢字をやりますよ、前は３年生だったんだけれども２年生でやりますよ、そういう漢字はあるかもしれません。そこで何が何でも覚えろということじゃない。","voiceIndex":198,"id":"exchange-094"},{"speaker":"沢田委員","kind":"質問","question":"聞きますけれども、漢字の習得率、これはどんな状況になっているでしょうか。それから、私が聞いた国語の先生のすべてが無理です、できません、ますます漢字嫌いの子が多くなりますというふうにおっしゃっておりました。カリキュラム検討委員会でこの問題を検討した際に意見はなかったのか、全会一致だったのか、お答え願いたいと思います。","respondent":"若月教育長","answer":"習得率のデータは今こちらには持ち合わせておりませんので、お答えができませんけれども、しかし、今委員はお聞きになった先生方は全部無理だと、こういうふうにおっしゃったと。じゃあ、今やっている漢字は完璧なんでしょうか。","voiceIndex":200,"id":"exchange-095"},{"speaker":"沢田委員","kind":"質問","question":"私は、この問題を習得率がどれぐらいあるのかということを事前に質問しますということを言ったけれども、出てこない。半分わからない。改めてこういう結果はどうなのかということと、じゃあ、私は漢字をやるということを言っていましたから、小学校１年生の漢字を教える、今は読みですけれども、今度は書きも入ってくる。具体的にどういう状況なんでしょうか。","respondent":"若月教育長","answer":"これはいろいろな考え方があると思います。例えば、今の子どもたちは、小学校でもそうです。ワープロでもパソコンでもとにかくああいったようなものを大変使います。私たち大人もそうです。使わなかったんならば漢字というものは忘れてしまいます。興味もなくなっていくんです。","voiceIndex":202,"id":"exchange-096"},{"speaker":"沢田委員","kind":"確認","question":"小学校１年生で習うのは、まず平仮名。それから、平仮名に濁点、長音、それからそれを覚えるだけではなくて、鉛筆の持ち方、線や形を書くこと、音と文字との確認、大変なことを小学校１年生の間で覚えなくちゃならないのに、平仮名はできているけれども、教育現場では片仮名を勉強する時間を生み出すのが難しいというのが実態だと言っていました。","respondent":"若月教育長","answer":"それよりも心配したのは、今の日本の子どもたちにとって大事なこと、心配なことは学習意欲のほうの低下、これのほうがむしろ大きな問題だな、こういう認識を持ちました。","voiceIndex":204,"id":"exchange-097"},{"speaker":"沢田委員","kind":"質問","question":"ですから、現場の教員の意見を得てやったというふうには私は思えません。それから、ＯＥＣＤのテストですけれども、２０００年ですから習熟度学習をやる前、要するに、混合教育、能力別教育をやらない段階でのテストだったんです。だから、日本は８位になった。そしてＯＥＣＤの調査でトップになったのは、最低ランクのトップ。フィンランドはどういう教育をやっているかというと、大体１学校６０人ぐらい。","respondent":"若月教育長","answer":"私はそのデータを持っておりません。必ずしもそうとは言い切れない部分だってあるだろうと思います。したがいまして、このフィンランドの教育のやり方についてどう思うかと言われても、それはたまたまそうだったんであって、今度やれば日本は絶対負けないぞ、私はそう思いました。","voiceIndex":206,"id":"exchange-098"},{"speaker":"沢田委員","kind":"質問","question":"例の混合教育、フィンランドの問題ですけれども、３２カ国が加わって２６万人の一斉テストを世界中でやった結果、１位がフィンランド、２位がカナダ、３位がニュージーランド、日本は８位です。１位から８位まで能力別教育をやった国はありますか。ないんですよ。このことに対する見解をさらに伺いたいと思います。","respondent":"若月教育長","answer":"１位から８位までは能力別学習をやっている国はないんだというようなことをお話になりました。私はそこら辺はそれぞれの一つ一つの国をつぶさに調べたわけではありません。","voiceIndex":208,"id":"exchange-099"},{"speaker":"沢田委員","kind":"質問・要望","question":"漢字だって覚えられない。それで、上位の子は先にどんどん進めていくわけですから。そうしたことを考えたときに、私はもう４７都道府県のうち、来年では東京都と香川県しか４０人学級という巨大学級をやっているところがなくなるというこの現実を踏まえて、本当に子どもたちに学びの喜びを享受させるためにも少人数学級を導入すべきだと思いますが、教育長、いかがでしょうか。","respondent":"若月教育長","answer":"そうすると、これはどんなあれかわからないけれども、例えば私のようにできの悪い子は、分数を幾ら説明されたってわからない。概念がつかめないんですよ。そういう子どもは何人もいるんです。若月君もわからない、古川君なんかもっとわからない。そういう子どもがいる。","voiceIndex":210,"id":"exchange-100"},{"speaker":"沢田委員","kind":"質問","question":"教育長の熱心なあれはわかりますけれども、私は事前にＯＥＣＤの調査について質問をするから、しっかり調べておいてほしいということを通告していたんです。それがまともにない。それから、今年の春には習熟度別学習のアメリカでの教授の先生だとかいろいろ紹介もしました。世界の流れはどうだったかということについてもまるで答弁の中にはない、残念だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":212,"id":"exchange-101"},{"speaker":"西本委員","kind":"確認","question":"無所属の会より代表しまして、総括質疑を行います。私は２点ほど大きく質問いたします。一つは、幾つかの会派からもありましたけれども、私は視点を変えて、次世代育成支援対策に関してご質問いたします。それで、お伺いいたします。確認いたしますが、全国的に先駆けて子育て支援対策を実施しておりますけれども、区民のニーズをどのように取り入れ実施に至ったのか、その経緯をお答えください。","respondent":"小沼児童保健事業部長","answer":"全国に先駆けてのニーズ把握の件ですけれども、私どもとしましては、保育園の利用者、あるいは現場での保護者の反応、それから区民の声、もちろんですけれども、議会でのやりとり、あるいはこういう場を通じてのご意見の拝聴、それから世論調査等。","voiceIndex":214,"id":"exchange-102"},{"speaker":"西本委員","kind":"質問","question":"その中で補うところは多少あるかと思いますが、それを今後どういうふうにしていくのかという視点が今後必要になってくるという形であると私も認識しております。品川区がすべき次世代育成支援の方針と、今までの保育サービスなどの事業に対する検証について、今後品川区における行動計画をするに当たってどのように検証を入れていくのか、その考えをお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"２点目のご質問ですけれども、まず品川区での検証の関係等の問題ですが、確かに政策がある程度成熟というんでしょうか、潤ってまいりますと、本来想定した目的以外の目的で残念ながら使われてしまうという傾向があること、これは否めないと思います。","voiceIndex":216,"id":"exchange-103"},{"speaker":"西本委員","kind":"質問・要望","question":"しかしながら、そこは拡大すれば、その反面安易に使ってしまうという、親側も早く子どものために帰りたい、しかしながら仕事もある、そういうせめぎ合いの中で仕事をしているわけですから、そういう気持ちもわかるのではありますが、やはり子どもたちのことを考えたときに、自分自身が親として早く帰るという努力を忘れるような政策になってはいけないというふうに思っております。","respondent":"小沼児童保健事業部長","answer":"だからこそ、これからは子育てそのものに家庭であるとか、それを包んでの子育てであるとか、そういうところに行政運営のシフトあるいは視点を移していくべきというふうに私のほうは今考えているところです。","voiceIndex":218,"id":"exchange-104"},{"speaker":"西本委員","kind":"質問","question":"全員の参加でも、まだありません。活動も年に１回から数回と非常に少なく、活動自体も制約されているというのが実態です。自主的な活動にはまだまだ至っておらないというのが現状です。今後発展させるために、具体的な改善を検討する必要があると思いますけれども、保育園と保護者とのかかわりについて検討する検討委員会のようなものを設置はできないか、そのお考えをお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"折り返し点あるいは判定する時期に差しかかってありますし、さまざまな問題なりあるいは解決すべき課題というようなことも出てきているような場面もありますので、検討委員会という名前はともかくとして、何らかの形でのよりよきものを育てていくような。","voiceIndex":220,"id":"exchange-105"},{"speaker":"西本委員","kind":"質問・要望","question":"ぜひ今後、保育園ＰＴＡを発展させるという意味でも具体的に行動をしていただきたいというふうに思っております。このような新たな動きを取り入れて、保育園の環境が改善してほしいと願っております。教育現場でもＰＴＡは円滑に教育を行う上で重要なポジションにあるわけですけれども、本来の正常な関係の再構築をどのように考えているのか、区としてのお考えをお聞きしたいと思います。","respondent":"小沼児童保健事業部長","answer":"基本的なところでは、運動論を主体としての子育てということに連綿としているわけではないというようなことも私なりにわかりましたし、ということであれば、次世代育成もさることながら、品川区における新しい子育て。","voiceIndex":222,"id":"exchange-106"},{"speaker":"西本委員","kind":"意見","question":"保護者たちは争いを望みません。コミュニケーションを本当に必要としております。現在、自己中心的な考え方が蔓延している現在において、自ら率先して子育ての輪を広げようと考えている保護者の方たちは非常に貴重な存在であると私には思います。保育園事業を円滑にできるパートナーとして、ともに考えていきたいという区民の気持ちをどのように受けとめていくのか、ご答弁をお願いいたします。","respondent":"小沼児童保健事業部長","answer":"先ほどちょっと申し上げましたけれども、健全育成事業あるいは保育園事業にかかわる大部分の区民の方々の気持ちというものは、この間いろいろな紆余曲折、経過を経ましたけれども、現在はそれなりに私のほうとしてはつかんだところですので。","voiceIndex":224,"id":"exchange-107"},{"speaker":"西本委員","kind":"質問","question":"非常に心温まるご答弁ありがとうございました。ぜひよろしくお願いいたします。次に、オアシスルームや児童センターの幼児、乳児クラブなど、在宅の子育てをされている保護者への支援について政策がいろいろ行われています。待ちの政策ではなくて、率先してかかわっていくという政策が必要と私は考えております。児童保健事業部としてどのような政策を行っていくのか、お聞きをいたします。","respondent":"小沼児童保健事業部長、伊藤品川区保健センター所長","answer":"今３点にわたる質問がございましたけれども、まず児童センターを活用してのお話ですけれども、確かに待ちのあるいはウェーティングというようなところでしょうか。これらの事業は年々参加者が増加しているという傾向があります。今後どのような事業を展開していくのかということにつきましては、食育等、新たな事業展開の中で考えていきたいと考えています。","voiceIndex":226,"id":"exchange-108"},{"speaker":"西本委員","kind":"質問","question":"その不安の中で子育てをして、今は情報社会ですから、いろいろな本などがありまして、いろいろな情報があればあるほどどれを信じていいのか、どれを選んでいいのかわからない、そういう状況でもあります。一つ、お聞きしますが、品川区における障害のある児童の就学児に対する相談体制をどうとらえているのでしょうか、その現状をご質問いたします。","respondent":"古川教育次長","answer":"基本的には障害のあるすべての児童・生徒に教育を保障するということを基本理念といたしまして、現在、医師あるいは福祉施設の長、ろう学校や養護学校の教員、さらに心身障害学級の校長、教員等で構成いたします就学指導委員会を設置しながら適切な就学先の検討を行ってあります。","voiceIndex":229,"id":"exchange-109"},{"speaker":"西本委員","kind":"質問","question":"一人ひとりの状況に合わせて就学の相談に応じ、適切なアドバイスをしている。特別支援教育というのは教育関係だけではなくて、医療、福祉、教育界など広い分野での連携を図りながら進めていくべきだという考え方も款別審査の中でお聞きいたしました。子どもたち一人ひとりに最適な教育をするためのこの委員会の位置づけについて、今後どのように考えておられるのか、ご質問したいと思います。","respondent":"古川教育次長","answer":"いずれにいたしましても、現在特別支援教育の検討委員会を設置し、検討を進めてあります。この中で具体的な検討を進めていきたい、このように考えてあります。","voiceIndex":231,"id":"exchange-110"},{"speaker":"西本委員","kind":"質問・要望","question":"現在、幼稚部に乳幼児教育相談も含めて２６名、小学部に１７名、中学部に７名通学されております。乳児の健診で聴覚障害がある場合、当然専門教育機関として品川ろう学校を紹介すると思いますけれども、学校に就学するときの相談に対して、区は教育委員会を通してどのようなアドバイスを行っているでしょうか、まずそれをお聞きしたいと思います。","respondent":"古川教育次長","answer":"幾つかの対応があろうかと思ってありますけれども、先ほども申し上げましたように、私どもは保護者と一緒になりながら、そのお一人お一人に一番ふさわしい就学の形態、こういうものをとらえながら、今相談を受けている、こういう状況です。","voiceIndex":233,"id":"exchange-111"},{"speaker":"西本委員","kind":"質問","question":"いろいろなアドバイスをしていただいている現状だというふうにお聞きしました。聴覚障害の専門教育機関、これが都立品川ろう学校という位置づけにあろうかと思いますが、この品川ろう学校と近隣と小中学校とのかかわりがどうなっているのか、その辺をお聞きしたいと思います。","respondent":"古川教育次長","answer":"今後ともこの交流につきましては進めていきたい、このように考えてあります。","voiceIndex":235,"id":"exchange-112"},{"speaker":"西本委員","kind":"質問・要望","question":"往復で４時間の通学時間になる、これは乳幼児、それから小学生の通学としては許容範囲を越えてしまうというふうに考えております。品川区としても品川ろう学校の機能が増えることは好ましいと思いますけれども、聴覚障害の子どもたちの専門教育機関として品川ろう学校機能を残してもらえるよう、品川区教育委員会として働きかけていただきたいと考えますが、どのようにお考えになりますでしょうか。","respondent":"古川教育次長","answer":"この間、さまざまなこの計画に対しまして、保護者の方あるいは関係者の方のご意見等もあるようですけれども、最近、東京都議会におけるこの問題についての一定の質疑の中で、東京都の教育委員会のほうの答弁の中には。","voiceIndex":237,"id":"exchange-113"},{"speaker":"西本委員","kind":"質問・要望","question":"専門的な知識と経験が非常に大切になってきます。そういう意味では、就学指導委員会の設置をしているのですから、先ほども言いましたけれども、その機関を活用し、さらに品川ろう学校のような専門機関と連携を強めて障害を持つ子どもたちだけではなく、健常児もかかわることで成長できるような仕組みを図り、既存の機関を最大限活用するように政策に反映をしていただきたいと要望して終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":239,"id":"exchange-114"},{"speaker":"井上委員","kind":"質問","question":"私は、品川・生活者ネットワークを代表して総括質問をいたします。最初に指定管理者制度について伺います。一つには、この二つの施設を指定管理者制度にした理由、そして二つ目に、両施設の指定管理者選定基準の項目はどのようなものであったのか、三つ目は、議会承認の前には選考委員会が行われていますが、委員会の構成メンバーはどのように選出したのでしょうか、伺います。","respondent":"小沼児童保健事業部長","answer":"あるいは管理者の選考にかかわる経費、縮減あるいは削減というような問題がどう図られるかどうか。それから、管理運営を安定継続して行う物的、人的な能力があるかというようなところが大きなところでの選定の基準あるいは選考の基準ということで審査したところです。","voiceIndex":241,"id":"exchange-115"},{"speaker":"井上委員","kind":"質問・要望","question":"三つ目の質問で、選考委員会が行われているはずなんですけれども、その委員会の構成メンバーをどのように選出したかという質問にお答えいただきたいと思います。","respondent":"小沼児童保健事業部長","answer":"企画部の市岡企画財政課長、あるいは榎本行財政改革担当課長、あるいは宮地総務課長、西島経理課長、関連する金子保育課長、辻田児童課長というようなところがメンバーになってあります。構成メンバーは以上申し上げたようなところです。","voiceIndex":243,"id":"exchange-116"},{"speaker":"井上委員","kind":"質問","question":"構成メンバーは伺いましたけれども、どのような基準でこのメンバーになったのか、メンバーはこの施設によって決められたのか、それとも、これからケースによっては選考委員会、メンバーがかわるのかというところの方針というか、考え方をお願いします。","respondent":"小沼児童保健事業部長","answer":"これは福祉施設というようなことがございまして、当然私どものほうの段階では、これはいろいろ議論がございましたけれども、個別に関係するところの関係者でつくり上げたですから、今後、この問題を広く一般にどうするかという話になりますと。","voiceIndex":245,"id":"exchange-117"},{"speaker":"井上委員","kind":"質問・要望","question":"指定管理者制度は利用料金制を取らなければならないという誤解をしている自治体があるという指摘がありますけれども、指定管理者制度と利用料金制はイコールではないということを確認した上で、品川区は、今後の施設のことですけれども、利用料制にするのか、従来どおり使用料にするのかということもあわせて見解をお示しいただきたいと思います。","respondent":"中尾根企画部長","answer":"そこで区といたしましては、これらの移行に際しましては、一つ一つの施設にその特徴なり、今後のあるべき姿、そういうものをつぶさに分析をしまして、ケース・バイ・ケースとして一つ一つ丹念に検討した結果でどのようにしていくか、このように持っていきたい。","voiceIndex":247,"id":"exchange-118"},{"speaker":"井上委員","kind":"質問","question":"今回の心身障害者福祉会館とぷりすくーる西五反田では心身障害者会館の場合には、以前使用料というところで利用料に条例改正をされたわけですけれども、これから移行する施設においては、利用料が適切ではないような施設も見受けられると思うんですけれども、そのことは、今その施設施設において判断をするということでよろしいでしょうか。","respondent":"中尾根企画部長","answer":"先ほど言いましたように一つ一つの施設の性格がありますから、区としては利用料金のことも含めまして、一つ一つの施設ごとにどうすべきかを判断していきたい、このように考えてあります。","voiceIndex":249,"id":"exchange-119"},{"speaker":"井上委員","kind":"質問・要望","question":"管理運営委託している施設が、２００６年までに指定管理者か直営にしていくのかということを決めていかなければなりませんけれども、どのような基準で指定管理者制度に取り組まれようとしているのか、また今後の予定として条例改正、議会承認の時期についてどうお考えになっているのか、具体的にお示しいただきたいと思います。","respondent":"小沼児童保健事業部長、中尾根企画部長","answer":"今、手元に具体的な資料がないので的確な数字をちょっと言いかねるところはあるんですが、たしかぷりすくーるの関係ですと。その、考えていく場合での検討といたしましては、区といたしましては、その指定管理者制度に充当するのに形式的にならないように。それから３０万円以下の金額の場合でしたらば、支払っている委託料の中で対応してもらう、こういうような取り決めでぷりすくーるの場合にはしています。","voiceIndex":251,"id":"exchange-120"},{"speaker":"井上委員","kind":"質問","question":"もう一つ、この施設がそういう収入増になる施設かどうかというのはまたあれなんですけれども、委託料の問題として、収入が多くなったら委託料を下げるとか、そういうところの協議は盛り込まれているんでしょうか。","respondent":"中尾根企画部長","answer":"したがって、その中で、そういう実際上の当初考えていたとおりの収支にあるのかどうか、ここをきちんと検証しろと、法律的にもこうなっておりますので、そういう清算行為というものは必ずそこのところに付随して起こるというふうに私どもは受け取ってございまして。","voiceIndex":255,"id":"exchange-121"},{"speaker":"井上委員","kind":"質問","question":"神戸市が２００４年３月に策定した公の施設の指定管理者制度運用指針は大変参考になるものですが、ご覧になっていただいていたらいいなと思うんですけれども、品川区でも運用指針を策定して取り組まれることが必要だと思いますけれども、お考えを伺います。","respondent":"中尾根企画部長","answer":"このことについて、私どもはこういうふうに全く反対の考えがあるような事態について、あらかじめ議会の意思を本来は図ってすべきことについて、行政側で一方的にこういう方針で出すというのは実際上いかがなものかなというふうに思ってございまして、もっともっとこれが進んで。","voiceIndex":257,"id":"exchange-122"},{"speaker":"井上委員","kind":"質問・要望","question":"先ほど答弁がありましたけれども、指定管理者制度を導入するに当たり、指定管理者の選定に際して幅広く公募を行うこと、選定過程や手続の透明性、公正性を高めていくために、外部の有識者の参画による選定委員会を事業部ごとに設置すること、選定結果の公表などを盛り込むというような指針をぜひつくっていただきたいということを要望して次の質問に行きます。子どもを取り巻く安全対策について伺います。","respondent":"古川教育次長","answer":"具体的な例を幾つか申し上げますと、例えば子どもに対しましては集団による下校ということで、これは教職員も対応いたしておりますし、さらにはＣＡＰの実施ということ、そして、これは一番大きな部分ですけれども、関係諸機関との連携です。","voiceIndex":259,"id":"exchange-123"},{"speaker":"井上委員","kind":"質問","question":"もう一つ、品川ではものづくり品川宿に委託をして、近隣セキュリティーシステムの開発に取り組まれておりますが、その進捗状況と、学校防犯システムにどのように連携されるのか、伺います。","respondent":"山田区民生活事業部長","answer":"近隣セキュリティーシステムの進捗状況等についてのお尋ねですが、品川区独自の防犯システムであります近隣セキュリティーシステムにつきましては、現在技術者ＮＰＯのものづくり品川宿に委託をいたしまして、児童の安全対策に重点を置いたシステムの構築に向けて。","voiceIndex":261,"id":"exchange-124"},{"speaker":"井上委員","kind":"質問","question":"大人が関心を持たなかったり、留守宅が増えれば、防犯ブザーや近隣システムも役に立たないということになります。そういった意味では、学校を取り巻く地域全体で道具に頼り過ぎない人と人との助け合いのソフト面を充実することが大切になると思いますが、いかがでしょうか。","respondent":"古川教育次長","answer":"特に今年度、小学校ＰＴＡ連合会、いわゆる小Ｐ連の４０校の共通の目標として、子どもの安全というものを取り上げながら、保護者がみずから主体的に学校行政と一体となって子どもたちの安全を守る、こういう大変心強いテーマを掲げながら。","voiceIndex":263,"id":"exchange-125"},{"speaker":"井上委員","kind":"質問","question":"小Ｐ連の皆さんがそういった目標を持たれていることは、今後安全なまちづくりという視点では大変いいことだと思います。このような地域を大人たち、私たち大人がつくってきました。通学路の安全に不安を持つ保護者も多いので、ぜひ行政が先ほどの小Ｐ連の皆さんとともに事務局を担う形で、子どもたち、親、先生たち、地域の皆さんで通学路の点検を行ってはどうかと思いますが、お考えはいかがでしょうか。","respondent":"古川教育次長","answer":"安全に対する意識を高める上でも、通学路あるいは通学路周辺のさまざまな安全性の確認、これは大事なことだろうと思ってありますし、教育委員会といたしましても、それぞれの学校が主体となりながら、ＰＴＡそして地域の方々の協力を得ながら、さらに充実した地域安全マップ。","voiceIndex":265,"id":"exchange-126"},{"speaker":"井上委員","kind":"提案","question":"午前中の委員の発言にもありましたけれども、私たち生活者ネットワークも議会提案や予算要望で、子ども自身が危険から身も守るＣＡＰ、暴力防止プログラムを学校教育に取り入れることを求めてきました。成長段階に合わせて行うことがさらに有効です。２００３年６月の生活者ネットワークの一般質問では、保護者からの要望があれば検討すると回答をいただきました。","respondent":"古川教育次長","answer":"これもＰＴＡ、小Ｐ連のほうとのいろいろなお話をしていく中で、やはりこのＣＡＰを子ども、そして保護者あるいは学校が一体となりながら進めていくということについての有効性、これについては教育委員会としても十分に承知していますので。","voiceIndex":267,"id":"exchange-127"},{"speaker":"井上委員","kind":"質問・要望","question":"私たちもＣＡＰを実際に行いましたけれども、１回のプログラムは大体３万円ほどということで、低学年と高学年と年齢に合わせたプログラムが必要であるということ、ですから小学校では８０回、４０校で８０回２４０万円、また中学生プログラムでは５４万円というような、そのぐらいの経費だと思いますので、ぜひ有志が、保護者がやろうとして家庭学級でやるということではなくて。","respondent":"若月教育長","answer":"今やっているプラン２１のほうは、初めの学校に対する目的といったことでありますけれども、大きく分けますと、一つはまず子どもたちに対してでありますが、何も特別なことを学校に要求しているわけではありません。","voiceIndex":269,"id":"exchange-128"},{"speaker":"井上委員","kind":"質問","question":"小学校での基礎基本の習得は非常に大切なことで、最低限身につけなければならない学力です。子どもがみずから学ぶ力と学ぶ喜びをこの時期に育てることも重要です。品川区は教育の成果、学校が成果を出すということをどのように考えているのか、伺います。","respondent":"若月教育長","answer":"今申し上げましたねらいでプラン２１を進めております。そして、学校がある程度の成果を出してくださいなと言っていることも事実です。","voiceIndex":271,"id":"exchange-129"},{"speaker":"井上委員","kind":"質問","question":"それで、ちょっと小中一貫教育のことについて伺いますけれども、２００６年より全校に移行するという方針を示していますけれども、実際に小中学校の連携には学校の立地によっては非常に困難なところが見受けられます。実際にはどのように一貫教育を全区展開していこうと考えられているのでしょうか。","respondent":"若月教育長","answer":"この点につきましても一貫教育を全区展開するということは、もちろん形態の問題もありますけれども、大事なことは今一生懸命開発をしている小中一貫教育のカリキュラムの実施なんです。これが一番大事なことなんです。","voiceIndex":273,"id":"exchange-130"},{"speaker":"井上委員","kind":"質問","question":"学校間の組み合わせは学校同士で決めるとか、始まってから学校の創意工夫に任せる、また各学校が学校の特色を出していくというようなことでは学校現場に負担がかかり、子どもたちに与える影響が大変大きいと思いますが、その点はいかがでしょうか。現在まで保護者には小中一貫教育の情報をどのような形で周知しているのか、また保護者の意見をどのように聞いているのか伺います。","respondent":"若月教育長","answer":"広報紙、それから小中一貫教育ニュース、それからホームページ、各学校からのお知らせ、説明会、そうしたもので保護者の皆様方にはこの移行期間の手当てといったようなものを十分に説明し、不安のない。","voiceIndex":275,"id":"exchange-131"},{"speaker":"井上委員","kind":"質問","question":"さまざまな方法で保護者に周知しているということなんですが、実際に小中一貫教育のモデルを実施しているところがあると思いますが、どこに行けば、その小中一貫教育の授業を見ることができるんでしょうか。","respondent":"若月教育長","answer":"今一番具体的に見られるところは、日野中学校あるいは第二日野小学校、ここではもう既に幾つかの授業を実際に試行しています。","voiceIndex":277,"id":"exchange-132"},{"speaker":"井上委員","kind":"質問","question":"今回の小中一貫教育の説明では、３・４年生で学習指導要領より年間で国語は５０時間、算数は５５時間授業時間が増えます。授業時間を増やすということは、遠足や運動会の練習、写生大会とか課外授業などの行事の時間が減ってしまうのではないかということは一つ伺います。教育課程表の中に総合学習の時間が示されていませんが、これをどう考えるのか、ご説明ください。","respondent":"若月教育長","answer":"それからまた、特に中学校の授業時数が増えるということですが、これは実は数のマジックがありまして、中学校は５０分授業なんですね。ところが一貫教育でありますから、４５分授業でそろえなければならないんです。そうすると５分間足りなくなるんです。","voiceIndex":279,"id":"exchange-133"},{"speaker":"井上委員","kind":"質問","question":"総合学習の時間の件なんですが、市民科に充てる時間がどこなのかということと、もし総合学習の時間が市民科に入っていないのであれば、市民科の時間というのは教育課程表にはありませんでしたけれども、それはどうなっているんでしょうか。","respondent":"若月教育長","answer":"しかし、それだけでは高学年になった場合にちょっと足りない部分が出てきます。その一部を総合的な学習の時間から持ってくるということであります。そういう計算をしているということです。おわかりになりますか。","voiceIndex":281,"id":"exchange-134"},{"speaker":"井上委員","kind":"質問","question":"表はもちろんおわかりだと思いますけれども、じゃあ、そのことを時間がなくなりますので、それは改めてお伺いしたいと思います。外国籍の子どもたちを市民としてどう育てていくのか、またとても大切なことなので伺いますけれども、障害児が学校でともに学ぶという姿勢が見えてきませんけれども、この点についてはどのようにお考えでしょうか。","respondent":"若月教育長","answer":"それから二つ目、障害児の件ですね。これは先ほどもちょっと別の方の委員のご質問に答えておりますが、特別支援教育と言ったようなもの、あるいは支援学校、支援学級といったようなものは今検討されているというのは先ほどもご答弁をしたばかりであります。","voiceIndex":283,"id":"exchange-135"},{"speaker":"井上委員","kind":"意見","question":"この特別支援教育というのは、インクルージョンで統合教育だというところで、そういう特別支援教室をつくるということではなくて、もっと普通に子どもたちを一緒に、ともに学ぶということなんですけれども、今そういう仕組みがあるからということで、なかなかともに学ぶという姿勢を今お答えいただいていないと思うんですけれども、もう一度学校でともに学ぶということをご説明ください。","respondent":"若月教育長","answer":"一貫校であろうとどうであろうと、今はもう既に品川区はかなりそうなんですけれども、その場面、場面、その子どもたちの障害の実態や種類、そうしたものに応じてともに学ぶというような場面というのは、今後も一貫校の中でも十分に展開をしていく、そういう考えであります。","voiceIndex":285,"id":"exchange-136"},{"speaker":"井上委員","kind":"質問","question":"現在の品川区の公立離れの要因に、品川の教育の目指すところが見えてこない、情報提供の欠如に不信感を募らせているという状況があると思います。開かれた学校を指導する立場の教育委員会は、率先して情報開示をする姿勢を区民に見せるべきですが、お考えを伺います。","respondent":"古川教育次長","answer":"私どもは、これからも教育委員会一丸となりまして、学校もそうですが、さまざまな教育にかかわる情報を区民の方々に提供していくような、そういうことを進めていく考えです。","voiceIndex":287,"id":"exchange-137"},{"speaker":"井上委員","kind":"質問・要望","question":"小中一貫教育に関して言えば、保護者の方からどういう議論がされているのか何も見えてこないという意見も聞いています。ぜひ決定をしてからではなくて、そういう計画段階においても、先生方に説明したのと同じように、影響を受けるのは子どもたちであるということを考えて、当事者にもっと積極的に情報公開をしていただく姿勢を求めて終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":289,"id":"exchange-138"},{"speaker":"原委員","kind":"質問・要望","question":"我が党会派所属議員は、本決算特別委員会に向け、各議員の活動に加え、区内各種団体からのヒアリング等の要望、あるいは政務調査会における政策研究、また各種検討会の結果を質問してまいりました。区長ならびに各事業部におかれましては、これら会派所属議員の質問および会派として提出しました政策要望等を踏まえ、平成１７年度の品川区予算に反映していただけますよう強く要望をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":291,"id":"exchange-139"},{"speaker":"三上委員","kind":"提案","question":"公衆浴場の健康づくり施策の支援対策を初め、次世代育成支援対策推進法に関する施策の展開、ふれあいサポート活動、ヒートアイランド対策を含めた環境問題、地域再生等都市再生、監査委員会から恒常的に指摘を受ける学校職員の都費職員の仕事における責任体制、また一両日中にも台風２３号の影響が東京にも予想されますが、災害状況をリアルタイムで区民への映像提供を即刻検討することを求めるなど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":293,"id":"exchange-140"},{"speaker":"高星委員","kind":"質問・要望","question":"品川区民連合を代表して意見表明を行います。指摘をしておきたいと思います。最後に本委員会審査において、我が会派委員から申し上げました意見、指摘いたしました事柄について、今後の区政執行の中に生かしていただくよう強く要望し、平成１５年度品川区一般会計歳入歳出決算初め、すべての事業会計歳入歳出決算の認定に賛成をいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":295,"id":"exchange-141"},{"speaker":"宮崎委員","kind":"質問・要望","question":"大崎駅西口中地区開発はオフィスから住宅中心に計画を変更しまして、都営住宅や区営住宅はつくらないが、税金から７０億円も補助して高級マンションをつくる、こんな開発は自治体が率先して進めることでしょうか。抜本的見直しを求めます。この問題の改善を求めた我が党の質問に、高橋区長は月１４万円で仕事をできることはすばらしいと述べました。議員への情報提供については重ねて改善を求めます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":297,"id":"exchange-142"},{"speaker":"本田委員","kind":"質問・要望","question":"以下、意見と要望を簡潔に申し上げます。平成１５年度は区政総合業績評価制度を構築しましたが、内部評価にとどまらず、区民への説明責任、事業の透明性や満足度の高い効率的施策の展開に十分生かしていくよう要望いたします。最後に、私ども無所属の会議員の各種意見や要望について十分にご賢察いただき、予算や施策に反映されますことを要望して意見表明といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":299,"id":"exchange-143"},{"speaker":"井上委員","kind":"質問・要望","question":"生活者ネットワークは意見と要望を以下に述べまして、平成１５年度品川区一般会計決算および国民健康保険事業会計、老人保健医療特別会計、介護保険特別会計、用地特別会計の各歳入歳出決算に対し、認定いたします。事務事業評価が２期目を迎えてさらに区民にわかりやすいものになることを望みますが、内部評価を公表し、区民の評価を求めることで、区民が主体的になれる仕組みづくりを積極的に行うべきです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":301,"id":"exchange-144"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1240#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":131304,"voices":307}},{"id":"h16-20041104-6","meetingId":"h16-cm11","date":"2004年11月4日","dateIso":"2004-11-04","committee":"区民委員会","time":"午後１時０３分～午後３時３６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"所管事務調査、中小製造業の活性化に向けた主な取り組み","agenda":"所管事務調査、中小製造業の活性化に向けた主な取り組み","exchanges":[{"speaker":"原委員","kind":"意見","question":"平成１５年度実績を見ても、果たしてそれがどのような結果に結びついているのかというのが大事な状況だし、例えばここで予算額を出していただいていますが、それに向けていろいろ実績を上げられて、いろんな企業が参加されて、じゃそれをどうやってフィードバックされているのかというところを挙げていただければなと思うんです。","respondent":"日下部産業振興課長","answer":"宣伝もうまくできない。そういったところを行政側が側面から支援することによりまして、少しでもものづくりの基盤の復活、それから形成ということで、行政として支援していくということが今非常に重要であると、このように考えております。","voiceIndex":8,"id":"exchange-001"},{"speaker":"原委員","kind":"質問","question":"それがやっぱり活性化に結びつく原点であって、その辺のところのお考え、そしてまたこれはそれで終わるわけではなくて、次々と見直しをしていかなきゃならない部分もたくさん出てきていると思うので、その辺の今後の中の状況についてお考えがあればお聞きしたいと思います。","respondent":"日下部産業振興課長","answer":"見直しというようなお話でありますけれども、実はこの前産業界の皆さんといろいろ意見交換をすることがありましたけれども、そこで一つ言われましたことは、もう中小の製造業というのは、言葉は悪いけれども、やはり意欲がないとなかなか生き残っていくことが難しいわけで。","voiceIndex":10,"id":"exchange-002"},{"speaker":"原委員","kind":"質問・要望","question":"中小企業の活性化と、単に言ってしまえばそれで終りなんですが、そこにいろんな事業がついて回り、いろんな実績が出てくるわけで、常にその部分に目を向けていなければならない。取り組みについては積極的にいかなきゃならない。そういったところを今後の中でしっかり検討していっていただきたい。これについては要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"藤原委員","kind":"質問","question":"こうした効果という意味でお伺いしたいんですけれども、新製品・新技術の開発費用の一部助成なんですけれども、これはお貸しするんじゃなくてお金を差し上げるわけですよね。確か、審査のときに、会社の方を呼ばれて何名かで面接をして、決まるまで審査が厳しいんですよね。","respondent":"日下部産業振興課長","answer":"それを活用して、私もよくわからないんですが、小型のリニアモーターの技術がいろんな形で汎用性があると。これもおそらく相当市場性が高いのではないかと、そういう形で成果に結びついているんじゃないかと、このように認識をしております。","voiceIndex":13,"id":"exchange-004"},{"speaker":"藤原委員","kind":"質問","question":"新技術開発等も経営の一環だと思うんですけれども、一番最後に融資のあっ旋をして信用保証協会の保証料の助成とか、利子補給とかしていますが、こういう施策をしているにも係わらず、また別に助成をするという意味というのを教えてもらいたいと思います。","respondent":"日下部産業振興課長","answer":"そういったことも含めて、直接的な助成策ということで新製品の開発という形で進めておりますので、そういう意味では経営の基盤に係わる資金の融資、一方で新しいものをつくり出すといいますか、それに乗っかっているわけですけれども、そういう別な観点からの助成ということで。","voiceIndex":15,"id":"exchange-005"},{"speaker":"藤原委員","kind":"質問","question":"最後に、また戻っちゃうんですけれども、一部助成では条件が品川区にある企業だと思うんですけれども、新開発をして成功したらすぐ品川区から出て行っちゃったとかというようなことはないと思うんですけれども、例えば何年間は品川区にいてくださいよとかという条件はないと思うんですけれども、いい技術を開発した企業が。","respondent":"日下部産業振興課長","answer":"ただ、ちょっと手元に持っておりませんけれども、区内で３年ぐらい操業の実績があるということで条件について説明していますし、そういった意味では、やはり品川区にしっかりと根付いた企業に対する一つの投資といいますか、そういう前提で助成をしていますので。","voiceIndex":17,"id":"exchange-006"},{"speaker":"山村委員","kind":"質問","question":"基本的なことをお聞きしたいと思うんですが、品川区内にある中小製造業の数と、それが大体１０年前ぐらいからどのぐらい減ったかということと、これから１０年間どのぐらい減りそうなのか、これがわかるんでしたら教えていただければと思います。","respondent":"日下部産業振興課長","answer":"そういったことも含めまして、大分工場が地域の中に残っていけるような法制度上の条件も変わってまいりましたので、そういったことも含めまして、私どもとしましては何とか地域にそのまま残っていただくというような形で考えていきたいと、このように思っております。","voiceIndex":19,"id":"exchange-007"},{"speaker":"山村委員","kind":"質問","question":"平成１５年度で２,０００件というのは、経営している状態の件数でしょうか。","respondent":"日下部産業振興課長","answer":"基本的には、経営をしているという実態があるものということで承知しております。","voiceIndex":21,"id":"exchange-008"},{"speaker":"菊地委員","kind":"質問","question":"天王洲のほうなんですけれども、先ほどの課長の説明ですと実際にある会社の新部門という意味なのかどうか。創業支援という意味合いからすると、実際にある会社の新部門に貸していく考え方というのは、創業支援という意味合いからすると、ちょっと違うのかなというような気もするんですけれども、Ｊタワーの場合と天王洲の場合との考え方の違いを教えていただければと思います。","respondent":"日下部産業振興課長","answer":"最初に西大井の応募の状況ですけれども、創業支援スペースのほうが、大ざっぱですが確か５０件ほどの応募がありました。それから、オフィススペースにつきましては、３０件ほどの応募があったです。","voiceIndex":23,"id":"exchange-009"},{"speaker":"菊地委員","kind":"質問","question":"ということであれば、実際に会社として成立していれば、当然一定の資本金があって、それなりの規模の事業展開を現実にやっているわけですよね。実際に応募を取ろうとしたときに、これ以下の企業あるいはこれ以上の企業という規定というのか、そういったものを設けざるを得ないと思うんですけれども、その辺の考え方はどうなんでしょうか。","respondent":"日下部産業振興課長","answer":"先ほども申し上げましたけれども、実際に具体的な募集の基準をどうするかということで、いろいろな角度から検討していますので、その辺はまた別途具体的な考え方が定まった中で、報告をさせていただきたいと思います。","voiceIndex":25,"id":"exchange-010"},{"speaker":"山村委員","kind":"質問","question":"ということは、製造業以外のソフト関係ですとか、例えばこれから金融関係とかいろいろとあると思うんです。製造業以外の業種に関しての助成とか支援というのは、今はないと考えてよろしいんですか。","respondent":"日下部産業振興課長","answer":"この中で技術力の向上等については、やはり製造関係中心になるんですが、例えば資金の融資あっ旋といったものにつきましては、業種を問わずソフトも含めて対応するという状況です。","voiceIndex":29,"id":"exchange-011"},{"speaker":"山村委員","kind":"質問","question":"ソフト関係というのは、結構地元じゃない人が多いと思うんです。助成の周知とかどこまでうまくいっているのかというのはあると思うんですけれども、その辺いかがでしょうか。","respondent":"日下部産業振興課長","answer":"ソフト関係の方というのは、そういった意味では今までのような私どもの通常の広報媒体だけでは、なかなか周知が非常に難しいところがありまして、そういった意味では、今必ずそれと並行してインターネットで情報を提供するとか、そういった一つの大きな流れになっていますから。","voiceIndex":31,"id":"exchange-012"},{"speaker":"山村委員","kind":"意見","question":"アメリカだとシリコンバレーとか言って、ソフト関係の会社ばかり集まって１つのまちが形成されている場所とかあるわけですね。はっきり申し上げて、製造業よりもそっちに日本の企業自体が集中していかざるを得ないところがあると思うので、未来を見据えるのだったら、もうちょっとソフト関係のほうに助成等の新しい形を考えていったほうがいいんじゃないかと思うんですけれども、どのように思うのか。","respondent":"日下部産業振興課長、山田区民生活事業部長","answer":"そういうことも含めまして、ソフト関係もこれから非常に重要な産業の一部でありますので、その辺をしっかりやっていくということも大事じゃないかと、このようには考えておりますが、ただ一方でものづくりは基本といいますか。ですから、当然今ここについてこれの助成というやり方をしているんですけれども、そこのところのやり方が効率を考えて、どちらの方向を取ったらいいか、今出ましたベンチャー企業の支援と併せて、第二創業支援ということで。","voiceIndex":33,"id":"exchange-013"},{"speaker":"山村委員","kind":"質問・要望","question":"製造業でもパソコンのソフトを使ってものをつくるようなこととかはわかるんですけれども、結局パソコン世代じゃなく人は使えないとか、そういう部分の支援とか協力とかやったほうがいいんじゃないかと思いますので、そういうことも含めて、これからも頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":36,"id":"exchange-014"},{"speaker":"井上委員","kind":"意見","question":"先ほど何人か同じような意見があったんですけれども、厳しい審査で助成をされているということで、その後の結果はあまりすぐには出ないかもしれないんですけれども、評価の仕組み、結果が助成に対してどうかという仕組みが今どうなっているのかお尋ねしたいと思うんです。","respondent":"日下部産業振興課長","answer":"それを踏まえて、何回も申し上げておりますが、例えば産業交流展での出展に助成をするとか、事後のフォローについても進めていっているという状況です。","voiceIndex":37,"id":"exchange-015"},{"speaker":"井上委員","kind":"質問・要望","question":"だから、助成をしたことが間違いであったということではなく、それを生かせるための出した方々、企業の方たちの声がちゃんとこちらに戻ってくるような仕組みづくりというのは、事務事業評価も、これは一部のところですべての品川区の方たちに関係するものではないという意味では、この方たちと意見の交換、意見を吸い上げる仕組みというのをつくっていかなければいけないと思いますし、先ほどもハード。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":39,"id":"exchange-016"}]},{"id":"topic-02","title":"東京国際空港再拡張事業に係る環境影響評価方法書の概要","agenda":"東京国際空港再拡張事業に係る環境影響評価方法書の概要","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"以前に説明があったときに、行政のほうからも意見をあげて、ほぼ希望どおりの飛行区域になっていったという話がありましたけれども、もう一度確認をさせていただきたいんですけれども、前回の状況からここに至るまでの間というのは、内容的には別に変更されていないということなんでしょうか、飛行区域等について、そこだけお願いします。","respondent":"金井環境課長","answer":"委員のご指摘のとおりでございまして、６月に修正案というのが出されまして、それは私どもが意見を申し述べておりました位置の変更ですとか、高さの変更ですとか、ルートの取りやめとか要望を出しました。","voiceIndex":44,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=2408#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":17095,"voices":48}},{"id":"h16-20041104-7","meetingId":"h16-cm11","date":"2004年11月4日","dateIso":"2004-11-04","committee":"厚生委員会","time":"午後１時０４分～午後２時５０分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"築舘委員","kind":"意見","question":"介護予防のほうの検討ですね、福祉・医療系６委員、痴呆のほうが福祉・医療系８委員というんですが、どういった立場の方を検討されているのかをお聞かせ下さい。","respondent":"早津高齢福祉課長","answer":"痴呆のケアマネージメントにつきましては、これも福祉・医療系となっておりますが、社会福祉施設の理事長以下、ドクターが２人、施設の指導員が２人等です。","voiceIndex":8,"id":"exchange-001"},{"speaker":"築舘委員","kind":"意見","question":"その点の１４ケースにおける、そこまでの選抜の仕方といいますか、その辺の説明があったらお聞かせ下さい。","respondent":"早津高齢福祉課長","answer":"これにつきましては、時期的にも８月からということで、検討会がかなり進んでおりまして、すでに二度ほどこのシートを使った打ち合わせ会が進んでおりまして、一定の成果も、なかなか効果があるのではないかというようなのが、今私どものところに感触として届いているところです。","voiceIndex":10,"id":"exchange-002"},{"speaker":"築舘委員","kind":"意見","question":"これを３月までということで、国が考慮をして、見直しにおける参考にするということだと思うんですけれども、具体的にはどういった形でまとめて、国に影響が与えられるというような感じを持っていらっしゃいますか。","respondent":"早津高齢福祉課長","answer":"そうすると、新しい介護予防給付を実施することで、どの程度の介護度の進行が防止できるのかとかというようなことを考えていくのではないかなというふうに思います。","voiceIndex":12,"id":"exchange-003"},{"speaker":"本多委員","kind":"質問","question":"今の続きなんですけれども、国が各モデルの成果なり、そういったものをまとめて、国がまとめたものを、協力をした自治体のほか、全国の自治体とかにどのようにお知らせいただくのか教えて下さい。","respondent":"早津高齢福祉課長","answer":"具体的なフィードバックの方法まではちょっと不明な点があるんですが、介護予防につきましては、先ほどの中でも、１の介護予防のほうですと、国の事業概要の(4)に、国の介護予防サービス評価委員会云々というようなものが書いてありますけれども。","voiceIndex":14,"id":"exchange-004"},{"speaker":"本多委員","kind":"質問","question":"素直にそのままこれだけで対応できていくのか、その辺をお聞きしたいと思います。","respondent":"早津高齢福祉課長","answer":"ここに挙げました四つの観点は、センター方式のほうで言っていることではなくて、センター方式のほうの解説書を読みますと、もっと抽象的なことが書かれているので、本委員会に説明することにつきまして、従来型とどう違うのかというものを。","voiceIndex":16,"id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問・要望","question":"介護予防のモデル事業のほうですが、この実施期間というのは、国のほうから定められて、この間にまとめなくてはいけないという時期なんでしょうね。１６カ所で今回モデルを実施するということですけれども、多分この作業というのは前から行われていたと思うんですが、センター方式、できたばかりで新しくするのか、前の経過があるのかどうか、その辺も併せて教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"２点の質問のうちの一つ、予防に関する実施期間ですが、上に５つの項目が書いてありますけれども、これのそれぞれによって国のほうで期間を定めてあります。","voiceIndex":18,"id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"改正版ということでは、すでにある程度結果は出されているものなのか、その点が１点。痴呆性高齢者向けのというところで、その辺どう使い分けていくというのか、どこの段階で選ぶのかというのが１点。参加事業所の選定の基準があるのかどうか教えて下さい。","respondent":"早津高齢福祉課長","answer":"対象の選定は、支援センターのケアマネジャーのほうから、この方が幾つかのサービスを使っていること等を含めて対象とするのによいのではないかという選定をして、そのあと使っている事業所に対象としたいが、協力をしてもらえるかというような話をして。","voiceIndex":20,"id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"ケアマネジメント推進モデルのほうの、新しくセンター方式でなお一層すばらしく痴呆のをするということですが、４項目めの痴呆ケアの共通の視点がないのと、センター方式になると共通の視点の形成が可能になるという、ちょっとこれはわからないので、教えていただきたいと思います。","respondent":"早津高齢福祉課長","answer":"３カ所でやっておりますが、私もそれぞれ行きましたが、いずれも意気高く、また、参加された方も非常に喜んでいらしたというようなことを聞いております。引き続き一層の資質向上といいますか、サービス向上に努めたいというふうに思っております。","voiceIndex":22,"id":"exchange-008"},{"speaker":"嶋委員","kind":"質問","question":"選ばれる人は張り切るし、ご本人には周知されるのかどうかわからないんですが、そういう部分と、理学療法士の方も力も入ると思って、わからないようにやっていただけるのが一番デリケートの部分なので、そこら辺をどういうふうに、みんなと同じように、自然体でやるんだけれども、一つの、積極的に気持ちを高めていってあげたほうがもっと頑張れる部分もあるかと思うので。","respondent":"早津高齢福祉課長","answer":"ただ、それにしたとしても、ほかの方と扱いが変わるということはありませんで、むしろ同じようにやったほうが、品川区としては自立の方と要支援の方との差みたいなものも見れますので、同じ形での取り扱いはさせていただこうというふうに考えてあります。","voiceIndex":24,"id":"exchange-009"},{"speaker":"武内委員","kind":"質問","question":"１点だけ、痴呆性高齢者のほうですが、対象ケースで１４ケースということですけれども、この１４ケースの方が、例えば施設入所の方と在宅の方と、何名ぐらい、何ケースぐらいなのか、分かりましたら教えて下さい。","respondent":"早津高齢福祉課長","answer":"１４ケースの方は在宅の方です。結果的に、つい最近になって対象ケースの方の中で特別養護老人ホームに入られた方が１人いらっしゃいますが、在宅でのサービスということになりますので、在宅系の方です。","voiceIndex":26,"id":"exchange-010"},{"speaker":"本間委員","kind":"意見","question":"介護予防という、今までとは違った、いわゆる予防という部分に力を入れた中身が非常に前向きな捉え方をしている部分だと思います。国の指導でこのような形で参加自治体の７６のうちの一つに選ばれて、今回進めていくですが、このことは、参加対象プログラムというふうに出ておりますけれども、通常の業務の中で、ふだん行われている業務の範疇のもので済む程度のものであるのかどうかということです。","respondent":"早津高齢福祉課長","answer":"ただ、筋力向上トレーニングで申し上げますと、これは品川区として７月から始めた筋力向上トレーニングがスッポリとこれにはまるということになりますので、通常業務という意味で言えば。","voiceIndex":29,"id":"exchange-011"},{"speaker":"本間委員","kind":"意見","question":"平成１２年から介護保険制度が始まって、見直しの５年まであと１年という場面を迎える中での前向きな捉え方ですが、簡単に言えば、介護保険制度の見直しという一言にすぎますが、国の本当の意味でのねらいとするものがどこの辺にあるのか、言いにくい部分もあるかもしれませんけれども、品川区ということでなくて申し訳ないんですが。","respondent":"早津高齢福祉課長","answer":"要介護状態にならないにこしたことはないですし、重度化が進まないほうがいいわけですから、その方にとっても必要だというのがあるんですが、もう一方で、介護度が進めば、給付費も膨らんでいくということは避けようのない事実でございまして、給付費の増加率が非常に高いので。","voiceIndex":31,"id":"exchange-012"},{"speaker":"本間委員","kind":"質問・要望","question":"次に痴呆の部分で、具体的に個々のケースを挙げていただければよろしいんですが、新しいセンター方式によるマネージメント方式が幾つかありますけれども、痴呆介護の特性から、できることをしてもらうという部分ですね、この部分は本人との関係、嫌がったり、なかなか難しい部分もあると思いますが、先ほど、トイレ、食事、入浴の関係がちょっと出ましたけれども。","respondent":"早津高齢福祉課長","answer":"今回ケースの検討をしている中で、一つ出てきたのは、ずっと大工をやっている方がいらして、そういったことがだんだんと分かってきて、今後デイサービスの中で簡単な大工仕事みたいなものをやってもらうといいのではないかというような提案も。","voiceIndex":33,"id":"exchange-013"},{"speaker":"本間委員","kind":"質問","question":"実施期間が８カ月間というようなことで、長い期間なので、今年の８月から来年３月末の長い期間なので、どういう状況かちょっとわからないんですが、ご本人の、いわゆる障害者といいますか、対象者の方の痴呆の介護にあたっておられる方のわがままといいますか、特に年齢がいくとかたくなに周りからの意見とかそういうものを受け入れない、この部分の綱引きによって、新しい仕事とか、新しい人を付けるような。","respondent":"早津高齢福祉課長","answer":"ですから、新しいスタッフを動員してというような考え方は基本的にはとっておりません。","voiceIndex":35,"id":"exchange-014"},{"speaker":"南副委員長","kind":"質問・要望","question":"しかし、要介護３とか、要介護４とか、要介護５でも、それなりの筋力向上のためのサービスというのは必要だというふうに思っているんですけれども、そういう方たちに向けてのサービスがどれぐらい対応できるかどうかありますけれども、いわゆるそういう重度の方々の筋力向上、使える能力は大いに使って、それ以上悪くさせないというそこの考え方として。","respondent":"早津高齢福祉課長","answer":"介護予防のモデル事業の終了後ですが、品川区では筋力向上トレーニングにしても、身近なリハビリにしても、すでに本格実施をしておりまして、その後につきましては、改善された方については、例えばふれあい健康塾ですとか。","voiceIndex":37,"id":"exchange-015"},{"speaker":"南副委員長","kind":"質問・要望","question":"ですから、すべての方々が希望されれば、また払える能力があれば、使い切っていくということが大事だと思うので、その辺の体制も充実をしていただきたいというふうに思っています。どんな内容で、どのくらいの方々がサービスを使っておられるのか、これは歯医者のほうのサービスだというふうに思っているんですけれども、実態がどういうふうになっているのか、分かる範囲で結構ですから、教えて下さい。","respondent":"新美福祉高齢事業部長","answer":"こういったこともモデル事業を実施しながら、特に来年度までが第３期の平成１８年度から始まる介護保険事業計画をこれから具体的に検討をしてまいります。","voiceIndex":39,"id":"exchange-016"},{"speaker":"南副委員長","kind":"質問・要望","question":"最後にしたいと思いますが、前段のところは分かりました。それは施設だとか病院での話ですが、品川区も７カ所の施設を抱えていらっしゃいますから、そういうところで、例えば全体的な状況を見て、適切な施設サービスが提供できるようにしていただくという点で、改めて継続してこのことを取り上げてみたんですけれども、そういう視点もお伝えいただいて、対応サービスを充実させていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-017"},{"speaker":"築舘委員","kind":"質問","question":"それと、３点目は、最初に入ったときは日常生活が営めて、自炊が可能な方ということで入るわけですけれども、例えばそれが自炊ができなくなった、また、日常生活がきつくなってきて、寝込むまではいかないでしょうけれども、要介護度などが進んできたというような場合に、退去をするような状況が今までに出たのかどうか、そこのところを教えて下さい。","respondent":"蓼沼高齢事業課長","answer":"入居登録者は例年４０名程度になってあります。このうち入居される方が例年１５名から２０名ぐらいかと思います。そのほか１０名ぐらいの方がご辞退されたり、転出したり、施設に入ったり等々で、登録順位の３０名ぐらいの方までは入居その他で何らかの形で解決している状況です。","voiceIndex":49,"id":"exchange-018"},{"speaker":"武内委員","kind":"質問・要望","question":"私も３点お願いしたいんですが、一つは、保証人がいない方の場合の対応はどうなっているか。それから、こういった高齢者住宅は今後、今のところ増やす予定がないように以前に伺ったんですけれども、その主な理由みたいなものがあれば教えていただきたい。それから、これは単身者用の入居になっておりますけれども、ご夫婦の方などの場合にこういったものがあれば、そのご案内を教えていただきたいと思います。","respondent":"蓼沼高齢事業課長","answer":"高齢者住宅はこれ以外にもあんしんの住まいですとか、あるいはケアホームのような住まいタイプの施設といったような多様な取り組みをしてきてございまして、あるいは軽費老人ホーム、東海ホーム等もございまして、数的には３００戸以上の数になりまして、一定程度。","voiceIndex":51,"id":"exchange-019"},{"speaker":"武内委員","kind":"質問","question":"保証人の件ですけれども、第三者でも、その方が了解をされていればＯＫの場合もあるということでよろしいのかどうか。夫婦の場合は、２戸というんですが、これはどの辺にあるのかというのと、２戸なので、おそらくこういった形の募集はかけないと思うんですけれども、その辺の夫婦用の住宅をもう少し確保していくようなご予定があるのかないのか、その辺のところを教えて下さい。","respondent":"蓼沼高齢事業課長","answer":"今のところは増やす予定はございませんが、ご夫婦向けのものにつきましては、当面はあっ旋というものがありますので、ご夫婦世帯、これは条件が整えばそういうあっ旋が可能ですので、そちらで対応をしてまいりたいというふうに考えてあります。","voiceIndex":53,"id":"exchange-020"},{"speaker":"南副委員長","kind":"質問","question":"そうしますと、本来だったら、新たに社会福祉法人をつくる予定だったのが、福栄会で運営をお願いして、当面は品川区が国の分の２分の１の運営費を出して、東京都と一緒になった経費で運営をしていただくという計画で進めていくということなんですか。もう一つは、補助金がつかないと法内化ができないという、この辺のところを改めて、分かったようでわからないので、もう少し教えていただければと思います。","respondent":"西島障害者福祉課長","answer":"１点目につきましては、そのとおりでございまして、新規に法人をつくるためには、法内化をいたしまして、基本財産が必要ということになりますし、法内化できませんので、そういう部分がなくなりました。したがいまして、福栄会のほうに運営委託をするです。","voiceIndex":60,"id":"exchange-021"},{"speaker":"嶋委員","kind":"確認","question":"大変な中、品川区が単独でスタートをしていただけるということで、精神障害を持った方にとっては大変朗報かと思います。そういう意味では、事業内容も、ここに書かれている内容の事業内容を進めていただけるんでしょうか、確認をさせて下さい。","respondent":"西島障害者福祉課長","answer":"授産施設につきましては、現在自主製品作業等をやってありますが、それに合わせてクリーニング等をここで実施をするという予定で進めてまいりたいというふうに考えてあります。","voiceIndex":62,"id":"exchange-022"},{"speaker":"嶋委員","kind":"質問・要望","question":"私どもも党としても、しっかりと国、東京都にも働きかけていきたいと思っています。ぜひこれが継続的に続けていかれるように、また、障害を持った方たちの、ここに溜まり場をつくっていただけるということがあるので、これは一番の嬉しいところかなと思っています。そういう意味では、たくさんの方がここに溜まり場になるように、ぜひ頑張っていただきたいなと考えていますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":64,"id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"先ほど国と東京都が国庫補助のところ２分の１ということですが、全体的にどのくらい施設のところにかかるのか、あと運営でどのくらいかかって、品川区がどのぐらい負担をしていくのかの大枠のところを教えて下さい。","respondent":"西島障害者福祉課長","answer":"生活支援センターの運営費ですけれども、来年度のいつからによってということでは金額が違ってまいりますが、平年度的に考えますと、約２,１５０万円ほどではなかろうかというふうに考えてあります。","voiceIndex":65,"id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"運営費のところは、丸々品川区で負担をすると２,１５０万円ということですか。","respondent":"西島障害者福祉課長","answer":"生活支援センターにつきましては、２,１５０万円で、それを東京都と品川区で、東京都が２分の１、品川区が２分の１という形になろうかと思います。","voiceIndex":67,"id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"もう１点ですが、社会福祉法人が新規じゃなくて、福栄会と今協議中ということだったんですけれども、平成１７年度中に開設をするわけですけれども、ここのところ指定管理者制度に係わってくる施設なのかどうか、その点を１点教えて下さい。","respondent":"西島障害者福祉課長","answer":"指定管理者制度との絡みですけれども、事業の委託ですので、指定管理者制度とは直接は係わらないというふうに考えてあります。","voiceIndex":69,"id":"exchange-026"},{"speaker":"築舘委員","kind":"質問","question":"福栄会の件ですけれども、新しく社会福祉法人を新設するというときには、どんな形でそれを設立しようというふうに考えていたのか。その後だめになって福栄会になった経緯を教えて下さい。","respondent":"新美福祉高齢事業部長","answer":"運営主体の問題ですが、通所授産施設、あるいは生活支援センターの整備につきましては、精神障害者保健福祉関係では、これまでかなり長い間の懸案事項でございまして、場所等を選定するということで３年半前から具体的に考えて、そのときに、従来からの家族会等々の要望の中で。","voiceIndex":71,"id":"exchange-027"},{"speaker":"築舘委員","kind":"質問・要望","question":"福栄会のほうもいろいろ事業を拡大しているというか、かなり受け持っているから、その点はしっかりと、福栄会頼みということもあるとは思うんですけれども、もちろん負担になってくるわけなんで、その辺をしっかり見ておいていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-028"},{"speaker":"南副委員長","kind":"質問・要望","question":"さっき伺えばよかったんですけれども、福栄会が受けていただくということになって、それはそれでよかったなとは思うんですけれども、家族会が頑張っていきたいということで、いろいろ活動をされて、品川区との調整、協議をされてきたわけですが、家族会も当然了解されてこういうふうになってきたんだろうというふうには思うんですけれども、改めてその辺というのはどうだったのか。","respondent":"西島障害者福祉課長","answer":"家族会につきましては、品川区のほうの考え方をご説明いたしまして、少なくとも現状のままではなかなか打開策が見つからないというような状況は家族会のほうも十分理解されておりまして、これについては一歩でも二歩でも前進だということで。","voiceIndex":74,"id":"exchange-029"}]},{"id":"topic-02","title":"の２、その他","agenda":"の２、その他","exchanges":[{"speaker":"本間委員","kind":"質問・要望","question":"委員長のほうでご丁寧にそれぞれ各所管の要望というふうなことでございましたが、私が聞き及ぶ部分におきまして、これまでも私どものほうでも団員がいるわけですけれども、何回かに分けまして、厚生委員会所管の部分でかなり勉強を続けておられるようですし、これも経験に照らし合わせて見ますに、相手方のほうの日程調整の部分と、こちらのほうの日程とすり合わせ等々もありますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":79,"id":"exchange-030"},{"speaker":"南副委員長","kind":"質問・要望","question":"そういうふうに進んでいっては、ちょっといろいろな問題が出てくるというふうに思いますので、改めてそれとは仕分けをしておいたほうがいいんじゃないかなと私は思っておりますので、何らかの形の機会のときに委員長のほうからその旨もお伝えをいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-031"},{"speaker":"南副委員長","kind":"質問・要望","question":"きちんと会派のうちの２会派だけが海外調査には賛成されて、あとは反対という状況もあるし、海外調査に行くということ自体がいろいろと今問題の出ているところなので、そこのところはそういうふうにやっていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":83,"id":"exchange-032"},{"speaker":"南副委員長","kind":"質問","question":"啓発セミナー開催そのものは本当に歓迎できる話なんですけれども、時期が、今までの経過があってのこの時期、一日も早くという思いなんでしょうけれども、１２月に入ってしまうと、一般的には気ぜわしいかなという気がするんです。例えば１１月だとか、あるいは来年１月に回すとか、その辺の検討はどういうふうになって１２月の中旬あたりになったのか、時期が時期だったので、その辺だけ教えて下さい。","respondent":"辻田児童課長","answer":"もう１点は、国のほうから何とか年内にこの事業を実施してほしいというような要請もございまして、私どものほうとしては、１２月１５日を過ぎると本当にせわしなくなるという状況もありますので、何とかその前というところでこの日にちを設定したものです。","voiceIndex":91,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3094#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":31943,"voices":94}},{"id":"h16-20041105-8","meetingId":"h16-cm11","date":"2004年11月5日","dateIso":"2004-11-05","committee":"建設委員会","time":"午前１０時１８分～午後３時１５分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の戸越幹線貯留管整備工事事業説明会の開催","agenda":"の戸越幹線貯留管整備工事事業説明会の開催","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"長期間にわたって工事をされるということなんですけど、２６号線の通りは交通規制はあるにせよ通行の妨げにならないと思うんですけれども、ほかの場所は、やはり場合によっては通行止めに完全になっちゃうんでしょうか。","respondent":"矢部下水道河川課長","answer":"発進立坑につきましては平塚中学校などなので、それについて交通の支障はございません。裏の図面の戸越銀座側なんですが、立坑というのが４カ所設置する予定なんですが、これにつきましては、作業時間帯は通行止めという形になってあります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この戸越幹線貯留管で、すべてで貯留管ができた場合にどれぐらいの量が貯留できるのかというふうなことと、これの貯留管工事で、どれぐらいの予算になっているのかということを教えていただきたいんですけれども。","respondent":"矢部下水道河川課長","answer":"それで、もう一つ平塚一丁目のほうに工事を予定している場所がございまして、その辺は今回の工事の効果を見ながら検討したいと思っているんですが、そこについては大体５００ｔぐらい、ですからトータルしますと３,０００ｔぐらいになるのかなという感じがしております。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"６億５,０００万円というのは今回のだけですか。全体ではどれぐらいなのかもちょっとお伺いします。","respondent":"矢部下水道河川課長","answer":"その２工事しか積算しておりませんので、そのトータルの金額についてはまだ。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"貯留管と調整池との考え方なんですけれども、そこら辺のところがここの地域でも調整池をつくるとかというような対応ではなくて、今回貯留管になったというふうなところでは、その調整池と貯留管との対応の考え方についてちょっと教えてください。","respondent":"矢部下水道河川課長","answer":"ただし、今回につきましては、そういうような適地がございませんので、道路の下に埋設をするです。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須貝委員","kind":"意見","question":"１点だけなんですけれども、工事のよく時間帯が問題になるんですね。業者側からすれば、交通量の少ない夜間、深夜をできるだけ工事の時間帯に持っていきたい。その辺の考え方として、できるだけ昼間にやってほしいけれども、昼間はまだ通行量もあるし、その辺はどのように工事の時間帯を考えていらっしゃいますか。","respondent":"矢部下水道河川課長","answer":"それで、最終的にはその次の工事のときに再度説明をして、住民の方の意見を聞きながら決めていきたいと考えています。","voiceIndex":13,"id":"exchange-005"},{"speaker":"高星委員","kind":"質問","question":"それの影響を軽減するということに、今回あまり関係ないような気がするんだけれども。この間の２３号の雨の場合については、もう戸越幹線に水が落ちる前の話のような気がしてならないんだけれども、直接この間の２３号のような台風の荒れた様子での形にはならないのかなというふうに思うんですけれども、その辺はどうなるんですか。","respondent":"矢部下水道河川課長","answer":"ですから、２３号のような場合、ちょっと雨の降り方によっても違いますけれども、被害の軽減にはつながると考えております。","voiceIndex":16,"id":"exchange-006"},{"speaker":"大沢委員","kind":"質問・要望","question":"５番の主な意見のところの騒音、振動について、実際に説明会をされたときに住民の方からはどのような要望というか、意見が出ていたのか、ちょっとおわかりになれば教えていただきたいんですが。","respondent":"矢部下水道河川課長","answer":"うちのほうの答えとしますと、基本的には戸越銀座以外は昼間やらせてもらう。要するに最新式の無振動というんですか、振動もほとんどなく、騒音も非常に少ない形の施工を一応考えております、というようなお話をしています。","voiceIndex":18,"id":"exchange-007"},{"speaker":"大沢委員","kind":"質問","question":"ほんとうに基本的で、地下何ｍぐらいにシールド工法を掘るというふうに、これは掘っていくわけなんですか、地下何ｍぐらいなんですか。","respondent":"矢部下水道河川課長","answer":"発進立坑の平塚中学校付近で深さが約１０ｍ。管の上側までなんですけれども、約１０ｍあります。それから、補助２６号線から区道に入る部分、ここが９ｍ４０、それで一番下流の戸越銀座周辺でいきますと、５ｍぐらいになります。","voiceIndex":20,"id":"exchange-008"},{"speaker":"大沢委員","kind":"質問","question":"それは地下を掘っていくわけですから、それによって地盤の沈下また地下水が枯れるとか、そういう弊害というのはあるんでしょうか。","respondent":"矢部下水道河川課長","answer":"これは目黒川の雨水バイパスでも採用しておりますし、そちらのほうでもそういう沈下の話とか、そういうものは一切出ておりません。同じような状況かと思います。","voiceIndex":24,"id":"exchange-009"},{"speaker":"大沢委員","kind":"質問","question":"ちょっと例えばなんですけれども、昆虫の幼虫が地面を掘りまして、体内から特別な液を出して回りを固めていく、そんなような形なわけですか。","respondent":"矢部下水道河川課長","answer":"確かにシールドで掘った場合に、余掘部分というんですか、外形よりもちょっと大きめに掘ります。そこの部分につきましては、委員ご指摘のとおり、モルタルといって裏塗りをします。そこで地盤沈下が起きないような形で施工してまいります。","voiceIndex":26,"id":"exchange-010"}]},{"id":"topic-02","title":"(3) の大崎駅西口Ｅ東地区（明電舎地区）開発事業","agenda":"(3) の大崎駅西口Ｅ東地区（明電舎地区）開発事業","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この明電舎の建物が地上３０階、地下２階、容積対象面積が１４万平米ですか、こういう大きな建物ができますけれども、この明電舎のこういう開発によって昼間人口がどれぐらい増えるのか、車台数がどれぐらい増えるのか、多分環境アセスの対象にならないという状況になっていると思うんですけれども、そこら辺の状況がどういうふうになるのかをひとつ教えていただきたいのと、それからあと。","respondent":"上野都市開発課長","answer":"それからあと、昨年１２月に開通しました東西自由通路から西口、さらに明電舎の開発にあわせましてデッキの延伸をする予定ですけれども、このデッキの整備を含めて明電舎の開発者負担で行うこととなっていますが。","voiceIndex":37,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"昼間人口は押さえていないということなんですけれども、商業関係はどれぐらいというふうなものの予想というのはなかなか難しいと思うんですけれども、事務所関係ではどれぐらいになるのかというふうなことをわかる範囲で教えていただきたいのと、それで車も全体で８,０００台ということですけれども、そしてまた、そのうち４,０００台が明電舎というふうなことですが、そこから出る廃熱がどの程度だとか。","respondent":"上野都市開発課長","answer":"それの全体をまたＣＯ2というものは、またある計算をしないと出てこないものですから、それはその環境計画書には計算までは義務づけられているものではなくて、別途それは計算書に基づいて、後で計算してみないとわからないという状況になります。","voiceIndex":39,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"大崎地区は６０haという、あれだけで次々と開発がされているわけなんですが、そこをトータルするとかなりのＣＯ2の増加というふうなことにつながってくると思いますので、そこら辺のところは区としてもぜひつかんで、質問に答えていただけるようにお願いしたいなというふうに思います。","respondent":"上野都市開発課長","answer":"工事車両につきましては１６３号線から環６のほうにつながるルートで処理する予定ですけれども、幾つか工事が輻輳してくるおそれもありますから、それを事業者間での相互調整を行うこととしてございまして。","voiceIndex":41,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ちょっと具体的によく見えてこないんですけれども、ぜひそこの安全面のところには配慮しながら進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":43,"id":"exchange-014"},{"speaker":"三上委員","kind":"確認","question":"確認だけさせてもらいたいんだけれども、この明電舎のこの地区に当たっては駐輪場で自転車が１５３台、バイク１７台ということで、今の大崎の駐車場、駐輪場というのは道路を使いながらやっていた中で、この台数的な部分で間に合うのかどうかということですよね。","respondent":"上野都市開発課長","answer":"別紙１に書いてあります自転車駐輪場の規模につきまして、これは明電舎の建物の中で必要となるいわゆる付置義務に相当するような台数でございまして、駅周辺の現状あります自転車とバイクにつきましては、今交通広場の下に駐輪所を設ける予定となっていまして、それに今。","voiceIndex":44,"id":"exchange-015"},{"speaker":"三上委員","kind":"質問","question":"図面を見ながら、この台数ということで同じような場所的な位置なので、そういうことで質問しちゃったんですけれども、別なところに地下６００台という形で整備されるのはそれなりのものかなというようには思いますけれども、わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":46,"id":"exchange-016"}]},{"id":"topic-03","title":"の御成橋再生水放水施設","agenda":"の御成橋再生水放水施設","exchanges":[{"speaker":"大沢委員","kind":"質問・要望","question":"放水用ノズル、ライトアップ用照明８基、それと水位計、もろもろのこの施設設備といいますか、このものがあるんですけれども、定期的な点検は行われるのか、それとメンテナンスが行われるとすると、どれぐらいの費用がかかるのか教えていただきたいと思います。","respondent":"上野都市開発課長","answer":"設置につきましては、これは東京都の下水道局との関係で整備しているものですけれども、管理は品川区の品川大崎土木事務所が実施する予定です。","voiceIndex":52,"id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"東京都の下水道局の芝浦水再生センターから持ってくるということなんですけれども、これはここまでのルートというものは、管をこの既設のものを使うというものなのかどうなのか、そこら辺のところを教えていただきたいのと、それと、これによって目黒川の水質改善ということなんですけれども、どれぐらいの水質が改善されるという、そういう面がありましたら教えてください。","respondent":"上野都市開発課長","answer":"それからあと水質改善につきましては、先ほどの時間帯で大体１日に合計で１８０ｔぐらいの水を流す予定でございまして、この水そのものが、まずは非常に従来の下水道局の再生水では砂ろ過だけでろ過していたんですけれども、それよりもさらに生物膜ろ過とか。","voiceIndex":54,"id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"効果が期待できるということで楽しみだなと思うんですけれども、これは実際にどれぐらい改善したかというふうなデータはこれからもとっていくというふうなものはあるんでしょうか。","respondent":"矢部下水道河川課長","answer":"これにつきましては、目黒川につきましては、当区でもそうですし、環境局のほうで定期的に水質調査しておりますので、その辺のデータを見れば、改善の効果とか、そういうのはわかるかと思います。","voiceIndex":56,"id":"exchange-019"},{"speaker":"須貝委員","kind":"質問","question":"あそこはたしか住宅が若干あったように思うんですが、今まで音がなかったようなところに急に音が発生するような状況にはなると思うんですけれども、その辺のご検討はどうですか。","respondent":"上野都市開発課長","answer":"川の水面を打つ音がしまして、懸念されますのは都営住宅がそばにありますので、その都営住宅の足元あたりまで行きますと音がほとんど気にならないぐらいまで下がるのは確認されましたけれども、居住されている上の階の方でどのぐらいの音がするのかは、居住者の方に。","voiceIndex":58,"id":"exchange-020"},{"speaker":"須貝委員","kind":"意見","question":"これはほんとうにいいことだと思うんで、ぜひ何とかこういう方法をいろいろなところで進められてほしいんですけれども、夜間どのぐらい影響が出るか、９時半ごろまでということなんでぎりぎりのところだと思うんですけれども、一応チェックだけお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":60,"id":"exchange-021"},{"speaker":"高星委員","kind":"質問","question":"あるいは放水している間に往々にしてあるのは、風と水しぶきの関係があるね。音よりもそっちのほうが大変だろうと思います。そこら辺のときに調整というのはできるのかどうなのかということについてだけ、ちょっとお聞きしたい。昼間の間でも。そこだけちょっと教えてください。","respondent":"上野都市開発課長","answer":"時間帯は、この朝８時半から夜９時半ぐらいまでの間しか定期的にしか行わない予定でございまして、それ以外の夜間は放水をしない予定です。","voiceIndex":61,"id":"exchange-022"},{"speaker":"高星委員","kind":"質問","question":"問題なのは、だから、通常のときとか、水しぶきが上がらなきゃいい。上がったときに、水量調節とか何かというのはできるのかなと思ったからちょっとお聞きしただけのことです。それと、どっちにしてもあの辺は親水公園というか、親水護岸というか、それから護岸の擁壁の緑化等々が進んでいるので、それとうまくマッチングしたような形で住民に喜ばれるようなものにしてもらいたい。","respondent":"上野都市開発課長","answer":"当面９日以降、１カ月ぐらいは試験的な放水期間として考えてございまして、その間、この水の流し方も含めて、少し調整しながら様子を見たいというふうに考えてございまして、そのときの状況に応じて、もしそういう水しぶきが舞い上がるような状況とか。","voiceIndex":63,"id":"exchange-023"},{"speaker":"大沢委員","kind":"質問","question":"とまるときはどんなときにとまるんでしょうか。放水がとまるときというのはあるんでしょうか。","respondent":"上野都市開発課長","answer":"基本的にはこの通常のタイマーでもって定時的にバルブを上げたり開いたりして調整しているわけですけれども、そういう災害が予想される場合には、もう管理者の責任において事前に近づいてきた場合には、バルブをとめてしまう、そういう措置をとります。","voiceIndex":65,"id":"exchange-024"},{"speaker":"大沢委員","kind":"質問","question":"そのときはもろもろの状況によってとめるということ。だれがどこで調整するのですか。","respondent":"松代道路公園課長","answer":"これは私ども道路公園課が、先ほど言いましたように品川大崎土木事務所というところで責任をもって管理をします。今ご質問がありましたように、台風等のときには私どもの職員がきちんとバルブを締めるとか、そういうふうなことをすることと考えています。","voiceIndex":67,"id":"exchange-025"},{"speaker":"須貝委員","kind":"質問","question":"ちょっともう１点だけお聞きしたいんですけれども、再生水を放水するということで、これは水面上に放水して、水質をそれでよくなるんじゃないかなという効果を考えているところはあると思うんですけれども、実際に水面上よりは、ほんとうは水質を浄化するならば水中に流したほうがいいんじゃないかなと思うんですけれども、その辺ちょっとどちらに聞いたらいいのかな。","respondent":"上野都市開発課長","answer":"この施設は浄化だけを目的としてつくっているものでございませんで、こういう橋から放水することによって、この地域の景観を新たにつくっていく、そういうことも目的の一つとしていますから、確かに浄化だけを効果としてねらうのであれば別のやり方があろうかと思いますけれども。","voiceIndex":69,"id":"exchange-026"},{"speaker":"伊藤委員長","kind":"質問・要望","question":"その他で何かありますでしょうか。では、ないようですので私から報告をします。前回の委員会におきまして、議長より平成１６年度品川区議会海外調査項目にかかわる調査要望書についての依頼があり、意見等がございましたら１０月２２日までに正副委員長のほうにということで、お願いをいたしました。要望があったものをもとにして正副委員長で精査させていただいたものです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":74,"id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=3800#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":13823,"voices":76}},{"id":"h16-20041105-9","meetingId":"h16-cm11","date":"2004年11月5日","dateIso":"2004-11-05","committee":"文教委員会","time":"午後１時０３分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"平成１６年特別区人事委員会「職員の給与に関する報告」の概要","agenda":"平成１６年特別区人事委員会「職員の給与に関する報告」の概要","exchanges":[{"speaker":"林（宏）委員","kind":"確認","question":"確認します。１ページ目の下から４行目、「年２回とすること」というのは、３月のは名前が違うから別ですよというふうにとる意味が入っているわけ。","respondent":"市川庶務課長","answer":"名称のいかんにかかわらず、民間の要するに夏期、冬期のいわゆるボーナスということで支給されていることに対して、公務員の場合、これまで例えば夏、冬は期末手当、それから３月は勤勉と、それからある時期から期末と勤勉がミックスされてきたような。","voiceIndex":5,"id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"だから、もとは民間と比較しているわけだよね。(2) のところとか上の部分ではね。そういったここで教育委員会で聞くことがいいのか、出たからちょっと聞いておくんだけど、いわゆる清掃に関係する部分の人事委員会からの意見というのは、一切触れられていないですか。これだけだとわからないんだけど。どうこうじゃなくて、触れているのか触れていないのかだけ聞かせてください。","respondent":"市川庶務課長","answer":"今回、本委員会で説明するに当たりまして、私がいろいろ資料を見た限りでは、特に清掃に触れられての指摘なりはなかったというふうに考えてあります。","voiceIndex":7,"id":"exchange-002"}]},{"id":"topic-02","title":"荏原文化センター温水プール等改修工事による休場","agenda":"荏原文化センター温水プール等改修工事による休場","exchanges":[{"speaker":"西本委員","kind":"質問・要望","question":"ちょっと確認をさせていただきたいんですが、周知方法の(1)番で、定期的に利用されている方たち、それから水泳教室みたいなものがあったと思うんですが、それに対する対応ですね、例えばほかの施設を当面使っていただくというような形なんですか、この辺はどういうふうになっているのか。","respondent":"上川内生涯学習課長","answer":"プールなんですが、昔近隣の学校のプールをお願いしたということがあるんですが、今そこをお願いしようと思って伺ったらば、ちょうどこの時期はプールを使わない、繁忙期の反対、閑散期だということで、そこも改修工事をするということで使えなくて、あと、総合体育館とか。","voiceIndex":13,"id":"exchange-003"},{"speaker":"西本委員","kind":"質問・要望","question":"子どもたちも水泳教室、いろいろな団体がおられるんですよね。それで、結構利用されている方が多いですし、個人の方でも結構利用されているんですね。工事が近い状況になると、知らない人もだんだん周知する形になると思うんですけれども、これは要望ですけれども、丁寧な対応でいろんなところと交渉を率先してやっていただきたいというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"この２の工事内容を見ると、天井を直して、壁を直して、プールサイドを直して、水槽を直して、更衣室・シャワー室を直すというのは、全部取りかえるという意味にとっていいんですか。","respondent":"上川内生涯学習課長","answer":"全部取りかえるというのではなくて、天井とかは取りかえますが、床とかは滑らないようにゴムの入った塗装をするとか、上から塗装する部分もありますし、またタイルのはがれた部分はそこだけ補修をして。","voiceIndex":16,"id":"exchange-005"},{"speaker":"林（宏）委員","kind":"質問","question":"荏原文化センターそのものが建てかえられないという、全体的にね、容積だとか何だとか、理由はわからないけど、今言われたこともそうだけど、これを見たら全面改修だよね。そうすると、プールはこれで、この先１０年、２０年やって、耐震ということについては、今回の工事に関しては入っていないんですか。","respondent":"上川内生涯学習課長","answer":"今回の工事については入っておりません。","voiceIndex":18,"id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"これだけの改修工事をするんだったらば、あそこは地下ですよね。半地下というのか、地下ですね。そうすると、やっぱりそこら辺、きちんとしていくべきだろうと僕は思う。ただ落ちているものを改修するならわかるけど、最初に聞いたら全面工事じゃないということで、これは全面工事に近いですよ。としたら、やっぱりその辺、きちんとして工事をやっていくべきだと僕は思うんだけど、この工事費は幾らですか。","respondent":"上川内生涯学習課長","answer":"おおよそ６,４００万円です。","voiceIndex":20,"id":"exchange-007"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、耐震工事をやるかやらないかという検討をして、例えばその費用的に同じぐらい耐震の検査あるいは検査結果によっては、工事代と、それが１億２,０００万円にはね上がるとか、そういうことは検討されたんですか。","respondent":"上川内生涯学習課長","answer":"耐震につきましては、部分的な耐震というのはちょっと困難だろうということで、やるんだったら全体的ということもありますが、耐震につきましては、区のほうで計画的にこれから進めていくという方向も伺っておりますので。","voiceIndex":22,"id":"exchange-008"},{"speaker":"林（宏）委員","kind":"質問","question":"最後の説明、違うんだよ。じゃあ、上の部分のプール以外のところをやったときには耐震検査をやったんですか。","respondent":"古川教育次長","answer":"したがいまして、耐震性につきましては、全体の中でまた対応していきたい、このように考えております。","voiceIndex":24,"id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"プールを全部をつくると１億２,０００万円から１億５,０００万円と言われているから、それは金額的な部分でやるんでしょう。だから、やっぱり校庭なんかも改修するときに検査しているようだから、やっぱり全面に近い改修をするときは、耐震の検査をして改修していくということは頭の中に入れておくべきだと僕は思いますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":26,"id":"exchange-010"},{"speaker":"藤田委員","kind":"質問","question":"プールの利用者の声なんですけれども、そうした声が今回の改修の中で生きているのかどうか、その辺をちょっとお伺いしたい。","respondent":"上川内生涯学習課長","answer":"例えば更衣室がじめじめしているとか、男性のほうが、私は女性しか見られないんですが、構造上換気が男性のほうが悪いとか、地下２階にありますから、やはり、そういう部分もあるんですが、今回換気も含めてやっていこうとか、あと、プールサイドのところが。","voiceIndex":27,"id":"exchange-011"},{"speaker":"藤田委員","kind":"質問","question":"そういう面で、一番端っこの１コースだけでも歩けるような施設にしてもらえないだろうかという声をちらっと今まで聞いたものですから、今回いいチャンスで、あそこは６コースぐらいあるんでしょうか、はっきりしませんけれども、一番端の１コース、わずか往復できるようなスペースですから、そういう面で今回の改修に合わせて、そうした皆さんの声を生かすことはできないんでしょうか。","respondent":"上川内生涯学習課長","answer":"荏原文化センターのプールは真ん中のところが１.５メートルで、こちらが１.２メートルというふうに、真ん中が深くなっているのは知っています。","voiceIndex":29,"id":"exchange-012"},{"speaker":"藤田委員","kind":"質問","question":"そうなると何十年先になりますよね。ですから、構造上、もしできれば、こういうふうになっていても、多少の最初のフラットのところだけでも削るとか、何かちょっと、今水中ウォークが非常に人気が高いわけですよ。むしろ、泳ぎよりも歩きたいんだという、そういう希望がかなり多いわけですから、ぜひ計画をできないかと。ちょっとしつこいようですけど。","respondent":"古川教育次長","answer":"戸越台中学校がそうですし、今後、大崎の小中一貫校でもそういう設備になっていこうかと思うんですが、この荏原文化センターのプールは昭和４５年ということで、当時のつくりは、プール全体の本体が鉄板をコーティングしているのもあれば、焼き付けとか。","voiceIndex":31,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問・要望","question":"私も近くの民間のプールなんですけど、６年間通っているんですけども、ほとんど皆さん歩いていらっしゃるんですね。それだけものすごい人気があるということをまず念頭に置いて、ぜひ検討できるところは検討していただきたい。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":33,"id":"exchange-014"},{"speaker":"沢田委員","kind":"質問","question":"今の次長の答弁の中で、昭和４５年ですか、オープンは。そうですね。それで、ちょっとお尋ねしたいんですが、改修計画というのは、先ほど１９９０年に全面改修をやったということなんですが、どんなテンポで、計画でやっているのか、ちょっとお尋ねしたいと思うんですが。","respondent":"上川内生涯学習課長","answer":"大規模改修というのは、１９７０年にオープンして、１９９０年ですから２０年で、ほぼ全面改修をしてきた経過があります。","voiceIndex":34,"id":"exchange-015"},{"speaker":"沢田委員","kind":"質問・要望","question":"今７０年と聞いたので、余計にちょっと思ったんですけれども、先ほど論議があった屋上屋を架するようなもんなんですけど、そこは要望して、早く軌道に乗せていただきたいということだけ述べておきます。最初のほうだけちょっと。","respondent":"市川庶務課長","answer":"その意味で、昨年から始まりました耐震診断、これはこれから今の段階では学校児童施設ですけれども、文化センターについてもそういう対応をしなければいけないと思っています。","voiceIndex":36,"id":"exchange-016"},{"speaker":"沢田委員","kind":"意見","question":"あまり深く言うべきあれじゃないと思うんですけど、耐震計画、屋上防水だと十二、三年、あるいは１５年ぐらいの間で傷んだらやるという、もたせるだけもたせるというのは一般にやっていることですけど、前に決算特別委員会か予算特別委員会で私が言ったらば、そういうものは持っていないと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":38,"id":"exchange-017"}]},{"id":"topic-03","title":"品川区子ども読書活動推進計画（案）","agenda":"品川区子ども読書活動推進計画（案）","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"この計画の目標の一番上のところに、子どもの読書環境の整備が必要だと、本文の中にも中学生で本を読む子が５割いるんですけれども、学校図書館の利用は５ページですか、２割強に満たないのは、やっぱり読書環境の整備がおくれていることが要因じゃないかという指摘がありますけど、今回の計画で現状がどうなっているのか、この辺を解明されるのかということをちょっと伺いたいと思うんですけれども、まず。","respondent":"古里品川図書館長、谷田部学務課長","answer":"ビジネス支援図書館につきましては、資料費を約１,０００万円投じていただきまして、区立図書館の資料費についても全体で１,０００万円程度今年度は増額をさせていただいてあります。中学校になりますと、この基本の数字が先ほど６学級でちょっと単純にご説明申し上げました。基本となるもと、数字が４,８００冊になります。これに６４０冊に学級数から２を引いた、残った学級数で掛けたものを足して蔵書数にすると。","voiceIndex":43,"id":"exchange-018"},{"speaker":"中塚委員","kind":"質問・要望","question":"ただ、この計画の中に具体的に蔵書の、例えば先ほどの資料費、今後どのように改善していくのか、５年間の間に。５年間の計画ですけれども、やっぱり先ほどの分析の中にも読書環境の整備がおくれているという指摘がありましたけれども、こういった改善の目標といいますか、５年間のこういった数値目標はどのようになっているのでしょうか、教えていただきたい。","respondent":"古里品川図書館長","answer":"それに基づいて学校図書館につきましては、具体的にこれから整備していこうという方針が大体内部で方針が固まりつつありますものですから、学校図書館についてはこれからその整備計画をつくりながら進めていきましょうということで、それは別個の計画を立てる形になりますので。","voiceIndex":46,"id":"exchange-019"},{"speaker":"中塚委員","kind":"質問・要望","question":"子どもたちが本を好きになって、計画をぜひ進めていただければと思うんですけど、具体的な中に、例えば図書館の冷房化を進めていくとか、いろいろ工夫が入っているかと思うんですけれども、そこの５年間、やっぱり現状、このアンケートを見ると、ほんとうに本を読む生徒が年々減ってきている、読書と親しんでほしいなと思いますので、ぜひ、これはソフト的な中身だと言いますけども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":48,"id":"exchange-020"},{"speaker":"沢田委員","kind":"質問","question":"１点だけ聞きたいんですが、区民からの意見を募集するという、その募集する中身は何を一番聞こうとしているのか、ちょっと教えてください。","respondent":"古里品川図書館長","answer":"こちらから区民の皆さんにこういう意見をご提案してほしいという恣意的な意図はございませんので、この計画案を見ていただいた上で、この子ども読書活動推進というところで我々のほうでつくりました案を見ていただきながら、区民の方にこういうこともしてほしいとか。","voiceIndex":49,"id":"exchange-021"},{"speaker":"沢田委員","kind":"質問","question":"だから、そういう点ではこの問題は教育の中で、先日の総括質問を繰り返すつもりはないんですけど、やっぱり漢字が重荷で逃避したいというふうにしない、むしろ漢字を進んで勉強できるような、そういう教育とあわせてやっていくためにどうするかというふうに考える必要があるんじゃないのかなというふうな気がします。これ以上やると、この間の続きみたいになりますのでやりませんけど、終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":53,"id":"exchange-022"},{"speaker":"大西委員","kind":"質問・要望","question":"ちょっと本筋から外れるかもわかりませんけど、ちょっとお尋ねしたい点があります。子どもに例えば親が読ませたい本だとか、もしくは、親が読みたい本、よく新聞なんかの、中刷りというんですか、下のほうに出ている部分でありますけども、そういうものが図書館にない場合に、そういうものを読みたいというときには、図書館に何らかのあれで購入を求めることがまずはできるんでしょうか。","respondent":"古里品川図書館長","answer":"区立図書館全体で所蔵していない本については、今２３区あるいは都立中央図書館と連携をしていますので、そちらから借用してご提供する、少しお時間はかかりますが、そういう制度もあります。","voiceIndex":54,"id":"exchange-023"},{"speaker":"大西委員","kind":"質問","question":"ということは、後段の今言われた中で、例えば新刊の部分については、リクエストということが相当するわけですか。","respondent":"古里品川図書館長","answer":"そのようになるかと思います。","voiceIndex":56,"id":"exchange-024"},{"speaker":"大西委員","kind":"質問","question":"子どもの教育に対して悩んでいる人にはこういうふうにという形で、何らかの形でこういう本を読まれることをお勧めしますという形で、新聞紙上で単にやっているんじゃなしに、私どものほうから、行政のほうで発信していく、こういうものはこういう点でお役に立ちますよと、だから皆さんもお読みになられたらどうでしょうかと勧めてみて、そして、そうだ読んでみようかという大人の部分と。","respondent":"古里品川図書館長","answer":"先ほどいろんなテーマでのブックリストの関係ですが、今区立図書館では魅力ある図書館づくりということで、経営の改善を含めていろいろ検討していますが、この中でもそうした区民の皆さんの関心の高いテーマについてのブックリストを、今年度の終わりぐらいか。","voiceIndex":58,"id":"exchange-025"},{"speaker":"西本委員","kind":"確認","question":"ちょっと確認をまずしたいんですが、「この読書活動の推進に関する法律」が平成１３年の１２月ということで、推進計画策定委員会というのが平成１６年４月に設置ということがあるんですが、この間はどういうふうな動きがあったのか。","respondent":"古里品川図書館長","answer":"それで１５年に入りまして、品川区として、じゃあ東京都の計画を受けてどうするかという検討を１５年度の途中から再検討させていただきまして、１６年の当初から策定委員会を設置して、品川区における計画の検討を行ってきたというのがこの間の経過です。","voiceIndex":60,"id":"exchange-026"},{"speaker":"西本委員","kind":"質問","question":"ちょっと聞き逃したかもしれないんですが、推進委員会というのが今度新たに設置されるということで、策定委員のメンバーを見ましても、福祉の方もいらっしゃいますし、横の関係もあって、その中でいろいろ考えられているというのはあるんですが、今後の連携ですが、どういうふうにしていくのか、リーダーというのがいないと、なかなか推進していくことが難しいかと思いますので。","respondent":"古里品川図書館長","answer":"案の７ページの第四ですが、推進会議の設置ということをうたってあります。この推進会議でこの読書活動をこの５年間で実施していくに当たって、子どもたちに推進をするための会議を設置するです。","voiceIndex":64,"id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"そうすると、平成１７年から実際に委員会、推進会議を設置するということなんですが、そうすると、まだ構想段階だと思いますけど、１７年というのは来年なので、どういう関係の方たちを想定されるのか、例えば家庭を含めたり、それから就学前後の子どもたちを考えたりとかしたときには、かなりいろんな関係者を集めないといけないのではないかなと、教育にかかわっている方だけじゃなくて。","respondent":"古里品川図書館長","answer":"ほかの区のあるいは自治体の推進計画を見ましても、おおよそ大体のところで推進会議を設置してございまして、そこにいろんな構成メンバーも既に載ってあります。それらを参考にしながら、私どもも検討は進めていきたいというふうに思ってあります。","voiceIndex":66,"id":"exchange-028"},{"speaker":"西本委員","kind":"質問・要望","question":"それからあと、先ほど読書の日というのを設定するというふうに言っていますが、これも要望なんですが、コンクールだけをやるといってもなかなか集まりにくいと思いますので、例えば評価をしてあげる、だれかの一番の成果といいますか、たくさん読んだ子に何か賞状を出すとか、そういうものを入れてやると、それをきっかけにしてちょっとやってみようかなというところがありますので。","respondent":"中島指導課長","answer":"今委員のご指摘のように、現在でも学校のほうでは朝の読書ですとか、それからまた教師ですとか親、こういった部分での読み聞かせ活動を実施する実態があります。","voiceIndex":68,"id":"exchange-029"},{"speaker":"林（宏）委員","kind":"提案","question":"いろいろ提案や要望が出てきているけども、ここに書いてある１１月２１日から１月２０日まで要望を受け付けて、計画の策定をしていくとあるんだけど、今日ここで言われた議員の要望とかというのと、区民からの要望募集と、どういうふうに位置づけていかれるんですか。それから、文教委員会は１月２０日まで何回も開かれるんだけど、そこでまた要望と出していって受け付けるんですか。","respondent":"古里品川図書館長","answer":"区議会の中であるいは文教委員会の中で改めて最終計画を提示するに当たりまして、報告はさせていただき、またその中でご論議いただき、それが計画案の修正が必要であれば、私どものほうとして策定委員会で協議いたしまして。","voiceIndex":70,"id":"exchange-030"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"だから、ちょっとそういう意味で、この推進計画案というのが、趣旨がどこにあって、どういう意味合いを持ってこの推進計画をつくり、この推進計画に沿って品川区は具体的にこういう施策を進めていきたいんだと、そういうものまで出さないと、この推進計画案に対する要望と、いわゆる図書館への要望とか、そういうことに直接的なものの意見が多くなっちゃうと、せっかく寄せられてきている意見が。","respondent":"古里品川図書館長","answer":"それをそのまま使ったということですので、委員ご指摘のことですので、最終的な計画の中では言葉の使い方を変更させていただきたいと思います。","voiceIndex":72,"id":"exchange-031"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"いや、図書館の用語としてあるなら使っていけばいいんだし、それをここに書けばいいんですよ。今の説明をね。早く言えば、１３から１８歳というのは中高生。それをあえて図書館の用語として使えばいいし、使わないなら、中高生と一般的に言っていると思うんだよな。だから、細かい話であれですけど、この中身について要望を僕らもメールで訴えていけばいいということになりますわな。","respondent":"古里品川図書館長","answer":"こういう文教委員会の場でのご意見以外にお申し出いただくんであれば、メール等でお送りいただければ結構だと思いますし、私に直接お電話をいただいても結構です。その中で政策論議等させていただければと思います。","voiceIndex":74,"id":"exchange-032"},{"speaker":"林（宏）委員","kind":"意見","question":"やっぱり、生まれて、三つ子の魂じゃないけど、さっき親が読む姿を見るという、それも段階的にはあるんだろうけど、それ以前で、やっぱり言葉もわからない、字も読めないという段階から耳に言葉が入ってくること、それは本を聞かせる、あるいは話をするというところから、ほんとうに生まれてすぐから始まっている、あるいは生まれる前の胎教という言葉もあるけれど。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":76,"id":"exchange-033"},{"speaker":"中塚委員","kind":"確認","question":"１０月の末に校長会が行われたというのをちょっと聞きまして、１０月２９日、確認だけなんですけれども、校長会小中一貫校のカリキュラムが決定したという話をちょっと聞いたんで、その辺、何を決定したのかと、今日じゃなくていいんですけど、議会への報告はどういう形になるのか、それだけちょっと教えてください。","respondent":"中島指導課長","answer":"１０月２８日の木曜日の日に区内の小中学校の校長、教頭、そして小中一貫教育の教育課程を中心的に編成していく担当、これが各学校３名ということで、全校の教員を集めて研修会を行いました。そこで、現在取り組んでいるカリキュラムの進捗状況についての説明をいたしました。","voiceIndex":87,"id":"exchange-034"},{"speaker":"中島委員長","kind":"質問","question":"ほかになければ、私からご案内します。第４回定例会のときの委員会の日に、おそらく１１月３０日になると思いますが、先日の行政視察の報告についてご意見をお伺いしたいと思います。そのときに、このご意見をお伺いし、まとめていきたいと思いますが、よろしいでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=4520#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":26335,"voices":90}},{"id":"h16-20041105-5","meetingId":"h16-cm11","date":"2004年11月5日","dateIso":"2004-11-05","committee":"総務委員会","time":"午後１時０４分～午後２時２４分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を17件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"最初に、１番目の品川区次世代育成支援対策推進行動計画策定の進捗状況","agenda":"最初に、１番目の品川区次世代育成支援対策推進行動計画策定の進捗状況","exchanges":[{"speaker":"若林委員","kind":"意見","question":"いよいよ次世代のほうかなという感じで、２点ほど。いわゆる全庁的な、横断的な次世代に関する委員会といいますか、協議会も、そうでないものもありますけれども、各事業部、児童保健等々、教育委員会等々の人事的な連動、絡みというのはどのようになっているか、まずお教えください。","respondent":"榎本行財政改革担当課長","answer":"その検討会につきましては、この次世代育成に関するすべての事業部とか、すべての課が入っておりまして、その庁内検討会の中で、例えばこの行動計画のたたき台をつくるに当たっては、どういう計画なのか、先の計画はどうなのかと。","voiceIndex":7,"id":"exchange-001"},{"speaker":"若林委員","kind":"質問","question":"例えば、その意見をホームページ等を使って、こういう意見が区民の方から次世代に関してはありましたよと。その中で、これは最終的に取り入れましたとか、こういう意見はこういうふうに計画を立てます、これはちょっと受け入れられませんというようなやりとりというのは、個人的なという意味じゃなくて、対区民全体としてのやりとりというのは何か方向性がありますでしょうか。","respondent":"榎本行財政改革担当課長","answer":"まだちょっと具体的な部分というのは詰めていないんですけれども、流れとしましては、委員おっしゃるように聞いた意見に対して、似たような意見ですとか、グルーピングが多分できると思いますので、そのグループごとに。","voiceIndex":9,"id":"exchange-002"},{"speaker":"若林委員","kind":"確認","question":"ぜひとも、よろしくお願いをいたします。最終的に地域協議会で３月下旬に確認をして、策定というふうに矢印が引っ張ってありますが、ここの段階で、いわゆる庁内検討会はどういう影響力を持っていくんでしょうか。これで最後にします。","respondent":"榎本行財政改革担当課長","answer":"行動計画の中では、ある程度５年スパンのもので考えていますので、すぐ着手できるもの、それから、もう少し煮詰めながら着手できるもの、幾つか段階を経るとは思いますけれども、具体的な動きに入っていくという形で考えています。","voiceIndex":11,"id":"exchange-003"},{"speaker":"若林委員","kind":"確認","question":"策定後の動きはわかりました。策定、最終決定の前、例えば途中の段階とか、最終確認のタイミングで庁内検討会、各事業部、部署の責任者のもみ合いというのがあるかどうかという意味で、もう一回、済みません。","respondent":"榎本行財政改革担当課長","answer":"済みません。それぞれ協議会のほうに出すに当たっては、事前に庁内検討会のほうできちんと調整をとった上で出すという形で考えております。最終的な部分についてはです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"石田委員","kind":"質問・要望","question":"ちょっとわからないので何点か教えていただきたいんですが。問題は、その行動計画を、先ほど言いましたように、中身の実現に向けてどうしていくかという考え方のところだと思うんですけれども、そういうことを考えたときに、私がよくわからないのは、国の指針というのがありますね。もちろん東京都も含めてなんだけど、そこら辺のところを教えてほしいんです。","respondent":"榎本行財政改革担当課長","answer":"それと、例えば保育サービスですと、国が求めているレベルを既に超えてやっている部分もありますので、その辺についても、どこのレベルにするのかとか、そういうものも含めて区のほうは進めていかなきゃいけないものと考えております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"石田委員","kind":"質問・要望","question":"もう一段、その中で、指針の扱いなんだけど、確かに今言った指針の場合は地方交付税というので手当てをしようというお話になって、我々は地方交付税ではないわけで、２３区にいるわけですから、先ほど言ったように、この指針に出てきているものよりも、具体的なことをとれば、品川区はもっとやっているというのは非常にわかるわけです。それをどうやって考えてやろうとされているのか。","respondent":"市岡企画財政課長","answer":"だから、逆に言うと、国の方針があるからとって、区のほうから、これについては国庫補助金をつけるべきだということを、これまでと同じように言っていっていいのかどうかというところが大変問題があって、むしろ税財源の充実、移譲によって、基幹税の移譲によって。","voiceIndex":17,"id":"exchange-006"},{"speaker":"石田委員","kind":"質問・要望","question":"今のところの話だと思うんです。これは避けて通れないところだと思うんです。この財調の問題も根本から、今税源移譲というお話もあったけれども、そこをどうクリアにしていくかということをしていかないと、これから１０年間のスパンで、特に５年間のスパンで考えたとしても、この政策がいい方向で実現していくというと、なかなかそこがつまずくというか。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-007"},{"speaker":"本田委員","kind":"質問","question":"東京２３区だけでも出てくると思うんですけれども。いろいろ施策を打っていくときに、裏づけになる財源がなければ、例えば行政サイドでもたくさん所管が集まってやるわけですけれども、なかなか気合が入ってこないじゃないですか。品川区はもっと上へ行っているじゃないかと。そういうことでいいのかなというふうに、感想として１つ持つんですけれども、どうなんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"自治体間のアンバランスについても、やはり子育てに優しい自治体というのがすべての人が住みやすい町になって選ばれるというのが、一般の点からいきますと、子育てに関しても施策はある程度ばらつきが出るかもしれないですけれども、全体として。","voiceIndex":20,"id":"exchange-008"},{"speaker":"本田委員","kind":"質問","question":"財源のほうでもう一つ伺いますのは、２３区の場合は財調財源というか、自治体でといいますか、２３区の中でも施策的にはばらばらですね。例えば品川区のような医療費無料化の問題では、他区でやっていないところも多いんですけれども、そういう点も含めていこうかとか、そういう議論というのはもう始まっているんですか。","respondent":"市岡企画財政課長","answer":"それで、すぐには財調の新規の項目の中に入れるというのは、都との協議でもなかなか難しいんですが、仮に今年だめでも、方向性として正しければ、必ず数年のうちにはそれが財調算定の項目になってくる可能性がありますので、長くなりましたけれども、そういう視点から。","voiceIndex":22,"id":"exchange-009"},{"speaker":"宮崎委員","kind":"意見","question":"国の具体的な中身というのはどういうふうになっているのかというのを１つ、説明をお願いしたいのと、あと、東京都のほうなんですけれども、先ほども企画財政課長のほうからも施策の方向が、訂正があれば後で財調でついてくるんじゃないかと、なるほどと思ったんですけれども。そうはいっても、現実問題、そうはいっていないんじゃないかという気がするんですけれども。","respondent":"榎本行財政改革担当課長、市岡企画財政課長","answer":"新新エンゼルプランをつくるということで、厚生労働省が今検討を進めておりますけれども、国としては、その新しい新新エンゼルプランというものをつくって、その中で少子化対策を全体的にやっていこうという流れになっております。公立保育所運営費は１６年度にもう国の負担金と都の負担金がなくなりましたので、品川区の予算でいうと、１０億円、歳入が来なくなっています。そのかわり、５億４,０００万円、所得譲与税が来るようになりました。","voiceIndex":26,"id":"exchange-010"},{"speaker":"宮崎委員","kind":"提案","question":"そこら辺の決算特別委員会のときにでも実態調査をやったらいいんじゃないかという提案もしたんですけれども。改めてこの計画をつくる上でどうなのかということを、お伺いしたい。もう一つ、今協議会のほうの構成もありましたけれども、こういうところの方々の提案も、区民の要望を反映してもらうということも必要なんですけれども。","respondent":"榎本行財政改革担当課長","answer":"１点目の意見集約の関係ですけれども、ホームページで意見を集約していくという形です。","voiceIndex":29,"id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問・要望","question":"もう二点なんですけれども。それが具体的にどういう形で施策が考えられているのか、今時点でわかったらお願いしたいということ。出生率は品川区が全都平均よりも低いんですけれども、このところ、何でこれだけ品川区が全都で低いのかというところの品川区の特性といいますか、そこら辺の背景といいますか、そこら辺のところをどういうふうにお考えになっているか、基本的なところですけれども、伺いたいです。","respondent":"榎本行財政改革担当課長","answer":"１点目の経済的負担の軽減の部分ですけれども、やはり区でとったアンケートについても教育費がかかるというのがあります。ただ、実際にもう少しほかの調査で幾つか分析しますと、どこの部分の教育費にかかるのかというと、高校、大学の教育費にかかるというのが圧倒的に多いと。","voiceIndex":31,"id":"exchange-012"},{"speaker":"宮崎委員","kind":"確認","question":"今のを確認しておきたいんですけれども。出生の数自体は増えているけれども、出生率の母数になる女性の、転入も多くて、子どもは増えているんだけれども、割ると減っちゃうんだと。要するに単身の女性が増えているということになるわけですか。そうすると、単純にいくと、この方々がちゃんと結婚して子育ての環境が整っていくと、率そのものも改善していくということになるということですか。","respondent":"榎本行財政改革担当課長","answer":"独身女性というか、１５歳から４９歳の女性の転入率よりも、子どもが増えてくる率のほうが低いという形になっているので、相対的には出生率自体が下がってはきているらしいと。要は、独身というか、１５歳から４９歳の女性がとにかく増えてきているということ自体は間違いない。","voiceIndex":33,"id":"exchange-013"},{"speaker":"宮崎委員","kind":"提案","question":"わかりました。その点で１つと。住宅の問題というのは非常に、ここにも住環境整備というふうになっているんですけれども、私は住宅を考えるということになると、どうしても今、東京都のほうも都営住宅はつくらないし、区のほうも区営住宅は増やさないという方向なんですけれども、私は、ここのところはやっぱり考えざるを得ないと思うんですけれども、そこら辺は何か今時点で方向性はあるんでしょうか。","respondent":"榎本行財政改革担当課長","answer":"やはりこの間の協議会の中でもありましたけれども、マンションがかなり品川区の場合には増えてきておりますので、住環境自体は決して悪くなっているというわけではないというような認識でおります。","voiceIndex":35,"id":"exchange-014"},{"speaker":"宮崎委員","kind":"質問・要望","question":"今、晩婚化の問題で出会える場と、以前、そういう主張をされた方がいたなというのを思い出したんですけれども。これは感想です。こういうふうに、子育てに配慮した住宅、いわゆる住環境だけではなくて住宅ということに着目するのであれば、そこのところを考えていってほしいということを、これは要望になりますけれども。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-015"},{"speaker":"土井委員","kind":"質問・要望","question":"今まで国はさまざまな施策について補助金というスタイル、ひもをつけて落としていた。さあ、何かひもをつけなきゃいかんというので、一生懸命に今度は子育てというか、そういうスタイルの中で指針という形でひもをつけて、それに合った者には金を出すよという形になっているんじゃないかなといううがった見方があるかどうか、その辺はどうお考えかというのが１つ。そこがどうなのか、聞かせていただきたい。","respondent":"榎本行財政改革担当課長","answer":"協議会の中での検討の事項ですけれども、まだ具体的な細かいところまで全部踏み込んではいませんけれども、やはり全体像を見てもらった中で、品川区で何が必要なのかというところの判断というのは１点、必要なのかなと。","voiceIndex":38,"id":"exchange-016"},{"speaker":"土井委員","kind":"質問・要望","question":"品川区や何かの場合は非交付団体ですから、そういう話でなるんだと思うんですけれども、地方の交付団体にしてみれば、結局、交付税というスタイルで包括的な格好でぼんと来るよと。だけれども、こういう形で何本かのひもがもうくっついちゃっていて、それに合ったもの以外はできないという形になってしまうんじゃないかという意味も含めて、そんな思いがしたので話したところです。要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-017"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=1668#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":26796,"voices":47}},{"id":"h16-20041108-11","meetingId":"h16-cm11","date":"2004年11月8日","dateIso":"2004-11-08","committee":"自治制度特別委員会","time":"午後１時０３分～午後２時３２分","status":"正式会議録","sourceType":"formal","overview":"自治制度特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を29件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の１番目、特定事件調査を行います。まず初めに、(1) 都区財政調整協議（主要５課題）に関すること","agenda":"の１番目、特定事件調査を行います。まず初めに、(1) 都区財政調整協議（主要５課題）に関すること","exchanges":[{"speaker":"築舘委員","kind":"意見","question":"細かいことで恐縮ですけれども、４行目の、品川区においても、清掃事業ということで、もちろん分かっていることですけれども、収集・運搬ということで、括弧して、清掃事業（収集・運搬）と書いておけば分かりやすいんじゃないかなということ。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":6,"id":"exchange-001"},{"speaker":"田中委員","kind":"質問・要望","question":"ちょっと基本的な話でお聞きしたいんですが、平成１２年から基礎的自治体になったということで、品川区の議会では「基礎的」という言葉を使っているんですが、先ほどの議長会の決議案には「基礎自治体」とありまして、「的」が抜けているんですが、文言的な調整はどうなっているのか、その辺の考え方をお聞かせいただきたいと思います。","respondent":"市岡企画財政課長","answer":"いわゆる法律のテキスト、教科書などでは「基礎的自治体」という言い方をしておりまして、広域自治体に対して基礎的自治体というのが一般的な表現ではないかと思います。特に間違っているとか何とかではありません。","voiceIndex":8,"id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"そういう意味では、このままでいいかと思います。２３区の思いとしては、今年の１２月ないし来年１月に東京都側からの大都市事務の内容が示されるということで、これまで都区の役割分担を求めてきたという経緯がありますが、最終的な目標というか、求めるのは、役割分担ではなくて、それに基づく財源配分ということだと思います。そのことを品川区の決議案で言えば、５番目に入るんでしょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":10,"id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"そこへ踏み込むのが僕らの考え方だろうと思うので、そうであるならば、今の田中委員のお話のように、都区間の役割分担以上に、もっと踏み込んだ話を我々が先にここへ出しちゃって、得られるものがここまでしかないよという形になるのはやむを得ないけれども、最初からげたを向こうにあずけておいて、我々が突っ込んで絵をかくんじゃなくて、そこのところを先にポンと持っていってしまったら。","respondent":"市岡企画財政課長","answer":"繰り返しますと、５項目をあまりこれまでの経過を踏まえない形で広げると、これは約束していない事項ですと言われると、空回りしてしまいますけれども、考え方を入れる分には構わないと思います。","voiceIndex":11,"id":"exchange-004"},{"speaker":"須藤委員","kind":"意見","question":"１番目のところで、単に役割というのではなくて、もう少しはっきりしておいてもらえば、内容的なものは、今言った文章の中にあるので、ここに書いたことを僕らは考えているんだよというようなふうに持っていければいいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":13,"id":"exchange-005"},{"speaker":"南委員","kind":"質問","question":"基本的にいいと思いますし、むしろ私たちの認識としては、議長会のほうの案文よりも、品川区議会の案文のほうがすぐれているんじゃないかというふうに言うことができるんじゃないかなというふうに思います。ちょっと今後の当面の活動についても触れていいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":14,"id":"exchange-006"},{"speaker":"南委員","kind":"質問","question":"４番の2)で、都議会自由民主党都区制度改革議員連盟、議員連盟役員と議長会役員との意見交換会というのがあるんですけれども、議長がおいでですし、これからやられるところなので、意見としてお伝えしていただければいいかなという思いで、意見を述べたいんですけれども、いいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-007"},{"speaker":"南委員","kind":"意見","question":"参考的に見ておりますし、ただ、これから１１月１８日に会議が開かれて、案文も含めて決議されていくというふうに承知しているんですけれども、その後の議長会としての動きということで、一つの案として出されているということを承知しながら申し上げたいんです。","respondent":"松澤議長","answer":"承っておきます。","voiceIndex":18,"id":"exchange-008"},{"speaker":"藤田委員","kind":"質問","question":"私たちの意向が全部この文面に入っていると思います。先ほど委員長が、１１月１８日の議長会を受けてと、あと正副委員長にお任せ下さいというお話があったんですが、これは議長会から各区に対して決議文なり要請文を上げてもらいたいという要請があったわけですよね。そうではないんですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":21,"id":"exchange-009"},{"speaker":"藤田委員","kind":"質問・要望","question":"分かりました。今日、議長がいらっしゃいますので、ぜひとも２３区まとまった方向で、それぞれの各区の立場でこの決議文が遂げられるようなご努力をいただきたいというふうに思っております。要望しておきますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":23,"id":"exchange-010"},{"speaker":"須藤委員","kind":"質問","question":"もう一つは、先ほど都議会のほうで、僕らが見ていると、都側寄りの考え方をやるような都議会のあり様なんですね。だから、そこであっても、本当に２３区の形をとってきているのかどうかというのを非常に懸念するところなんだけれども、そういう流れ方は、先ほどちょっと企画財政課長がお話のような進み方だけで大丈夫なのかなという懸念がちょっとあるんだけれども、いかがでしょうか。","respondent":"市岡企画財政課長","answer":"区長が決算特別委員会のときにも申し上げておりましたけれども、場合によっては、そういう本質的な課題について、平成１７年度協議で東京都の姿勢に誠意が見られないならば、これはいろいろな関係があって、そう単純にはいかないと思いますけれども、場合によっては。","voiceIndex":27,"id":"exchange-011"},{"speaker":"須藤委員","kind":"質問・要望","question":"平成１２年度の移管のときもそういう形でしっかり話をしましょうという形でスタートを切って、結局主要５課題で残されちゃったというような経緯があるので、同じような形で流れていくことを、また一つ、二つ向こうが、今言った、三位一体で云々だよというのだけやっておいて、またそれは今後の課題ですみたいな話で、次の何年後にというような話にならないとも限らないなと思っているので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-012"}]},{"id":"topic-02","title":"自治会館（仮称）の運営に関すること","agenda":"自治会館（仮称）の運営に関すること","exchanges":[{"speaker":"藤田委員","kind":"質問","question":"今ご説明がありましたが、５番、特別区沿革・観光協会・施設等紹介等ですけれども、ただ紹介だけではなくて、せっかくここまで新しく事業を起こそうとしているわけですので、１年間を通じてどういうスパンでやるのかわかりませんが、例えば品川区の地場産業、品川の特色となると、品川巻とか、せんべいみたいなのがありますね。今説明があって、気がついたものですから、いかがでしょうか。","respondent":"宮地総務課長","answer":"そういった中で、またより一層各区のＰＲ、販売も含めたものができるかどうか、こちらのほうといたしましても、意見を言う場がありましたら、伝えていきたいというふうに考えております。","voiceIndex":35,"id":"exchange-013"},{"speaker":"藤田委員","kind":"質問・要望","question":"地場産業の育成ということもありますので、各区それぞれ意識があると思うんです。ぜひとも検討をしていただきたいと、要望をしておきますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":37,"id":"exchange-014"},{"speaker":"高星委員","kind":"質問・要望","question":"だから、新たな事業というのは、こういった一つのサービスというのは、今藤田委員も言われたけれども、販売も必要なんじゃないかというような、そういうふうに考えると、どんどん事業が拡大されていくという要素があると思うんですけれども、その辺のところの流れというものが分かっていたら教えていただきたいと思います。","respondent":"宮地総務課長","answer":"そこでのさまざまな検討がありまして、さらに区長会への報告、そして、またどういうことになるかというふうに議長会への報告というふうになってまいりますが、私どもこの自治会館を所管している総務部長、総務課長の中でも一つの連絡を兼ねた会議があります。","voiceIndex":38,"id":"exchange-015"},{"speaker":"高星委員","kind":"質問・要望","question":"議長に要望するのも何ですが、議長は毎年代わってしまうじゃない。だから、この話をたどっていくと、自民党何だいというふうになっちゃうんだけれども、本当に大事だと思うので、議長、ご尽力のほうよろしくお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":40,"id":"exchange-016"}]},{"id":"topic-03","title":"続きまして、特別区人事・厚生事務組合に関すること","agenda":"続きまして、特別区人事・厚生事務組合に関すること","exchanges":[{"speaker":"須藤委員","kind":"質問","question":"いろいろ見直し制度を持ってきて、順次返ってきているんだけれども、この辺のところは２３区でいろいろなことで温度差がありますというような話があったんだけれども、こういうところに登載してくる時点では、その辺の考え方はどうなんですか。２３区全部でゴーサインでいけたのか、いろいろ問題があってこういうところで今進んできているのかというお話をお願いいたします。","respondent":"桑村人事課長","answer":"ちょっと途中で言いかけたんですが、平成１３年度から１４年度にかけて実際に実務的な検討をしました。それについては課長会を中心にやっていたわけですが、正直言って、課長会レベルでは、そういう意味では非常に温度差が激しい。","voiceIndex":46,"id":"exchange-017"},{"speaker":"須藤委員","kind":"意見","question":"７ページのところの、「今後改めて、現行の連合人事委員会制度を含め検討することが必要である」との意見も出されたというような形だけれども、この辺の考え方はどのくらいの比率というのか、重さはどの程度だったのかということを聞かせてもらいたいと思います。","respondent":"桑村人事課長","answer":"正直言いまして、これを上げたときは現行の枠組みを壊さないというのが検討会の前提でございましたので、ただ、意見としては言わせていただいているということだろうと思います。","voiceIndex":48,"id":"exchange-018"},{"speaker":"須藤委員","kind":"質問・要望","question":"その辺を聞くと、ますますこれは大変な仕事だなと危惧されるんですけれども、委員長をはじめ皆さんに頑張っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":50,"id":"exchange-019"},{"speaker":"高星委員","kind":"質問・要望","question":"調整手当は調整手当で２３区全体で見るけれども、各区においても特殊勤務手当という形の中で、それに何かして付加することもできるという具合にとれていくのか、調整手当はやめよう、全部各区の特殊勤務手当でやろうじゃないかというよう考え方とかいっぱいあると思うんですけれども、現在の段階で区長会では、清掃の今度の人事、給与の関係ではどんなふうになっているのか。","respondent":"桑村人事課長","answer":"その辺につきましても相当議論がございまして、ここに書かれているように、特殊勤務手当は各区事項ですけれども、これは実際上清掃の方を２３区で受けるというのは、じゃ、各区ばらばらで平成１８年に受けるのかということもございました。","voiceIndex":51,"id":"exchange-020"},{"speaker":"高星委員","kind":"質問","question":"だから、今の説明ですと、平成１８年４月１日からのものについては特殊勤務手当でやるという話だったというふうに思うんだけれども、４月１日で用意ドンのときはそれで共通であって、２日以降については各区によってそこに加算することもあり得る、あるいは減額することもあり得るというような考えで今動いているんですか。","respondent":"桑村人事課長","answer":"ただ、それ以降のことについては各区事項ですので、いわゆる身分切り替え時は全く同じですけれども、例えば平成１９年４月１日になって、どこかの区が特殊勤務手当の考え方を変えたとすれば、それは各区ばらばらになるです。","voiceIndex":53,"id":"exchange-021"},{"speaker":"藤田委員","kind":"質問・要望","question":"基本的なことで教えていただきたいんですが、東京都の職員であって、品川区に赴任をしたという場合に、東京都は東京都の考えのもとでやる、２３区は２３区の共通のものでやる、このギャップというのは考えられないんでしょうか。例えば給与にしても、よく東京都の皆さんが見えますね、その辺をまず教えていただきたいんです。","respondent":"桑村人事課長","answer":"あるとすれば、東京都のほうが、成績率ですとか、昇給についての一定の考え方ですとか、やってありますので、そういった制度上の違いはありますけれども、例えば全体で期末勤勉手当の何月ですとか、それから、扶養手当が幾らとか、２００円。","voiceIndex":55,"id":"exchange-022"},{"speaker":"藤田委員","kind":"質問","question":"一たん退職をされるということであれば、身分は公務員ということにつながりますから、退職手当とか、諸手当みたいなものはどういうふうになるんですか。","respondent":"桑村人事課長","answer":"これは東京都だけじゃないんですけれども、例えば神奈川県から３月３１日付で品川区に入って来たとすると、退職手当は基本的に共通になっていまして、そこの段階で払わずに、いわゆる最終的に辞めた段階で払うという規定を持っているところで、それは私ども特別区のほうも同じで。","voiceIndex":57,"id":"exchange-023"},{"speaker":"藤田委員","kind":"質問","question":"例えば東京都の職員が、２３区ではなくて、例えば一般の市に行ってしまったとか、例えば三鷹市とか、そういうところへ行っても、わずかな金額しか差がないんでしょうか。","respondent":"桑村人事課長","answer":"そこの団体との関係ですけれども、いわゆる私ども特別区というのは今までの関係もあって、東京都の課長級などはそのまま課長級でおりますけれども、市等につきましては、１段階上というんでしょうか、東京都において係長級の職員が課長になったり。","voiceIndex":59,"id":"exchange-024"},{"speaker":"藤田委員","kind":"質問","question":"もう一つ、採用のところですが、資格基準として、Ｉ類、III類、またII類の保育士とありますが、その年齢ですけれども、今、途中から公務員になりたいんだけれどもという人がかなりいらっしゃるわけですね。この辺の、もっと広げたような、いろいろな条件をつけて、そういう検討というのはされていないんでしょうか。","respondent":"桑村人事課長","answer":"もう一つは、年齢制限の撤廃を最初からやってしまうという、これは国などが検討を始めておりまして、実際に始めたところもあるようですけれども、６０歳まで、フリーでどなたでも試験がという、これは非常に高い倍率だったようですけれども、そういうふうな、時代が。","voiceIndex":61,"id":"exchange-025"},{"speaker":"藤田委員","kind":"質問","question":"その方向で考えていくべきじゃないかなというふうに思うんです。今の社会状況から見ると、そういう声が強いわけですから、そういう目で検討を加えていく必要があるんじゃないかと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-026"},{"speaker":"武内委員","kind":"意見","question":"１点だけですけれども、今こういう見直しをされていまして、職員の方とか、働きやすいような体制とか、そういうことを検討されていると思うんですけれども、区民の立場で言えば、これによってどういうメリットが出てくるのか。","respondent":"桑村人事課長","answer":"なるべくその意味での共通基準がないほうが職員にとってはやりやすい、あるいは区民にとってはサービスが向上するというような制度をつくっていけるんじゃないかというふうに考えてあります。","voiceIndex":64,"id":"exchange-027"},{"speaker":"高星委員","kind":"質問・要望","question":"〔「ありません」と呼ぶ者あり〕そうすると、例えば１８日の総会がどういうふうな中身になったのかとか、そういったことを少なくとも意見書、決議案を品川区議会から出す前に我々の委員会はないわけでしょう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-028"},{"speaker":"高星委員","kind":"質問・要望","question":"１１月１８日の総会の中身の情報があれば、いただきたいなと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-029"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5556#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=11&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":27243,"voices":75}},{"id":"h16-20041109-14","meetingId":"h16-cm11","date":"2004年11月9日","dateIso":"2004-11-09","committee":"行財政改革特別委員会","time":"午後１時０４分～午後５時１１分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件抜き出しています。","hasFullText":true,"topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=5764#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":465,"voices":4}},{"id":"h16-20041109-16","meetingId":"h16-cm11","date":"2004年11月9日","dateIso":"2004-11-09","committee":"街づくり特別委員会","time":"午後１時０６分～午後３時３８分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を19件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"飯沼委員","kind":"意見","question":"未買収であった駅前の２棟が和解をしたということで、ほっとしているわけですけれども、ちょっと答えられるところだけでいいんですが、次の第４回定例会のところにかかるかもしれないんですが、前にご説明をいただいたときに、地元の地権者は、仮の営業所と代替地の確保をしてほしいと、これが大きな願いだったと思うんですが、この辺がどうなったのかという点。","respondent":"中島街路事業担当課長","answer":"そういうことで、取得した後、東京三菱銀行の残地の一部、七、八十m2になると思うんですけれども、そのぐらいの用地を取得して、こちらで営業が継続できるものと考えています。","voiceIndex":6,"id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"そういうことでは、羊華堂のほうは移られる、浅草のほうで営業されると受けとめてよろいしんでしょうか。それから、もう１軒のほうは、当初の願いというか、目途が立ったということなので、地元で営業ができると受けとめてよろしいでしょうか。その点が１点。この辺は、買収の算定の基準があるのかどうかわからないんですが、その辺で、買収の価格とかは違うんでしょうか。","respondent":"中島街路事業担当課長","answer":"羊華堂の今後の営業の関係ですけれども、先ほど、浅草のほうにというお話をしましたけれども、もう１カ所、東急目黒線の武蔵小山駅前広場の整備の後に、東急用地が一部残るところがございまして、そちらを希望をされております。","voiceIndex":8,"id":"exchange-002"},{"speaker":"飯沼委員","kind":"質問・要望","question":"和解後、まだきちっとしていないところでは、ぜひ、最後まで区のほうで力を注いでいただきたいとお願いするのが１点。そうすると、この土地は品川区が買収して、品川区の持ち分になるわけですね。それを東急電鉄に貸す、提供するみたいな形になるわけですか。４線になって広がった部分なんですが、東急電鉄に貸していくということになるんですか。","respondent":"中島街路事業担当課長","answer":"土地につきまして、複雑な関係がございまして、先ほど申し上げました東急電鉄用地があるんですけれども、これは基本的には品川区が東急電鉄から買うことになるんですけれども、これにつきましては、連続立体交差事業の絡みで。","voiceIndex":10,"id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"もう１点なんですが、駅前広場の、きょう、大ざっぱな、前からこれしか見てないんですが、詳細な設計ができたと、それから、埋設物とかいろいろな部分で、警視庁や何かと協議中ということなんですが、その詳細な図面というのは、どのぐらい経ったら地元の方々のところに見せていただけるのかどうか。それから、意見などはどういうところで言えるのかなと思っているんですが、その辺はいかがでしょうか。","respondent":"中島街路事業担当課長","answer":"そういった意味で、基本的には、警視庁との協議がすべて整った段階で、あるいは、工事のもっと前の段階で工事説明会もありますので、さまざまな形で地元の方にお話をさせていただいて、ご意見があれば伺っていきたいと考えております。","voiceIndex":12,"id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今よりかなり広くなって、使いやすくなるとは思うんですが、ぜひ、地元の方のご意見を十分に聞く機会をつくっていただきたいなというのが１点。そうなので、できる限りその方向でお願いしたいんですが、その辺はどうなっているでしょうか。","respondent":"中島街路事業担当課長","answer":"現在、花は毎年きれいに咲いているんですけれども、相当木自体がいたんでいる部分がありますので、移植するときには地方のほうに、要するに樹木にすごく栄養分がいいところに一遍置いて、元気になった上で、適当な場所に移植をしていきたいと考えていますので。","voiceIndex":14,"id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"駐輪場が、どこに、何台分ぐらいできるのかということ。それから、今、自転車はすごくたくさんとまっていますけれども、今、何台ぐらいあるのかも教えていただきたいんです。","respondent":"中島街路事業担当課長","answer":"駐輪場のお話ですけれども、現在、事業者間で協議をしているところですけれども、武蔵小山につきましては、２枚目の資料１の図面を見ていただきますと、補助２６号線がございまして、現在、踏み切りがありますけれども、その右側を駐輪場として。","voiceIndex":16,"id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"説明会が、権利者３６名ということで、権利者８８世帯のうち、随分少ないなと思ったんですけれども、なぜこんなに少なかったのかという理由をお聞きしたい。それから、高齢者の世帯がどれぐらいあるのか、それを教えていただきたい。それからもう一つ、権利者で、ここに住んでいらっしゃらない方もいらっしゃると思うんですけれども、それが何世帯ぐらいあるのかについて、まず教えていただきたいんです。","respondent":"上野都市開発課長","answer":"権利者は８８名おられまして、普段、地元の説明会でも、出席される方は大体４０名前後の方が来られていますから、地元の権利者説明会と大体同じような方が見えておられるのかなです。","voiceIndex":23,"id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そういうところをどういうふうに考えられているかということを、ひとつ聞かせていただきたいと思います。それから、主な意見・要望でも出されているんですけれども、歩行者デッキの計画についてというところで、いろいろとこういうふうにできてくると書かれていますけれども、中地区のところにかかる部分というのはそんなに多くないのかなという感じがするんです。","respondent":"上野都市開発課長","answer":"隧道の件につきましては、当初、大崎署のほうから、現状の隧道を拡幅整備することで、歩行者と自転車の通行者の安全を確保してほしいということでしたが、全体を改修すると非常に多大な金額になるということと、支障物件が非常に多いために。","voiceIndex":25,"id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"先日の建設委員会で、車の台数がどのぐらいに増えるのかという質問のときに、西口全体で８,０００台増えると、そのうち明電舎関係が４,０００台ということでお聞きしたんですけれども、ソニーとかこちらの南地区は全然開発の計画がはっきりしていないわけですから、８,０００台というのは、明電舎と中地区だけですよね。ちょっとそこら辺のところの説明をお願いしたいと思います。","respondent":"上野都市開発課長","answer":"それを補助１６３号のほうで受けまして、考え方としては、それをまず環状６号線のほうに流すということで対応する。","voiceIndex":27,"id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"４地区で８,０００台が増えてくるということなんですけれども、では、今までは何台で、それが８,０００台に増えるのかというところを教えていただきたい。総床面積で、そこら辺のところの計算ができるということなんですけれども、ソニーとか、南地区の開発については、全く報告を受けてないんですけれども、西地区全体での延べ床面積の総面積はどれぐらいになるのかを教えていただけるでしょうか。","respondent":"上野都市開発課長","answer":"今までの台数については、別の機会にお答えいたしたいと思うんですけれども、計画の延べ床面積で、住宅についてはおおよそ１０haの規模を考えてあります。４につきましては、大体６０haぐらいでしょうか。","voiceIndex":29,"id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"すごく巨大な数字だなという感じがするんですけれども、では、合計の延べ床面積で４０haということになるわけですよね。それで、車が合わせて８,０００台に増えると。そして、人工排熱でどのぐらいの放熱になるのかというが、明電舎の部分では計算していないということを言われていたんですけれども、西口全体でどういうふうな状況になるのかというところは。","respondent":"上野都市開発課長","answer":"その算定については、特に事前に算定する、あるいはそれを報告することが義務づけられておりませんから、あらかじめ類推値として具体的に把握することはできないです。明電舎については、特段計算はされていないです。","voiceIndex":33,"id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今、こんなに地球温暖化の問題がクローズアップされているときに、やっぱり超高層のこういうビルがそういうふうな排熱を出して、それを加速させているということが指摘されているわけですから、品川区としても、やっぱりしっかりと、この中地区ではどれぐらいのＣＯ２が出て、車もこのぐらい増えて、それを解消するためにどういう対策が必要かという検討する必要があると思うんですけれども。","respondent":"上野都市開発課長","answer":"ＣＯ２につきましても、開発でどのぐらい出るかについて、大崎駅周辺についてのまちづくり連絡会の活動の一環として、チャンレジということで、どこまでできるかわかりませんけれども、検討の対象にしようかという議論はしています。","voiceIndex":35,"id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"だから、そこら辺のところは、この計画と同時に、環境対策というのも進めることが必要だと思うんですけれども、そのことをお聞かせください。それからもう一つ、補助金についてなんですけれども、補助金は７０億円弱だということで言われたんですけれども、これは国と都ということで出てくると思うんですけれども、補助金の内容というのか、そこら辺のところを教えていただきたいんです。","respondent":"上野都市開発課長","answer":"環境面につきましては、いずれにしても、開発に伴って、できる限り環境負荷を軽減する取り組みをやっていくですから、通常の開発ですと、一定の環境負荷が、定量の比較で発生することが想定されるわけですけれども、それよりもさらに一層の省エネルギー対策を行うことなどで。","voiceIndex":37,"id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"環境にできる限り配慮したということなんですが、どれぐらい環境に負荷をかけるのか、そのデータをしっかりと出して、配慮した場合に、それがどれぐらい軽減されるのかというのを出していただかないと、頑張ってやりました、しかし、これだけひどくなりましたということになってしまうので、やっぱりそこら辺のところは、データとしてしっかりと出していただきたいと思うんですが、最後に。","respondent":"上野都市開発課長","answer":"先ほど、計量的なことにつきましては、どこまで数値的なものが出せるかということについては、まちづくり連絡会で議論をしていますけれども、緑化の効果などについてもできる限り、６０ha全体でどのぐらいの効果があるのか、あるいはモデル的に。","voiceIndex":39,"id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"すみません、もうこれだけで終わります。補助金の７０億円ですけれども、国と区が半分ずつで３５億円ずつ出すということなんですけれども、今までの開発は、国と都で、区からはあまり出してこなかったと思うんですけれども、ここら辺のところの、区が出すとか、都が出すとか、そういう基準がどうなっているのか、ちょっと最後に教えていただけますか。","respondent":"上野都市開発課長","answer":"補助の仕方は、ここのところは変わってございませんで、区の再開発事業については、全体の補助対象事業のうち、３分の１が国費で、３分の１が当該自治体が負担すると。品川区の場合は、それが財調で対応するということです。市町村の事業については、都が補助する。","voiceIndex":41,"id":"exchange-015"},{"speaker":"本多副委員長","kind":"質問・要望","question":"今回の１０月２０日は、権利者を対象にした説明会ということなんですが、出席者は４３名で、うち権利者が３６名ということで、この７名は権利者の家族ということになるのか、それとも、説明者なのか、その辺をちょっと教えていただきたいんです。","respondent":"上野都市開発課長","answer":"その他、今、事業参加組合に入っている３組合の３名の方が入っているのと、それから東京都のほうからオブザーバーというのが説明会に来られましたので、合計７名ということになります。","voiceIndex":43,"id":"exchange-016"},{"speaker":"本多副委員長","kind":"質問・要望","question":"そうすると、同行者とかは発言とかができるわけですか。その辺の、権利者を対象にした説明会なんですが、その辺の線引きというか、それをちょっと教えていただきたいんです。","respondent":"上野都市開発課長","answer":"説明会そのものは権利者を対象としておりまして、権利者からのご意見を頂戴するということですから、もし権利者に同行されていた親族の方がおられるとすると、権利者の代理という形であれば、発言は可能ということになります。","voiceIndex":45,"id":"exchange-017"}]},{"id":"topic-02","title":"事件調査","agenda":"事件調査","exchanges":[{"speaker":"井上委員","kind":"質問・要望","question":"都市再生ビジョン成案ということで出されて、中間まとめが公表されて、これは決定というものなのか、これがどういうスケジュールで確定するのか、どういう性質のものなのかもよくわからないんですけれども、その辺をちょっと教えていただきたいんです。","respondent":"上野都市開発課長","answer":"この合意に基づいて、それぞれ参加されている事業者が、さらに個別の研究、あるいは事業を進めていくということを表明しているです。","voiceIndex":52,"id":"exchange-018"},{"speaker":"井上委員","kind":"質問","question":"これは、こういう形づくったものという目標であるので、もうどこかでこれを決定するとかという話ではない、これに基づいて個別の計画が決定されていくということですか。〔「そうです」と呼ぶ者あり〕 わかりました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":54,"id":"exchange-019"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=6288#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2004-01-01&TermEnd=2004-12-31"}],"sourceMeta":{"pages":0,"characters":16396,"voices":58}}]);
